_PRJ_BLOCK_PRECISION_TOLERANCE_M = 1.0

# Absolute, in metres. A ring's closing vertex is a literal repeat of its first,
# so it matches to float noise -- 1 mm is orders of magnitude below the spacing
# of any real surveyed vertex. This MUST NOT be scaled by coordinate magnitude:
# doing so (mag * 1e-6) yields 4.4 m on UTM northings, which silently deletes a
# genuine final vertex from any ring that happens to close within 4.4 m of its
# start. That truncation desynchronised a block's vertex count from its PRJ
# twin, so _polygon_alignment_error returned inf, that one block alone missed
# PRJ precision correction, and the edge it shared with its neighbour stopped
# being coincident -- drawing the shared boundary as two separate lines.
_CLOSING_VERTEX_TOL_M = 1e-3


def _qt_object_is_alive(obj) -> bool:
    if obj is None:
        return False
    if _qt_is_valid is not None:
        try:
            return bool(_qt_is_valid(obj))
        except Exception:
            return False
    try:
        obj.metaObject()
        return True
    except Exception:
        return False

_ARC_SEGMENTS:    int = 32
_CIRCLE_SEGMENTS: int = 36

# ─────────────────────────────────────────────────────────────────────────────
# SBM FILE PARSER
# ─────────────────────────────────────────────────────────────────────────────

def parse_sbm_file(filepath: str) -> List[Dict]:
    """
    Parse a .sbm menu file and return a list of category dicts:

        [
            {
                "title": "Building",           # MAIN_MENU label
                "menu_index": 1,               # which SUB_MENU it maps to
                "subclasses": [
                    {
                        "label":    "BUILDING",
                        "lv":       "BUILDING",
                        "co":       1,
                        "wt":       1,
                        "collect":  "SHAPE",   # SHAPE | STRINGS | points | ""
                        "rgb":      (255, 0, 0),
                    },
                    ...
                ],
            },
            ...
        ]
    """
    import re

    raw = Path(filepath).read_text(encoding="utf-8", errors="replace")
    lines = raw.splitlines()

    # ── 1. parse MAIN_MENU entries  (one per 'B,N' line) ──────────────────
    #  'Building', 'B,1', line /nosave
    main_re = re.compile(r"'([^']+)'\s*,\s*'B\s*,\s*(\d+)'", re.IGNORECASE)
    main_entries: List[Tuple[str, int]] = []  # (label, sub_menu_index)
    in_main = False
    for line in lines:
        stripped = line.strip()
        if stripped.upper().startswith("MAIN_MENU"):
            in_main = True
            continue
        if stripped.upper().startswith("SUB_MENU"):
            in_main = False
        if in_main:
            m = main_re.search(stripped)
            if m:
                main_entries.append((m.group(1), int(m.group(2))))

    # ── 2. parse SUB_MENU blocks ───────────────────────────────────────────
    #  SUB_MENU title=1, ...
    #  'BUILDING' 'LEVEL CREATE="BUILDING";LV=BUILDING;CO=1;WT=1;COLLECT SHAPE'
    sub_title_re  = re.compile(r"SUB_MENU\s+title\s*=\s*(\d+)", re.IGNORECASE)
    entry_re      = re.compile(
        r"'([^']+)'\s+'LEVEL\s+CREATE\s*=\s*\"[^\"]*\"[^']*'",
        re.IGNORECASE,
    )
    lv_re      = re.compile(r"LV\s*=\s*([^;'\"]+)", re.IGNORECASE)
    co_re      = re.compile(r"CO\s*=\s*(\d+)",      re.IGNORECASE)
    wt_re      = re.compile(r"WT\s*=\s*(\d+)",      re.IGNORECASE)
    collect_re = re.compile(r"COLLECT\s+(\S+)",      re.IGNORECASE)

    sub_menus: Dict[int, List[Dict]] = {}
    current_sub: Optional[int] = None
    subclass_count = 0

    for line in lines:
        stripped = line.strip()
        tm = sub_title_re.search(stripped)
        if tm:
            current_sub = int(tm.group(1))
            sub_menus.setdefault(current_sub, [])
            continue
        if current_sub is None:
            continue
        em = entry_re.search(stripped)
        if not em:
            continue
        label = em.group(1).strip()
        rest  = stripped

        lv_m      = lv_re.search(rest)
        co_m      = co_re.search(rest)
        wt_m      = wt_re.search(rest)
        collect_m = collect_re.search(rest)

        lv      = lv_m.group(1).strip()      if lv_m      else label
        co      = int(co_m.group(1))         if co_m      else 7
        wt      = int(wt_m.group(1))         if wt_m      else 1
        collect = collect_m.group(1).upper() if collect_m  else ""

        # Generate a beautiful, unique color using golden ratio hue distribution
        # Unconditional assignment guarantees zero repetition among subclasses.
        import colorsys
        h = (subclass_count * 0.618033988749895) % 1.0
        # Optimal parameters for black canvas: value = 0.98 (very bright),
        # saturation = 0.72 (vibrant but with enough light/white mix to make blue/purple highly visible)
        s = 0.72
        v = 0.98
        r_val, g_val, b_val = colorsys.hsv_to_rgb(h, s, v)
        rgb = (int(r_val * 255), int(g_val * 255), int(b_val * 255))
        subclass_count += 1

        sub_menus[current_sub].append({
            "label":   label,
            "lv":      lv,
            "co":      co,
            "wt":      wt,
            "collect": collect,
            "rgb":     rgb,
        })

    # ── 3. merge into category list ────────────────────────────────────────
    categories: List[Dict] = []
    for cat_label, sub_idx in main_entries:
        categories.append({
            "title":      cat_label,
            "menu_index": sub_idx,
            "subclasses": sub_menus.get(sub_idx, []),
        })

    return categories


# Structural/metadata layers that MUST always be rendered regardless of the
# user's layer-visibility selection (e.g. "BL" for block boundary polygons,
# "FileNames"/"BLOCKS"/"FeatureAttribs" for file-name / grid-label text).
# Any layer whose upper-cased name contains one of these tokens is treated as
# a system layer and bypasses the selected_layers filter in both the entity
# rendering pipeline and the actor-visibility toggle.
_SYSTEM_LAYER_TOKENS: frozenset = frozenset({
    "BL", "FILENAMES", "BLOCKS", "FEATUREATTRIBS", "BLOCK_LABEL",
    "BLOCKLABEL", "FILENAME",
})

def _is_system_layer(layer_name: str) -> bool:
    """Return True if this layer carries structural SNT metadata that must
    always stay visible (block outlines, file-name labels, etc.)."""
    upper = str(layer_name or "").strip().upper()
    if upper in _SYSTEM_LAYER_TOKENS:
        return True
    return any(tok in upper for tok in _SYSTEM_LAYER_TOKENS)


def _snt_point_in_polygon_2d(px: float, py: float, polygon: list) -> bool:
    """Ray casting 2D point-in-polygon test (XY plane)."""
    n = len(polygon)
    inside = False
    j = n - 1
    for i in range(n):
        xi, yi = polygon[i][0], polygon[i][1]
        xj, yj = polygon[j][0], polygon[j][1]
        if ((yi > py) != (yj > py)) and (px < (xj - xi) * (py - yi) / ((yj - yi) or 1e-12) + xi):
            inside = not inside
        j = i
    return inside


def _snt_polygon_bbox_2d(polygon) -> Optional[Tuple[float, float, float, float]]:
    """Return finite XY bounds for a polygon without allocating a NumPy array."""
    if not polygon:
        return None
    min_x = float("inf")
    min_y = float("inf")
    max_x = float("-inf")
    max_y = float("-inf")
    found = False
    for point in polygon:
        try:
            x = float(point[0])
            y = float(point[1])
        except (TypeError, ValueError, IndexError):
            continue
        if not math.isfinite(x) or not math.isfinite(y):
            continue
        found = True
        if x < min_x:
            min_x = x
        if x > max_x:
            max_x = x
        if y < min_y:
            min_y = y
        if y > max_y:
            max_y = y
    if not found:
        return None
    return (min_x, min_y, max_x, max_y)


def _choose_snt_spatial_cell_size(polygon_records, default: float = 1000.0) -> float:
    """Choose a stable grid size from the median block extent."""
    spans = []
    for record in polygon_records or []:
        try:
            polygon = record[0]
        except Exception:
            polygon = record
        bounds = _snt_polygon_bbox_2d(polygon)
        if bounds is None:
            continue
        min_x, min_y, max_x, max_y = bounds
        span = max(max_x - min_x, max_y - min_y)
        if math.isfinite(span) and span > 0.0:
            spans.append(float(span))
    if not spans:
        return max(1.0, float(default))
    try:
        value = float(np.median(np.asarray(spans, dtype=np.float64)))
    except Exception:
        value = float(default)
    if not math.isfinite(value) or value <= 0.0:
        value = float(default)
    return max(1.0, value)


def _build_snt_point_spatial_index(entries, cell_size: float):
    """Build an order-preserving point grid for tuples beginning with X/Y."""
    cell_size = max(1e-9, float(cell_size))
    buckets = defaultdict(list)
    valid_count = 0
    source_entries = entries or []
    for order, entry in enumerate(source_entries):
        try:
            x = float(entry[0])
            y = float(entry[1])
        except (TypeError, ValueError, IndexError):
            continue
        if not math.isfinite(x) or not math.isfinite(y):
            continue
        key = (math.floor(x / cell_size), math.floor(y / cell_size))
        buckets[key].append((order, entry))
        valid_count += 1
    return {
        "cell_size": cell_size,
        "buckets": buckets,
        "entries": source_entries,
        "valid_count": valid_count,
    }


def _query_snt_point_spatial_index(index, polygon):
    """Return bbox-local point entries in the exact original source order."""
    if not index:
        return []
    entries = index.get("entries") or []
    if not entries:
        return []
    bounds = _snt_polygon_bbox_2d(polygon)
    if bounds is None:
        return entries
    min_x, min_y, max_x, max_y = bounds
    cell_size = float(index.get("cell_size") or 1.0)
    ix0 = math.floor(min_x / cell_size)
    ix1 = math.floor(max_x / cell_size)
    iy0 = math.floor(min_y / cell_size)
    iy1 = math.floor(max_y / cell_size)
    nx = ix1 - ix0 + 1
    ny = iy1 - iy0 + 1
    if nx <= 0 or ny <= 0 or nx * ny > 16384:
        return entries
    candidates = []
    buckets = index.get("buckets") or {}
    for ix in range(ix0, ix1 + 1):
        for iy in range(iy0, iy1 + 1):
            candidates.extend(buckets.get((ix, iy), ()))
    if not candidates:
        return []
    candidates.sort(key=lambda item: item[0])
    return [entry for _order, entry in candidates]


def _snt_polygon_centroid_2d(polygon: list) -> Tuple[float, float]:
    if not polygon:
        return (0.0, 0.0)
    return (
        sum(float(p[0]) for p in polygon) / len(polygon),
        sum(float(p[1]) for p in polygon) / len(polygon),
    )


def _snt_polygon_interior_point(polygon: list) -> Tuple[float, float]:
    """Return a point that is reliably inside the polygon, even for thin diagonal strips.

    TerraScan block polygons are often long narrow strip shapes (flight-line corridors).
    Their arithmetic centroid frequently falls *outside* the boundary, which causes
    both PRJ-stage-1 (SNT centroid vs PRJ poly) and PRJ-stage-2 (PRJ centroid vs SNT
    poly) to fail, leaving the polygon matched only by the text-label fallback.

    Strategy: try midpoints between vertex i and its mirror vertex (n-1-i).
    For a two-sided strip polygon these midpoints land on the interior spine.
    Falls back to the simple centroid for convex polygons (where it works fine).
    """
    if not polygon:
        return (0.0, 0.0)
    n = len(polygon)
    half = n // 2
    for i in range(1, half):
        j = n - 1 - i
        if j <= i:
            break
        mx = (polygon[i][0] + polygon[j][0]) / 2.0
        my = (polygon[i][1] + polygon[j][1]) / 2.0
        if _snt_point_in_polygon_2d(mx, my, polygon):
            return (mx, my)
    # Fallback: simple centroid (correct for convex/compact polygons)
    return _snt_polygon_centroid_2d(polygon)


def _normalized_delivery_project_stem(filename: str) -> str:
    """Return a conservative project identity for classified SNT copies."""
    stem = Path(str(filename)).stem.strip()
    return re.sub(
        r"(?:[ _-]+class(?:ification)?(?:[ _-]*\d+)?)$",
        "",
        stem,
        flags=re.IGNORECASE,
    ).strip(" _-").casefold()


def _parse_snt_adjacent_prj_blocks(snt_filename: str) -> List[Dict[str, object]]:
    """Read block geometry from an unambiguous adjacent PRJ."""
    try:
        snt_path = Path(str(snt_filename))
        if not snt_path.is_absolute() or not snt_path.exists():
            return []
        primary_prj = snt_path.with_suffix(".prj")
        prj_candidates = [primary_prj, Path(f"{primary_prj}.bak")]

        # Some deliveries use independent SNT and PRJ names. Preserve the
        # standard same-stem priority, but accept a differently named PRJ only
        # when the folder contains exactly one, so association is unambiguous.
        if not primary_prj.exists():
            adjacent_prjs = [
                path for path in snt_path.parent.glob("*.prj")
                if path.is_file()
            ]
            matching_prjs = [
                path for path in adjacent_prjs
                if _normalized_delivery_project_stem(path.name)
                == _normalized_delivery_project_stem(snt_path.name)
            ]
            fallback_prj = None
            if len(matching_prjs) == 1:
                fallback_prj = matching_prjs[0]
                print(
                    f"[SNT block polygons] Matched classified SNT "
                    f"'{snt_path.name}' to PRJ '{fallback_prj.name}'"
                )
            elif len(adjacent_prjs) == 1:
                fallback_prj = adjacent_prjs[0]

            if fallback_prj is not None:
                prj_candidates.extend(
                    [fallback_prj, Path(f"{fallback_prj}.bak")]
                )
                print(
                    f"[SNT block polygons] Using adjacent PRJ "
                    f"'{fallback_prj.name}' for SNT '{snt_path.name}'"
                )
            elif len(adjacent_prjs) > 1:
                print(
                    f"[SNT block polygons] No same-name PRJ for "
                    f"'{snt_path.name}'; {len(adjacent_prjs)} adjacent PRJs "
                    "are ambiguous"
                )

        for prj_path in prj_candidates:
            if not prj_path.exists():
                continue

            with open(prj_path, "r", encoding="utf-8", errors="ignore") as f:
                lines = f.readlines()

            blocks: List[Dict[str, object]] = []
            i = 0
            while i < len(lines):
                line = lines[i].strip()
                if not line.startswith("Block "):
                    i += 1
                    continue

                block_file = line.replace("Block ", "", 1).strip()
                block_label = block_file
                for ext in (".laz", ".las", ".LAZ", ".LAS"):
                    if block_label.endswith(ext):
                        block_label = block_label[:-len(ext)]
                        break

                coords: List[Tuple[float, float]] = []
                j = i + 1
                while j < len(lines):
                    coord_line = lines[j].strip()
                    if coord_line.startswith("Block "):
                        break
                    if coord_line and "=" not in coord_line:
                        parts = coord_line.split()
                        if len(parts) >= 2:
                            try:
                                coords.append((float(parts[0]), float(parts[1])))
                            except ValueError:
                                pass
                    j += 1

                if len(coords) >= 2 and coords[0] == coords[-1]:
                    coords = coords[:-1]

                file_path = None
                for ext in (".laz", ".las", ".LAZ", ".LAS"):
                    candidate = prj_path.parent / f"{block_label}{ext}"
                    if candidate.exists():
                        file_path = str(candidate)
                        break

                if len(coords) >= 3:
                    blocks.append({
                        "label": block_label,
                        "block_file": block_file,
                        "points_2d": coords,
                        "file_path": file_path,
                        "prj_path": str(prj_path),
                    })
                i = j

            if blocks:
                source_kind = (
                    "backup"
                    if prj_path.name.lower().endswith(".prj.bak")
                    else "primary"
                )
                print(
                    f"[SNT block polygons] PRJ authority loaded: {len(blocks)} blocks "
                    f"from {prj_path.name} ({source_kind})"
                )
                return blocks
        return []
    except Exception as exc:
        print(f"[SNT block polygons] PRJ authority skipped: {exc}")
        return []


def _scale_snt_source_entities_in_place(entities, scale: float):
    """Scale SNT geometry entities in-place before actors are generated."""
    if not math.isfinite(scale) or scale <= 0.0 or math.isclose(scale, 1.0, rel_tol=0.0, abs_tol=1e-12):
        return
    seen_ids = set()
    for ent in entities:
        if not isinstance(ent, dict):
            continue
        for vkey in ("vertices", "points"):
            vlist = ent.get(vkey)
            if isinstance(vlist, list) and id(vlist) not in seen_ids:
                seen_ids.add(id(vlist))
                for i in range(len(vlist)):
                    p = vlist[i]
                    if len(p) >= 3:
                        vlist[i] = (p[0] * scale, p[1] * scale, p[2] * scale)
                    elif len(p) == 2:
                        vlist[i] = (p[0] * scale, p[1] * scale)
        blist = ent.get("boundaries")
        if isinstance(blist, list) and id(blist) not in seen_ids:
            seen_ids.add(id(blist))
            for b in blist:
                if isinstance(b, list) and id(b) not in seen_ids:
                    seen_ids.add(id(b))
                    for i in range(len(b)):
                        p = b[i]
                        if len(p) >= 3:
                            b[i] = (p[0] * scale, p[1] * scale, p[2] * scale)
                        elif len(p) == 2:
                            b[i] = (p[0] * scale, p[1] * scale)
        pos = ent.get("position")
        if isinstance(pos, (tuple, list)):
            if len(pos) >= 3:
                ent["position"] = (pos[0] * scale, pos[1] * scale, pos[2] * scale)
            elif len(pos) == 2:
                ent["position"] = (pos[0] * scale, pos[1] * scale)
        h = ent.get("height")
        if h is not None:
            try:
                ent["height"] = float(h) * scale
            except (TypeError, ValueError):
                pass


def _infer_snt_coordinate_scale(snt_bounds, prj_blocks) -> float:
    """Infer coordinate scale factor between SNT bounds and PRJ blocks."""
    if not snt_bounds or not prj_blocks:
        return 1.0
    try:
        sx0, sx1, sy0, sy1 = float(snt_bounds[0]), float(snt_bounds[1]), float(snt_bounds[2]), float(snt_bounds[3])
        s_cx = (sx0 + sx1) / 2.0
        s_cy = (sy0 + sy1) / 2.0
        s_span_x = abs(sx1 - sx0)
        s_span_y = abs(sy1 - sy0)

        all_pts = [p for b in prj_blocks for p in b.get("points_2d", [])]
        if not all_pts:
            return 1.0
        px0 = min(p[0] for p in all_pts)
        px1 = max(p[0] for p in all_pts)
        py0 = min(p[1] for p in all_pts)
        py1 = max(p[1] for p in all_pts)
        p_cx = (px0 + px1) / 2.0
        p_cy = (py0 + py1) / 2.0
        p_span_x = abs(px1 - px0)
        p_span_y = abs(py1 - py0)

        candidates = [1.0, 0.1, 10.0, 0.01, 100.0, 0.001, 1000.0]
        best_scale = 1.0
        min_error = float("inf")

        for s in candidates:
            sc_x0, sc_x1 = sx0 * s, sx1 * s
            sc_y0, sc_y1 = sy0 * s, sy1 * s
            if sc_x0 > sc_x1:
                sc_x0, sc_x1 = sc_x1, sc_x0
            if sc_y0 > sc_y1:
                sc_y0, sc_y1 = sc_y1, sc_y0

            overlap_x = max(0.0, min(sc_x1, px1) - max(sc_x0, px0))
            overlap_y = max(0.0, min(sc_y1, py1) - max(sc_y0, py0))
            if overlap_x > 0 and overlap_y > 0:
                center_dist = math.hypot((s_cx * s) - p_cx, (s_cy * s) - p_cy)
                span_ratio_x = (s_span_x * s) / (p_span_x + 1e-9)
                span_ratio_y = (s_span_y * s) / (p_span_y + 1e-9)
                if 0.1 <= span_ratio_x <= 10.0 and 0.1 <= span_ratio_y <= 10.0:
                    if center_dist < min_error:
                        min_error = center_dist
                        best_scale = s

        return best_scale
    except Exception:
        return 1.0


