# snt_attachment.py, replace _open_polygon_xy body
def _open_polygon_xy(points) -> np.ndarray:
    """Return finite XY vertices without a duplicate closing point."""
    clean = []
    source_points = [] if points is None else points
    for point in source_points:
        try:
            x = float(point[0])
            y = float(point[1])
        except (IndexError, TypeError, ValueError):
            continue
        if np.isfinite(x) and np.isfinite(y):
            clean.append((x, y))
    polygon = np.asarray(clean, dtype=np.float64)
    if len(polygon) >= 2:
        if np.allclose(polygon[0], polygon[-1],
                       atol=_CLOSING_VERTEX_TOL_M, rtol=0.0):
            polygon = polygon[:-1]
    return polygon

def _is_closed_block_polygon_entity(entity: Dict) -> bool:
    """Return True only for entities that actually represent closed polygons."""
    if not isinstance(entity, dict):
        return False

    entity_type = str(entity.get("type", "")).strip().lower()
    if entity_type not in ("line", "polyline", "lwpolyline", "polygon"):
        return False

    raw_points = entity.get("points") or entity.get("vertices") or []
    polygon = _open_polygon_xy(raw_points)
    if len(polygon) < 3:
        return False

    if entity_type == "polygon" or bool(entity.get("closed", False)):
        return True

    try:
        first = raw_points[0]
        last = raw_points[-1]
        if first is None or last is None or len(first) < 2 or len(last) < 2:
            return False
        return (
            abs(float(first[0]) - float(last[0])) <= _CLOSING_VERTEX_TOL_M
            and abs(float(first[1]) - float(last[1])) <= _CLOSING_VERTEX_TOL_M
        )
    except Exception:
        return False


def _is_block_boundary_layer_name(layer_name: str) -> bool:
    layer_u = str(layer_name or "").strip().upper()
    return (
        layer_u.startswith("BL")
        or layer_u.startswith("BL_")
        or layer_u.endswith("_BL")
        or "BLOCK" in layer_u
        or "GRID" in layer_u
        or "TILE" in layer_u
        or "BBOX" in layer_u
        or "BOUND" in layer_u
    )


def _is_known_block_boundary_layer(layer_name: str, attachment=None) -> bool:
    """Check name heuristic AND the tracked block boundary role in attachment state."""
    if _is_block_boundary_layer_name(layer_name):
        return True
    if attachment is not None:
        state = attachment.get("_snt_direct_changes")
        if isinstance(state, dict):
            blk_set = state.get("block_boundary_layers")
            if isinstance(blk_set, set) and layer_name in blk_set:
                return True
    return False


def _snt_poly_matches_prj_block(points_2d, prj_blocks, prj_spatial_index) -> bool:
    """Return True if a closed polygon's geometry corresponds to a PRJ tile.

    This is completely independent of the layer name, so it works after a
    block boundary layer has been renamed and the SNT re-opened.
    """
    if not prj_blocks or len(points_2d) < 3:
        return False
    cx, cy = _snt_polygon_interior_point(points_2d)
    for block in _nearby_prj_blocks(points_2d, prj_blocks, prj_spatial_index):
        prj_poly = block.get("points_2d") or []
        if len(prj_poly) < 3:
            continue
        if _snt_point_in_polygon_2d(cx, cy, prj_poly):
            return True
        pcx, pcy = _snt_polygon_interior_point(prj_poly)
        if _snt_point_in_polygon_2d(pcx, pcy, points_2d):
            return True
    return False


_DEFAULT_PLACEHOLDER_BLOCK_LEVELS = frozenset({
    "NEW LEVEL",
    "NEW LEVEL (0)",
})


def _normalise_snt_level_name(layer_name: str) -> str:
    """
    Normalize a MicroStation/SNT level name without regex.

    Examples:
        " New   Level "   -> "NEW LEVEL"
        "new level (0)"   -> "NEW LEVEL (0)"
    """
    return " ".join(
        str(layer_name or "").strip().upper().split()
    )


def _is_default_placeholder_block_level(layer_name: str) -> bool:
    """
    Return True only for the known MicroStation placeholder levels.

    This must remain separate from _is_block_boundary_layer_name().
    Globally treating every 'New Level' entity as a block boundary would
    incorrectly classify unrelated default-level polygons in other SNT files.
    """
    return (
        _normalise_snt_level_name(layer_name)
        in _DEFAULT_PLACEHOLDER_BLOCK_LEVELS
    )


def _is_bbox_index_level(layer_name: str) -> bool:
    """
    Identify small SNT index-tile polygons.

    BBOX geometry is retained only as a final legacy fallback.
    """
    return "BBOX" in _normalise_snt_level_name(layer_name)


def _lidar_label_keys(text: str) -> Tuple[str, ...]:
    """
    Produce exact case-insensitive lookup keys for a label.

    No partial-number matching is performed.

    Examples:
        LAVARONE000002
            -> ("lavarone000002",)

        LAVARONE000002.laz
            -> ("lavarone000002.laz", "lavarone000002")
    """
    raw_name = Path(str(text or "").strip()).name
    if not raw_name:
        return ()

    suffix = Path(raw_name).suffix.casefold()
    stem = (
        Path(raw_name).stem
        if suffix in {".laz", ".las"}
        else raw_name
    )

    # Preserve order while removing duplicate keys.
    return tuple(
        dict.fromkeys((
            raw_name.casefold(),
            stem.casefold(),
        ))
    )

def _float32_polygon_uncertainty(points) -> float:
    """Return the worst-case XY half-ULP for float32 world coordinates."""
    polygon = _open_polygon_xy(points)
    if len(polygon) < 3:
        return 0.0
    magnitudes = np.max(np.abs(polygon), axis=0).astype(np.float32)
    half_steps = np.abs(np.spacing(magnitudes).astype(np.float64)) * 0.5
    uncertainty = float(np.hypot(half_steps[0], half_steps[1]))
    return uncertainty if np.isfinite(uncertainty) else 0.0


def _buffer_polygon_for_quantization(points, distance: float) -> np.ndarray:
    """Expand a valid polygon by its coordinate uncertainty."""
    polygon = _open_polygon_xy(points)
    if len(polygon) < 3 or not np.isfinite(distance) or distance <= 0.0:
        return polygon
    try:
        from shapely.geometry import Polygon

        geometry = Polygon(polygon)
        if geometry.is_empty or not geometry.is_valid or geometry.area <= 0.0:
            return polygon
        buffered = geometry.buffer(float(distance), join_style=2)
        if buffered.is_empty or buffered.geom_type != "Polygon":
            return polygon
        buffered_xy = np.asarray(buffered.exterior.coords[:-1], dtype=np.float64)
        return buffered_xy if len(buffered_xy) >= 3 else polygon
    except Exception as exc:
        print(f"[SNT precision] Quantization buffer skipped: {exc}")
        return polygon


def _polygon_alignment_error(points, reference_points) -> float:
    """Return the best cyclic/reversed maximum vertex error in metres."""
    polygon = _open_polygon_xy(points)
    reference = _open_polygon_xy(reference_points)
    if len(polygon) < 3 or len(polygon) != len(reference):
        return float("inf")

    best = float("inf")
    for candidate in (reference, reference[::-1]):
        for shift in range(len(candidate)):
            aligned = np.roll(candidate, shift, axis=0)
            error = float(np.linalg.norm(polygon - aligned, axis=1).max(initial=0.0))
            if error < best:
                best = error
    return best


def _build_prj_spatial_index(prj_blocks):
    """Build a lightweight centroid grid for fast local PRJ matching."""
    records = []
    spans = []
    for block in prj_blocks or []:
        points = _open_polygon_xy(block.get("points_2d") or [])
        if len(points) < 3:
            continue
        min_x, min_y = points.min(axis=0)
        max_x, max_y = points.max(axis=0)
        records.append((block, 0.5 * (min_x + max_x), 0.5 * (min_y + max_y)))
        span = max(float(max_x - min_x), float(max_y - min_y))
        if span > 0.0:
            spans.append(span)

    cell_size = max(1.0, float(np.median(spans)) if spans else 1000.0)
    buckets = defaultdict(list)
    for block, center_x, center_y in records:
        key = (math.floor(center_x / cell_size), math.floor(center_y / cell_size))
        buckets[key].append(block)
    if records:
        centers_x = [record[1] for record in records]
        centers_y = [record[2] for record in records]
        center_bounds = (
            min(centers_x), min(centers_y), max(centers_x), max(centers_y)
        )
    else:
        center_bounds = None
    return {"cell_size": cell_size, "buckets": buckets,
            "center_bounds": center_bounds}


def _nearby_prj_blocks(poly_points, prj_blocks, spatial_index=None):
    """Return local PRJ candidates, preserving a full-scan safety fallback."""
    if not spatial_index:
        return prj_blocks or []
    points = _open_polygon_xy(poly_points)
    if len(points) < 3:
        return prj_blocks or []
    center_x, center_y = points.mean(axis=0)
    cell_size = spatial_index["cell_size"]
    center_bounds = spatial_index.get("center_bounds")
    if center_bounds is not None:
        min_x, min_y, max_x, max_y = center_bounds
        margin = 2.0 * cell_size
        if not (min_x - margin <= center_x <= max_x + margin
                and min_y - margin <= center_y <= max_y + margin):
            # A full scan cannot find a spatial match when SNT and PRJ are in
            # grossly different unit spaces. Avoid quadratic work on legacy
            # mis-scaled files.
            return []
    base_x = math.floor(float(center_x) / cell_size)
    base_y = math.floor(float(center_y) / cell_size)
    candidates = []
    for dx in (-1, 0, 1):
        for dy in (-1, 0, 1):
            candidates.extend(spatial_index["buckets"].get((base_x + dx, base_y + dy), []))
    return candidates if candidates else (prj_blocks or [])


def _find_precision_prj_block(
    poly_points,
    prj_blocks,
    used_labels=None,
    spatial_index=None,
):
    """Match only equivalent SNT/PRJ polygons; never replace a different shape."""
    best_block = None
    best_error = float("inf")
    used_labels = used_labels or set()
    candidates = _nearby_prj_blocks(poly_points, prj_blocks, spatial_index)
    for block in candidates:
        label = str(block.get("label") or "")
        if label and label in used_labels:
            continue
        error = _polygon_alignment_error(poly_points, block.get("points_2d") or [])
        if error < best_error:
            best_error = error
            best_block = block
    if best_block is None or best_error > _PRJ_BLOCK_PRECISION_TOLERANCE_M:
        return None, best_error
    return best_block, best_error


def _apply_prj_precision_to_block_entities(
    entities,
    prj_blocks,
    *,
    snt_uses_float64: bool = False,
):
    """Return render-only block copies using the best available precision."""
    # Fast path: files without any block-boundary layer cannot be affected
    # by PRJ matching or float32 quantization buffering (both apply only to
    # block lines). Scanning 1M+ entities with numpy per polygon just to
    # discover that would dominate Attach time, so check distinct layer
    # names first and return the input unchanged.
    distinct_layers = set()
    truncated = True
    try:
        distinct_layers = set()
        truncated = False
        for _ent in entities or []:
            if isinstance(_ent, dict):
                _ln = _ent.get("layer", "0")
                try:
                    distinct_layers.add(str(_ln))
                except Exception:
                    pass
                if len(distinct_layers) > 4096:
                    truncated = True
                    break
        if not truncated and not any(
            _is_block_boundary_layer_name(_ln) and "BBOX" not in str(_ln).strip().upper()
            for _ln in distinct_layers
        ):
            return list(entities) if isinstance(entities, list) else (entities or [])
    except Exception:
        pass
    corrected = []
    # The layer name decides eligibility. Resolve it once per distinct layer,
    # before normalizing entity types or testing polygon geometry.
    boundary_layers = {
        name for name in distinct_layers
        if _is_block_boundary_layer_name(name) and "BBOX" not in name.strip().upper()
    } if not truncated else None
    used_labels = set()
    prj_corrected_count = 0
    quantization_corrected_count = 0
    prj_spatial_index = _build_prj_spatial_index(prj_blocks)

    for entity in entities or []:
        if not isinstance(entity, dict):
            corrected.append(entity)
            continue

        if boundary_layers is not None and str(entity.get("layer", "0")) not in boundary_layers:
            corrected.append(entity)
            continue

        entity_type = str(entity.get("type", "")).strip().lower()
        layer_u = str(entity.get("layer", "")).strip().upper()
        is_block_line = (
            entity_type in ("line", "polyline", "lwpolyline", "polygon")
            and _is_block_boundary_layer_name(layer_u)
            and "BBOX" not in layer_u
        )
        if not is_block_line:
            corrected.append(entity)
            continue

        if not _is_closed_block_polygon_entity(entity):
            corrected.append(entity)
            continue

        original_points = entity.get("points") or entity.get("vertices") or []
        block, error = _find_precision_prj_block(
            original_points,
            prj_blocks,
            used_labels,
            prj_spatial_index,
        )
        source_xy = _open_polygon_xy(original_points)
        if len(source_xy) < 3:
            corrected.append(entity)
            continue

        uncertainty = (
            0.0 if snt_uses_float64 else _float32_polygon_uncertainty(source_xy)
        )
        precise_points = (
            _open_polygon_xy(block.get("points_2d") or [])
            if block is not None
            else source_xy
        )
        if len(precise_points) < 3:
            precise_points = source_xy

        meaningful_prj_delta = max(1e-6, uncertainty * 0.05)
        use_exact_prj = block is not None and (
            snt_uses_float64 or error > meaningful_prj_delta
        )

        quantization_applied = False
        output_points = precise_points
        if not use_exact_prj and uncertainty > 0.0:
            buffered_points = _buffer_polygon_for_quantization(
                precise_points,
                uncertainty,
            )
            same_geometry = (
                len(buffered_points) == len(precise_points)
                and np.allclose(
                    buffered_points,
                    precise_points,
                    atol=1e-12,
                    rtol=0.0,
                )
            )
            if not same_geometry:
                output_points = buffered_points
                quantization_applied = True

        if not use_exact_prj and not quantization_applied:
            # Preserve the PRJ match as metadata so the later block-index pass
            # can reuse this exact result instead of matching the same polygon
            # a second time. Geometry remains unchanged.
            if block is not None:
                entity_copy = dict(entity)
                entity_copy["_prj_block_label"] = str(block.get("label") or "")
                entity_copy["_prj_alignment_error_m"] = float(error)
                corrected.append(entity_copy)
                label = str(block.get("label") or "")
                if label:
                    used_labels.add(label)
            else:
                corrected.append(entity)
            continue

        entity_copy = dict(entity)
        default_z = 0.0
        if original_points:
            try:
                default_z = float(original_points[0][2])
            except (IndexError, TypeError, ValueError):
                pass
        entity_copy["points"] = [
            (float(x), float(y), default_z) for x, y in output_points
        ]
        entity_copy["closed"] = True
        entity_copy["_boundary_precision_corrected"] = True
        if block is not None:
            entity_copy["_prj_block_label"] = str(block.get("label") or "")
            entity_copy["_prj_alignment_error_m"] = float(error)
        if use_exact_prj:
            entity_copy["_prj_precision_corrected"] = True
            prj_corrected_count += 1
        if quantization_applied:
            entity_copy["_snt_quantization_buffer_m"] = float(uncertainty)
            quantization_corrected_count += 1
        corrected.append(entity_copy)

        if block is not None:
            label = str(block.get("label") or "")
            if label:
                used_labels.add(label)

    if prj_corrected_count:
        print(
            f"[SNT precision] Rendered {prj_corrected_count} matched block polygon(s) "
            f"from exact PRJ coordinates"
        )
    if quantization_corrected_count:
        print(
            f"[SNT precision] Expanded {quantization_corrected_count} float32 "
            f"block polygon(s) by their coordinate half-ULP"
        )
    return corrected


def _coordinate_shape(seq) -> Optional[Tuple[int, int]]:
    """Return ``(point_count, component_count)`` for a coordinate sequence."""
    try:
        count = len(seq)
    except TypeError:
        return None
    if count == 0:
        return None
    try:
        components = len(seq[0])
    except TypeError:
        return None
    if components < 2:
        return None
    return count, components


def _slot_sequence(entity, key, ring_index):
    if key == "boundaries":
        return entity["boundaries"][ring_index]
    return entity.get(key)


def _transform_slot_block(slots, entities, out, source_crs, canvas_crs, totals):
    """Transform one bounded block of coordinate sequences in a few PROJ calls."""
    from gui.projection_engine import transform_points

    buffers = {
        components: np.empty((total, components), dtype=np.float64)
        for components, total in totals.items()
    }
    offsets = {components: 0 for components in buffers}
    starts = [0] * len(slots)
    failed = set()

    for local, slot in enumerate(slots):
        index, key, ring_index, count, components = slot
        sequence = _slot_sequence(entities[index], key, ring_index)
        start = offsets[components]
        starts[local] = start
        try:
            buffers[components][start:start + count] = np.asarray(
                sequence, dtype=np.float64
            )
        except Exception:
            failed.add(local)
        offsets[components] = start + count

    for components, buffer in buffers.items():
        if buffer.size:
            transform_points(
                buffer, source_crs, canvas_crs, copy=False,
                chunk_size=max(1, len(buffer)),
            )

    for local, slot in enumerate(slots):
        if local in failed:
            continue
        index, key, ring_index, count, components = slot
        buffer = buffers[components]
        start = starts[local]
        values = [tuple(row) for row in buffer[start:start + count].tolist()]
        if key == "boundaries":
            out[index]["boundaries"][ring_index] = values
        elif key in ("position", "center", "insert"):
            out[index][key] = values[0]
        else:
            out[index][key] = values


def _reproject_entities_for_render(
    entities,
    source_crs,
    canvas_crs,
    *,
    chunk_points: int = 1_000_000,
):
    """Return canvas-space copies of ``entities`` using batched transforms.

    Transforming per entity rebuilt a PROJ ``TransformerGroup`` for every single
    feature, which for a multi-million feature SNT took hours of blocked GUI
    thread.  Every coordinate sequence is gathered here and transformed in a few
    vectorised calls instead; the resulting geometry is identical.
    """
    entities = list(entities or [])
    if source_crs is None or canvas_crs is None:
        return entities
    try:
        if source_crs.equals(canvas_crs):
            return entities
    except Exception:
        pass

    out = [dict(e) if isinstance(e, dict) else e for e in entities]

    # (output index, field, boundary ring index, point count, component count)
    slots: List[Tuple[int, str, Optional[int], int, int]] = []
    for index, entity in enumerate(entities):
        if not isinstance(entity, dict):
            continue
        for key in ("points", "vertices"):
            shape = _coordinate_shape(entity.get(key))
            if shape is not None:
                slots.append((index, key, None, shape[0], shape[1]))
        boundaries = entity.get("boundaries")
        if isinstance(boundaries, list):
            rings = []
            for ring_index, ring in enumerate(boundaries):
                if not isinstance(ring, list):
                    continue
                shape = _coordinate_shape(ring)
                if shape is not None:
                    rings.append((ring_index, shape))
            if rings:
                # Copy-on-write: the source entity must keep its native rings.
                out[index]["boundaries"] = list(boundaries)
                for ring_index, (count, components) in rings:
                    slots.append((index, "boundaries", ring_index, count, components))
        for key in ("position", "center", "insert"):
            position = entity.get(key)
            if isinstance(position, (tuple, list)) and len(position) >= 2:
                shape = _coordinate_shape([position])
                if shape is not None:
                    slots.append((index, key, None, shape[0], shape[1]))

    if not slots:
        return out

    cursor = 0
    while cursor < len(slots):
        end = cursor
        totals: Dict[int, int] = {}
        total_points = 0
        while end < len(slots):
            count, components = slots[end][3], slots[end][4]
            if end > cursor and total_points + count > chunk_points:
                break
            totals[components] = totals.get(components, 0) + count
            total_points += count
            end += 1
        try:
            _transform_slot_block(
                slots[cursor:end], entities, out, source_crs, canvas_crs, totals
            )
        except Exception as exc:
            print(f"[SNT CRS] coordinate transform failed: {exc}")
            return out
        cursor = end
    return out


def build_snt_block_polygons(
    app,
    entities: list,
    snt_filename: str,
    prj_blocks=None,
    attachment=None,
    progress_cb=None,
) -> None:
    """Extract BL-layer block polygons and associate each with a grid label for click-inside-block detection.

    Text labels that are file names reside on the 'FileNames' layer (promoted from FeatureAttribs).
    We prefer those over generic text so the block click uses the correct LAZ file name.
    """
    import time as _time
    _perf_t0 = _time.perf_counter()
    _perf_stage_t0 = _perf_t0

    if not hasattr(app, 'snt_block_polygons'):
        app.snt_block_polygons = []
    # BBOX index tiles (the labelled square grid cells) kept for Grid area
    # measurement only; snt_block_polygons stays the block index.
    app.snt_grid_tiles = [
        tile for tile in (getattr(app, 'snt_grid_tiles', None) or [])
        if tile.get("snt_filename") != snt_filename
    ]

    app.snt_block_polygons = [
        bp for bp in app.snt_block_polygons 
        if bp.get("snt_filename") != snt_filename
    ]

    # Real named block boundaries.
    explicit_block_polys: list = []

    # Possible real boundaries stored on MicroStation's default level.
    placeholder_polys: list = []

    # Small index tiles. These are used only when no real blocks exist.
    bbox_index_polys: list = []

    # Closed polygons that matched no name heuristic. Used for rename-safe
    # geometric recovery of the block boundary layer (see PRJ matching below).
    unrouted_closed_polys: list = []

    # Gate-passed (layer, etype, entity) references whose vertices are NOT
    # collected during the scan. Materialized into unrouted_closed_polys
    # below, and only when a downstream consumer can actually use them —
    # otherwise 250k+ building polygons would each pay a float conversion
    # for data that is never used.
    # NOTE (diagnostic-only edge): gate-time level counts assume a
    # gate-passed polygon also survives vertex collection. That holds for
    # all decoder-produced geometry; only corrupt input (non-finite or
    # ragged vertices that collection would drop below 3 points) can leave
    # the printed per-level count higher than a full re-verification.
    unrouted_pending: list = []
    _pending_per_layer: Dict[str, int] = {}

    # Diagnostic count of every level containing a closed polygon.
    polygon_level_counts: Dict[str, int] = {}

    # Separate filename labels from generic text.
    filename_text: list = []   # (x, y, text)
    other_text: list = []      # (x, y, text)
    text_by_layer: Dict[str, list] = {}

    def _collect_poly_points_2d(
        ent: Dict,
    ) -> List[Tuple[float, float]]:
        src = ent.get("points") or ent.get("vertices") or []
        out: List[Tuple[float, float]] = []

        for pt in src:
            try:
                if pt is None or len(pt) < 2:
                    continue

                x = float(pt[0])
                y = float(pt[1])

                if not np.isfinite(x) or not np.isfinite(y):
                    continue

                out.append((x, y))
            except (TypeError, ValueError, IndexError):
                continue

        if len(out) >= 2:
            x0, y0 = out[0]
            x1, y1 = out[-1]

            if abs(x0 - x1) <= 1e-9 and abs(y0 - y1) <= 1e-9:
                out = out[:-1]

        return out

    def _raw_closed_gate(ent: Dict, poly_etype: str) -> bool:
        """Cheap closed-polygon gate on raw first/last vertices only.

        No vertex conversion: entities with fewer than 3 raw points, or an
        open ring (and no explicit closed flag), are rejected before any
        float()/numpy work happens.
        """
        try:
            src = ent.get("points") or ent.get("vertices") or []
            if len(src) < 3:
                return False
        except TypeError:
            return False
        if poly_etype == "polygon":
            return True
        try:
            if bool(ent.get("closed", False)):
                return True
        except Exception:
            pass
        try:
            first, last = src[0], src[-1]
            if first is None or last is None or len(first) < 2 or len(last) < 2:
                return False
            return (
                abs(float(first[0]) - float(last[0])) <= _CLOSING_VERTEX_TOL_M
                and abs(float(first[1]) - float(last[1])) <= _CLOSING_VERTEX_TOL_M
            )
        except Exception:
            return False

    def _closed_poly_points_2d_fast(ent: Dict, poly_etype: str):
        """Fused closed-polygon point collection (single float pass).

        Equivalent to ``_collect_poly_points_2d`` + len>=3 +
        ``_is_closed_block_polygon_entity`` combined, but converts each
        vertex exactly once. Returns the 2D point list, or None when the
        entity is not a valid closed polygon.
        """
        if not _raw_closed_gate(ent, poly_etype):
            return None
        points_2d = _collect_poly_points_2d(ent)
        if len(points_2d) < 3:
            return None
        return points_2d

    _level_norm_cache: Dict[str, str] = {}
    _known_boundary_cache: Dict[str, bool] = {}

    def _norm_level_cached(name: str) -> str:
        try:
            return _level_norm_cache[name]
        except KeyError:
            pass
        norm = _normalise_snt_level_name(name)
        if len(_level_norm_cache) < 32768:
            _level_norm_cache[name] = norm
        return norm

    def _is_known_boundary_cached(name: str) -> bool:
        # Per-level memo of _is_known_block_boundary_layer. Safe to cache for
        # the scan: this loop only ever ADDS the already-True layer itself to
        # the tracked set, so a False verdict can never flip mid-scan.
        try:
            return _known_boundary_cache[name]
        except KeyError:
            pass
        verdict = bool(_is_known_block_boundary_layer(name, attachment))
        if len(_known_boundary_cache) < 32768:
            _known_boundary_cache[name] = verdict
        return verdict

    def _count_closed_level(name: str) -> None:
        key = name or "<blank>"
        polygon_level_counts[key] = polygon_level_counts.get(key, 0) + 1

    def _uncount_closed_level(name: str) -> None:
        # Compensate a gate-time count when lazy materialization later
        # proves the polygon degenerate (all vertices non-finite). Corrupt
        # data only; keeps the diagnostic identical otherwise.
        key = name or "<blank>"
        try:
            if polygon_level_counts.get(key, 0) > 0:
                polygon_level_counts[key] -= 1
        except Exception:
            pass

    # ------------------------------------------------------------------
    # Build an exact local LAZ/LAS filename index.
    # ------------------------------------------------------------------
    try:
        owner_dir = Path(str(snt_filename)).expanduser().parent
    except Exception:
        owner_dir = Path(".")

    lidar_roots = [
        owner_dir,
        owner_dir / "lazz",
        owner_dir / "LAZZ",
        owner_dir / "laz",
        owner_dir / "LAZ",
        owner_dir / "las",
        owner_dir / "LAS",
    ]

    # A None value means the key was ambiguous and must not be accepted.
    lidar_file_index: Dict[str, Optional[Path]] = {}
    missing_key = object()

    def _index_lidar_key(key: str, file_path: Path) -> None:
        if not key:
            return

        previous = lidar_file_index.get(key, missing_key)

        if previous is missing_key:
            lidar_file_index[key] = file_path
            return

        if previous is None:
            return

        if str(previous).casefold() != str(file_path).casefold():
            # Never guess when two files produce the same lookup key.
            lidar_file_index[key] = None

    seen_files: Set[str] = set()

    for root in lidar_roots:
        try:
            if not root.is_dir():
                continue

            for file_path in root.iterdir():
                if not file_path.is_file():
                    continue

                if file_path.suffix.casefold() not in {".laz", ".las"}:
                    continue

                path_key = str(file_path).casefold()
                if path_key in seen_files:
                    continue
                seen_files.add(path_key)

                _index_lidar_key(
                    file_path.name.casefold(),
                    file_path,
                )
                _index_lidar_key(
                    file_path.stem.casefold(),
                    file_path,
                )

        except OSError as exc:
            print(
                f"[SNT block polygons] Could not scan LiDAR folder "
                f"'{root}': {exc}"
            )

    def _resolve_lidar_label(text: str) -> Optional[Path]:
        """
        Resolve a text label only when it identifies exactly one real file.
        """
        matches: Dict[str, Path] = {}

        for key in _lidar_label_keys(text):
            file_path = lidar_file_index.get(key)

            if isinstance(file_path, Path):
                matches[str(file_path).casefold()] = file_path

        if len(matches) != 1:
            return None

        return next(iter(matches.values()))

    # ------------------------------------------------------------------
    # Separate real blocks, placeholder-level candidates and BBOX tiles.
    # ------------------------------------------------------------------
    _scan_idx = 0
    _scan_total = len(entities) if isinstance(entities, list) else 0
    for entity in entities:
        _scan_idx += 1
        if progress_cb is not None and (_scan_idx & 0x3FFFF) == 0:
            # Every ~256k entities: keep the progress dialog alive.
            try:
                progress_cb(f"indexing block boundaries... {_scan_idx:,}/{_scan_total:,}")
            except Exception:
                pass
            try:
                from PySide6.QtCore import QCoreApplication as _QCA
                _QCA.processEvents()
            except Exception:
                pass
        if not isinstance(entity, dict):
            continue

        etype = str(entity.get("type", "")).strip().lower()
        layer = str(entity.get("layer", "")).strip()

        if etype in (
            "line",
            "polyline",
            "lwpolyline",
            "polygon",
        ):
            # Route on the (cached) normalized level name BEFORE touching any
            # vertex. Open contour polylines — the vast majority on files like
            # N4_BLOCK_932 — are rejected by the raw closed gate without a
            # single float conversion. Unrouted layers only record a (layer,
            # entity) reference here; their vertices are materialized later,
            # and only if the PRJ geometric recovery path actually triggers.
            normalized_layer = _norm_level_cached(layer)
            if "BBOX" in normalized_layer:
                points_2d = _closed_poly_points_2d_fast(entity, etype)
                if points_2d is None:
                    continue
                _count_closed_level(layer)
                bbox_index_polys.append((points_2d, layer, entity))
            elif _is_known_boundary_cached(layer):
                points_2d = _closed_poly_points_2d_fast(entity, etype)
                if points_2d is None:
                    continue
                _count_closed_level(layer)
                explicit_block_polys.append((points_2d, layer, entity))
                # Record this layer as a known block boundary for future renames
                if attachment is not None:
                    _blk_state = attachment.get("_snt_direct_changes")
                    if isinstance(_blk_state, dict):
                        _blk_set = _blk_state.get("block_boundary_layers")
                        if isinstance(_blk_set, set):
                            _blk_set.add(layer)
            elif normalized_layer in _DEFAULT_PLACEHOLDER_BLOCK_LEVELS:
                points_2d = _closed_poly_points_2d_fast(entity, etype)
                if points_2d is None:
                    continue
                _count_closed_level(layer)
                placeholder_polys.append((points_2d, layer, entity))
            elif _raw_closed_gate(entity, etype):
                _count_closed_level(layer)
                unrouted_pending.append((layer, etype, entity))
                _pending_per_layer[layer] = _pending_per_layer.get(layer, 0) + 1

            continue

        if etype == "text":
            pos = entity.get("position", (0.0, 0.0, 0.0))
            text_value = str(entity.get("text", "")).strip()

            try:
                if not text_value or len(pos) < 2:
                    continue

                entry = (
                    float(pos[0]),
                    float(pos[1]),
                    text_value,
                )
            except (TypeError, ValueError, IndexError):
                continue

            text_by_layer.setdefault(layer, []).append(entry)

            if (
                normalized_layer == "FILENAMES"
                or _is_block_label_layer(layer, text_value)
                or _is_known_block_boundary_layer(layer, attachment)
            ):
                filename_text.append(entry)
            else:
                other_text.append(entry)

    # ------------------------------------------------------------------
    # Build spatial indices once. Previously every block scanned every text
    # label with a Python point-in-polygon test. On large SNTs this becomes
    # O(blocks * labels * vertices) and dominates attachment time. The index
    # only narrows candidates by bbox; the exact containment test is unchanged.
    # ------------------------------------------------------------------
    _all_closed_records = (
        explicit_block_polys
        + placeholder_polys
        + bbox_index_polys
        + unrouted_closed_polys
    )
    _text_cell_size = _choose_snt_spatial_cell_size(
        _all_closed_records,
        1000.0,
    )
    _filename_text_index = _build_snt_point_spatial_index(
        filename_text,
        _text_cell_size,
    )
    _other_text_index = _build_snt_point_spatial_index(
        other_text,
        _text_cell_size,
    )
    _text_layer_indexes: Dict[str, object] = {}

    def _text_candidates_for_layer(layer_name: str, polygon):
        entries = text_by_layer.get(layer_name, [])
        if not entries:
            return []
        index = _text_layer_indexes.get(layer_name)
        if index is None:
            index = _build_snt_point_spatial_index(entries, _text_cell_size)
            _text_layer_indexes[layer_name] = index
        return _query_snt_point_spatial_index(index, polygon)

    _perf_entity_scan_ms = (_time.perf_counter() - _perf_stage_t0) * 1000.0
    _perf_stage_t0 = _time.perf_counter()

    # ------------------------------------------------------------------
    # Resolve only those default-level polygons that contain a text label
    # corresponding to a real physical LAZ/LAS file.
    # ------------------------------------------------------------------
    resolved_file_labels = []

    for tx, ty, text_value in filename_text + other_text:
        resolved_path = _resolve_lidar_label(text_value)

        if resolved_path is not None:
            resolved_file_labels.append((
                tx,
                ty,
                text_value,
                resolved_path,
            ))

    _resolved_file_label_index = _build_snt_point_spatial_index(
        resolved_file_labels,
        _text_cell_size,
    )

    qualified_placeholder_polys: list = []

    for points_2d, layer, entity in placeholder_polys:
        resolved_text = None
        resolved_path = None

        for tx, ty, text_value, file_path in _query_snt_point_spatial_index(
            _resolved_file_label_index,
            points_2d,
        ):
            if _snt_point_in_polygon_2d(
                tx,
                ty,
                points_2d,
            ):
                resolved_text = text_value
                resolved_path = file_path
                break

        if resolved_path is None:
            # An unrelated polygon on New Level must not become a block.
            continue

        tagged_entity = dict(entity)
        tagged_entity["_default_block_level_fallback"] = True
        tagged_entity["_resolved_block_label"] = resolved_path.stem
        tagged_entity["_resolved_block_text"] = resolved_text
        tagged_entity["_resolved_block_file_path"] = str(
            resolved_path
        )

        qualified_placeholder_polys.append((
            points_2d,
            layer,
            tagged_entity,
        ))

    # ------------------------------------------------------------------
    # Rename-safe recovery: identify the block boundary layer geometrically.
    # After a layer is renamed and the SNT re-opened, neither the name
    # heuristic nor any cached role survives, but the block polygons still
    # coincide with the PRJ tiles. Match the unrouted closed polygons against
    # the PRJ spatial index to recover the correct block layer regardless of
    # its (possibly renamed) name.
    # ------------------------------------------------------------------
    if prj_blocks is None:
        prj_blocks = _parse_snt_adjacent_prj_blocks(snt_filename)
    prj_spatial_index = _build_prj_spatial_index(prj_blocks)
    _prj_by_label = {
        str(block.get("label") or "").strip().casefold(): block
        for block in (prj_blocks or [])
        if str(block.get("label") or "").strip()
    }

    _perf_preindex_ms = (_time.perf_counter() - _perf_stage_t0) * 1000.0
    _perf_stage_t0 = _time.perf_counter()

    # Lazy materialization: unrouted vertices are collected only when a
    # downstream consumer can actually use them —
    #   (a) PRJ geometric recovery (no explicit boundaries + PRJ present), or
    #   (b) labeled-grid recovery, which needs >=4 same-layer polys on a
    #       layer that also carries text labels.
    # Otherwise the pending references are dropped unconverted. Both gates
    # are exact: skipped layers provably contribute nothing.
    _prj_recovery_armed = bool(
        not explicit_block_polys and unrouted_pending and prj_blocks
    )
    # _pending_per_layer was tallied during the scan loop above.
    _grid_recovery_layers = {
        lyr
        for lyr, n in _pending_per_layer.items()
        if n >= 4 and text_by_layer.get(lyr)
    }
    if _prj_recovery_armed or _grid_recovery_layers:
        for _lyr, _et, _ent in unrouted_pending:
            if not _prj_recovery_armed and _lyr not in _grid_recovery_layers:
                continue
            _pts = _closed_poly_points_2d_fast(_ent, _et)
            if _pts is None:
                _uncount_closed_level(_lyr)
                continue
            unrouted_closed_polys.append((_pts, _lyr, _ent))

    if not explicit_block_polys and unrouted_closed_polys and prj_blocks:
        _layer_match: Dict[str, int] = {}
        _layer_total: Dict[str, int] = {}
        for _pts, _lyr, _ent in unrouted_closed_polys:
            _layer_total[_lyr] = _layer_total.get(_lyr, 0) + 1
            if _snt_poly_matches_prj_block(_pts, prj_blocks, prj_spatial_index):
                _layer_match[_lyr] = _layer_match.get(_lyr, 0) + 1
        _best_layer = None
        _best_count = 0
        for _lyr, _c in _layer_match.items():
            if _c > _best_count:
                _best_count = _c
                _best_layer = _lyr
        if _best_layer is not None and _best_count >= max(
            1, int(0.5 * _layer_total.get(_best_layer, 0))
        ):
            for _pts, _lyr, _ent in unrouted_closed_polys:
                if _lyr == _best_layer:
                    explicit_block_polys.append((_pts, _lyr, _ent))
                    if attachment is not None:
                        _bk = attachment.get("_snt_direct_changes")
                        if isinstance(_bk, dict):
                            _bs = _bk.get("block_boundary_layers")
                            if isinstance(_bs, set):
                                _bs.add(_lyr)

    # ------------------------------------------------------------------
    # Priority:
    #   1. Proper named boundaries
    #   2. Validated New Level boundaries
    #   3. BBOX tiles only as a final legacy fallback
    #
    # Therefore this LAVARONE file stores 3 real blocks, not 80 BBOX tiles.
    # ------------------------------------------------------------------
    if explicit_block_polys or qualified_placeholder_polys:
        bl_polys = (
            explicit_block_polys
            + qualified_placeholder_polys
        )
        selected_reason = (
            "named/validated-default block boundaries"
        )
    else:
        bl_polys = bbox_index_polys
        selected_reason = "BBOX legacy fallback"

    level_summary = ", ".join(
        f"{level!r}={count}"
        for level, count in sorted(
            polygon_level_counts.items(),
            key=lambda item: item[0].casefold(),
        )
    ) or "<none>"

    print(
        f"[SNT block polygons] Closed polygon levels: "
        f"{level_summary}"
    )
    print(
        "[SNT block polygons] Candidate selection: "
        f"explicit={len(explicit_block_polys)}, "
        f"default={len(placeholder_polys)}, "
        f"default-resolved={len(qualified_placeholder_polys)}, "
        f"bbox={len(bbox_index_polys)}, "
        f"selected={len(bl_polys)} "
        f"via {selected_reason}"
    )
    print(
        f"[SNT block polygons] {snt_filename}: "
        f"{len(bl_polys)} selected block polygons, "
        f"{len(filename_text)} FileNames labels, "
        f"{len(other_text)} other text"
    )

    used_prj_labels: Set[str] = set()
    used_precision_labels: Set[str] = set()
    _prj_match_count = 0
    _prj_direct_metadata_hits = 0
    _verbose_prj_matches = os.getenv(
        "NAKSHA_SNT_VERBOSE_BLOCK_MATCH",
        "0",
    ).strip().lower() in {"1", "true", "yes", "on"}

    for poly_pts, poly_layer, poly_entity in bl_polys:
        grid_name = None
        file_path = None
        prj_block = None
        precision_prj_block = None
        alt_names = []
        is_default_level_fallback = bool(
            poly_entity.get("_default_block_level_fallback")
        )

        fallback_grid_name = str(
            poly_entity.get("_resolved_block_label") or ""
        ).strip() or None

        fallback_text = str(
            poly_entity.get("_resolved_block_text") or ""
        ).strip() or None

        fallback_file_path = str(
            poly_entity.get("_resolved_block_file_path") or ""
        ).strip() or None

        poly_layer_u = poly_layer.upper()
        is_grid_poly = (
            is_default_level_fallback
            or "GRID" in poly_layer_u
            or "TILE" in poly_layer_u
            or "BBOX" in poly_layer_u
            or "BOUND" in poly_layer_u
        )

        is_precision_block_poly = (
            (
                is_default_level_fallback
                or poly_layer_u.startswith("BL")
                or "BLOCK" in poly_layer_u
            )
            and "BBOX" not in poly_layer_u
        )

        _pre_matched_label = str(
            poly_entity.get("_prj_block_label") or ""
        ).strip()
        if _pre_matched_label:
            _candidate = _prj_by_label.get(_pre_matched_label.casefold())
            if _candidate is not None:
                prj_block = _candidate
                precision_prj_block = _candidate
                _prj_direct_metadata_hits += 1

        if (
            prj_blocks
            and is_precision_block_poly
            and precision_prj_block is None
        ):
            precision_prj_block, _ = _find_precision_prj_block(
                poly_pts,
                prj_blocks,
                used_precision_labels,
                prj_spatial_index,
            )
            if precision_prj_block is not None:
                precision_label = str(precision_prj_block.get("label") or "")
                if precision_label:
                    used_precision_labels.add(precision_label)

        if prj_blocks:
            if prj_block is None:
                cx, cy = _snt_polygon_interior_point(poly_pts)
                nearby_blocks = _nearby_prj_blocks(
                    poly_pts, prj_blocks, prj_spatial_index
                )
                for block in nearby_blocks:
                    label = str(block.get("label") or "")
                    if label in used_prj_labels:
                        continue
                    prj_poly = block.get("points_2d") or []
                    if len(prj_poly) >= 3 and _snt_point_in_polygon_2d(cx, cy, prj_poly):
                        prj_block = block
                        break
                if prj_block is None:
                    best_score = None
                    for block in nearby_blocks:
                        label = str(block.get("label") or "")
                        if label in used_prj_labels:
                            continue
                        prj_poly = block.get("points_2d") or []
                        if len(prj_poly) < 3:
                            continue
                        pcx, pcy = _snt_polygon_interior_point(prj_poly)
                        if not _snt_point_in_polygon_2d(pcx, pcy, poly_pts):
                            continue
                        score = (pcx - cx) * (pcx - cx) + (pcy - cy) * (pcy - cy)
                        if best_score is None or score < best_score:
                            best_score = score
                            prj_block = block
            if prj_block is not None:
                grid_name = str(prj_block.get("label") or "").strip() or None
                file_path = prj_block.get("file_path")
                if grid_name:
                    if grid_name in used_prj_labels and _pre_matched_label:
                        # Defensive duplicate guard; preserve the old one-label
                        # per polygon behavior rather than accepting a stale tag.
                        prj_block = None
                        precision_prj_block = None
                        grid_name = None
                        file_path = None
                    else:
                        used_prj_labels.add(grid_name)
                        _prj_match_count += 1
                        if _verbose_prj_matches:
                            print(
                                f"[SNT block polygons] PRJ matched BL polygon -> "
                                f"{grid_name}"
                            )
        # For a validated default-level boundary, the local physical file
        # is authoritative. Do not allow an unrelated DV-style tile label
        # or PRJ alias to replace LAVARONE000002.
        if (
            is_default_level_fallback
            and fallback_file_path
        ):
            physical_grid_name = (
                fallback_grid_name
                or Path(fallback_file_path).stem
            )

            if (
                grid_name
                and grid_name != physical_grid_name
                and grid_name not in alt_names
            ):
                alt_names.append(grid_name)

            if (
                fallback_text
                and fallback_text != physical_grid_name
                and fallback_text not in alt_names
            ):
                alt_names.append(fallback_text)

            grid_name = physical_grid_name
            file_path = fallback_file_path

        # Collect ALL text labels inside polygon as alternative names for
        # fallback matching, but only test bbox-local candidates. The point-in-
        # polygon test and source ordering remain identical to the old path.
        for tx, ty, tval in _query_snt_point_spatial_index(
            _filename_text_index,
            poly_pts,
        ):
            if _snt_point_in_polygon_2d(tx, ty, poly_pts):
                if grid_name is None:
                    grid_name = tval
                elif tval != grid_name:
                    alt_names.append(tval)

        # IMPORTANT: exclude raw .laz/.las tile-reference text strings for normal blocks
        if grid_name is None:
            for tx, ty, tval in _query_snt_point_spatial_index(
                _other_text_index,
                poly_pts,
            ):
                tval_lo = tval.strip().lower()
                if (tval_lo.endswith(".laz") or tval_lo.endswith(".las")) and not is_grid_poly:
                    continue
                if _snt_point_in_polygon_2d(tx, ty, poly_pts):
                    grid_name = tval
                    break
        else:
            for tx, ty, tval in _query_snt_point_spatial_index(
                _other_text_index,
                poly_pts,
            ):
                tval_lo = tval.strip().lower()
                if (tval_lo.endswith(".laz") or tval_lo.endswith(".las")) and not is_grid_poly:
                    continue
                if _snt_point_in_polygon_2d(tx, ty, poly_pts) and tval != grid_name:
                    alt_names.append(tval)

        stored_poly_pts = poly_pts
        has_quantization_buffer = bool(
            poly_entity.get("_snt_quantization_buffer_m")
        )
        if precision_prj_block is not None and not has_quantization_buffer:
            precise_xy = _open_polygon_xy(precision_prj_block.get("points_2d") or [])
            if len(precise_xy) >= 3:
                stored_poly_pts = [(float(x), float(y)) for x, y in precise_xy]
        # Remove empty, duplicate and primary-name alternatives.
        alt_names = list(dict.fromkeys(
            str(name).strip()
            for name in alt_names
            if str(name or "").strip()
            and str(name).strip() != grid_name
        ))

        if prj_block is not None:
            resolved_block_file = str(
                prj_block.get("block_file") or ""
            )
        elif file_path:
            resolved_block_file = Path(
                str(file_path)
            ).name
        else:
            resolved_block_file = ""
        app.snt_block_polygons.append({
            "points_2d": stored_poly_pts,
            "grid_name": grid_name,
            "block_file": resolved_block_file,
            "alt_names": alt_names,
            "file_path": (
                str(file_path)
                if file_path
                else None
            ),
            "source": (
                "snt_default_level"
                if is_default_level_fallback
                else (
                    "snt_grid"
                    if is_grid_poly
                    else (
                        "prj"
                        if prj_block is not None
                        else "snt_text"
                    )
                )
            ),
            "snt_filename": snt_filename,
            "poly_layer": poly_layer,
        })

    # Recover grids stored on ordinary CAD levels (including level "0").
    # A repeated set of closed polygons with exactly one unique same-level
    # label per polygon is an unambiguous grid even when the level name does
    # not contain GRID/TILE/BBOX/BOUND.
    labeled_grids_by_layer: Dict[str, list] = {}
    for poly_pts, poly_layer, _poly_entity in unrouted_closed_polys:
        contained_labels = [
            text_value
            for tx, ty, text_value in _text_candidates_for_layer(
                poly_layer,
                poly_pts,
            )
            if _snt_point_in_polygon_2d(tx, ty, poly_pts)
        ]
        if len(contained_labels) == 1 and contained_labels[0].strip():
            labeled_grids_by_layer.setdefault(poly_layer, []).append(
                (poly_pts, contained_labels[0].strip())
            )

    recovered_grid_count = 0
    for poly_layer, labeled_polys in labeled_grids_by_layer.items():
        if len(labeled_polys) < 4:
            continue
        labels = [label.casefold() for _points, label in labeled_polys]
        if len(set(labels)) != len(labels):
            continue
        for poly_pts, grid_name in labeled_polys:
            app.snt_block_polygons.append({
                "points_2d": poly_pts,
                "grid_name": grid_name,
                "block_file": "",
                "alt_names": [],
                "file_path": None,
                "source": "snt_grid",
                "snt_filename": snt_filename,
                "poly_layer": poly_layer,
            })
            recovered_grid_count += 1

    if recovered_grid_count:
        print(
            f"[SNT block polygons] recovered {recovered_grid_count} labeled "
            "grid cell(s) from non-standard level names"
        )

    # Classified/edited SNT exports may contain no grid polygons, or only a few
    # incidental polygons that spatially match unrelated PRJ tiles. The PRJ is
    # the authoritative complete grid/file index, so merge every distinct PRJ
    # block instead of using it only when the SNT selection is completely empty.
    if prj_blocks:
        prj_names = {
            str(block.get("label") or "").strip().casefold()
            for block in prj_blocks
            if str(block.get("label") or "").strip()
        }
        # Replace any approximate/incidental SNT entry carrying a PRJ label;
        # the PRJ boundary and its direct source path are authoritative.
        app.snt_block_polygons = [
            entry for entry in app.snt_block_polygons
            if not (
                entry.get("snt_filename") == snt_filename
                and str(entry.get("grid_name") or "").strip().casefold() in prj_names
            )
        ]
        indexed_prj_names = set()
        retained_prj_count = 0
        for block in prj_blocks:
            points_xy = _open_polygon_xy(block.get("points_2d") or [])
            grid_name = str(block.get("label") or "").strip()
            if len(points_xy) < 3 or not grid_name:
                continue
            normalized_grid_name = grid_name.casefold()
            if normalized_grid_name in indexed_prj_names:
                continue

            block_file = str(block.get("block_file") or "").strip()
            alt_names = []
            if block_file:
                block_file_stem = Path(block_file).stem
                if block_file_stem and block_file_stem.casefold() != grid_name.casefold():
                    alt_names.append(block_file_stem)

            app.snt_block_polygons.append({
                "points_2d": [(float(x), float(y)) for x, y in points_xy],
                "grid_name": grid_name,
                "block_file": block_file,
                "alt_names": alt_names,
                "file_path": (
                    str(block.get("file_path"))
                    if block.get("file_path")
                    else None
                ),
                "source": "prj_authority",
                "snt_filename": snt_filename,
                "prj_path": block.get("prj_path"),
                "poly_layer": "PRJ",
            })
            indexed_prj_names.add(normalized_grid_name)
            retained_prj_count += 1

        print(
            f"[SNT block polygons] retained {retained_prj_count} distinct "
            f"PRJ authority block(s) alongside {len(bl_polys)} SNT polygon(s)"
        )

    # When real blocks win the selection above, the BBOX tiles are dropped
    # from the block index - but they are still the square grid cells the
    # user sees. Keep them (with their same-level label) for Grid area.
    if bl_polys is not bbox_index_polys:
        for tile_number, (poly_pts, poly_layer, _entity) in enumerate(bbox_index_polys, 1):
            labels = [
                text_value
                for tx, ty, text_value in _text_candidates_for_layer(poly_layer, poly_pts)
                if str(text_value or "").strip()
                and _snt_point_in_polygon_2d(tx, ty, poly_pts)
            ]
            app.snt_grid_tiles.append({
                "points_2d": [(float(x), float(y)) for x, y in poly_pts],
                "grid_name": labels[0].strip() if labels else f"{poly_layer} #{tile_number}",
                "source": "snt_bbox",
                "snt_filename": snt_filename,
                "poly_layer": poly_layer,
            })
        if bbox_index_polys:
            print(f"[SNT block polygons] kept {len(bbox_index_polys)} BBOX grid tile(s) "
                  "for grid area measurement")

    stored_for_owner = [
        block for block in app.snt_block_polygons
        if block.get("snt_filename") == snt_filename
    ]

    _perf_match_ms = (_time.perf_counter() - _perf_stage_t0) * 1000.0
    _perf_total_ms = (_time.perf_counter() - _perf_t0) * 1000.0
    if _prj_match_count:
        print(
            f"[SNT block polygons] PRJ matched {_prj_match_count} SNT polygon(s) "
            f"(metadata fast-path={_prj_direct_metadata_hits})"
        )
    print(
        f"[SNT block polygons] stored {len(stored_for_owner)} block entries "
        f"({sum(1 for block in stored_for_owner if block.get('grid_name'))} with grid_name)"
    )
    print(
        f"[SNT block polygons] PERF entity/index={_perf_entity_scan_ms:.1f}ms "
        f"preindex/placeholder={_perf_preindex_ms:.1f}ms "
        f"match/store={_perf_match_ms:.1f}ms "
        f"total={_perf_total_ms:.1f}ms "
        f"text_cell={_text_cell_size:.1f}m"
    )

def _aci_to_rgb(aci: int, cycle_idx: int = 0) -> Tuple[int, int, int]:
    if aci in _INVISIBLE_ACI:
        return _LAYER_COLOR_CYCLE[cycle_idx % len(_LAYER_COLOR_CYCLE)]
    if aci in _ACI_RGB:
        return _ACI_RGB[aci]
    return _LAYER_COLOR_CYCLE[aci % len(_LAYER_COLOR_CYCLE)]


def _normalise_vtk_color(color: Tuple[int, int, int]) -> List[float]:
    return [c / 255.0 for c in color]

def _is_block_label_layer(layer_name: str, text: str = "") -> bool:
    """
    Identify layers that carry block/file-name labels.

    We do not rely on a single exact name ("BLOCKS") because source projects
    commonly use variants such as "01_BLOCKS", "BLOCK_LABELS", or "FileNames".
    """
    lname = str(layer_name or "").strip().upper()
    if not lname:
        return False
    if text:
        try:
            int(text.strip())
            return False  # numeric attribute values are not block names
        except ValueError:
            pass
    if lname in {"BLOCKS", "FILENAMES", "FEATUREATTRIBS"}:
        return True
    return ("BLOCK" in lname) or ("FILENAME" in lname)

def _score_label(text: str) -> int:
    """
    Return a priority score for a text string.

    Score  100 : grid ID or block name  (separator + 4+ digits)
                 e.g. "DW2039017_000347", "GR_0012_005", "MASTROMAURO+SA2000001"
    Score   50 : separator + some digits  (e.g. "BLOCK_ABC_123")
    Score   10 : has any digit (generic label)
    Score    0 : skip - not a useful label

    FIX (block-name visibility): treat '+' as equivalent to '_' as a word
    separator so that DGN block names like "MASTROMAURO+SA2000001" score 100
    (HIGH priority) instead of 10 (LOW), ensuring they survive label decimation.
    """
    t = text.strip()
    if len(t) < 5:
        return 0
    has_digit     = any(c.isdigit() for c in t)
    # Treat both '_' and '+' as valid name separators (covers DGN block names
    # that export with '+' rather than '_', e.g. "MASTROMAURO+SA2000001")
    has_separator = '_' in t or '+' in t

    if not has_digit and not has_separator:
        return 10

    # HIGH: separator + 4+ digits -> grid IDs and DGN block names
    if has_separator and sum(c.isdigit() for c in t) >= 4:
        return 100
    # MEDIUM: separator + some digits
    if has_separator and has_digit:
        return 50
    # LOW: just has digits
    if has_digit:
        return 10
    return 0


def _is_repetitive_coordinate_annotation(entity: Dict) -> bool:
    """Identify dense ``X_Y`` coordinate text that may be safely decimated.

    CONNECT DGN survey grids commonly place one numeric coordinate pair on
    every cell using the ``FEATURE_LABEL`` level.  Those annotations must not
    consume the text-actor budget ahead of semantic labels such as names,
    statuses, and titles.
    """
    layer = " ".join(
        str(entity.get("layer", "")).strip().upper().replace("_", " ").split()
    )
    if layer != "FEATURE LABEL":
        return False

    parts = str(entity.get("text", "")).strip().split("_")
    if len(parts) != 2 or not all(part.strip() for part in parts):
        return False
    try:
        float(parts[0])
        float(parts[1])
    except ValueError:
        return False
    return True


def _label_color_and_height(
    text: str,
) -> Tuple[Tuple[int, int, int], float]:
    """
    Return (vtk_color, text_height) for a label â€” mirrors DXF smart colour
    selection in process_entity INSERT block.

    The DXF code uses:
      â€¢ Cyan   (0,255,255) + height 3.0  â†’  grid IDs  (underscore + many digits)
      â€¢ Yellow (255,255,0) + height 2.5  â†’  feature names  (everything else)

    We apply the same split so SNT labels look identical to DXF labels.
    """
    score = _score_label(text)
    if score >= 100:
        # High-confidence grid ID â†’ cyan
        return (0, 255, 255), 3.0
    else:
        # Feature / generic label â†’ yellow
        return (255, 255, 0), 2.5
    
@lru_cache(maxsize=262144)
def _score_label_cached(text: str) -> int:
    return _score_label(text)


@lru_cache(maxsize=262144)
def _label_color_and_height_cached(text: str) -> Tuple[Tuple[int, int, int], float]:
    return _label_color_and_height(text)


def _snt_enable_gl_point_size(app) -> bool:
    """
    Synchronously enable GL_PROGRAM_POINT_SIZE (0x8642) and install the
    persistent StartEvent observer so it stays enabled across future renders.
    """
    try:
        rw = app.vtk_widget.GetRenderWindow()
        if rw is None:
            return False
        state = rw.GetState() if hasattr(rw, 'GetState') else None
        if state and hasattr(state, 'vtkglEnable'):
            state.vtkglEnable(0x8642)

            try:
                from gui.unified_actor_manager import (
                    _install_program_point_size_observer,
                    _try_enable_program_point_size,
                )
                ua = getattr(app, '_unified_actor', None)
                if ua is not None:
                    _try_enable_program_point_size(rw)
                    _install_program_point_size_observer(ua, rw)
            except Exception:
                pass

            return True
    except Exception as e:
        print(f"  [warn] _snt_enable_gl_point_size: {e}")
    return False


def _snt_push_border_uniforms(app) -> None:
    """
    Push weight_lut / visibility_lut / border_ring_val uniforms to the
    unified point-cloud actor right now, before the impending render.
    """
    try:
        from gui.unified_actor_manager import _push_uniforms_direct, _main_tile_all_actor_items, _is_main_tiled
        if _is_main_tiled(app):
            for _, ua in _main_tile_all_actor_items(app):
                ctx = getattr(ua, '_naksha_shader_ctx', None)
                if ctx is not None:
                    _push_uniforms_direct(ua, ctx)
            return
        ua = getattr(app, '_unified_actor', None)
        if ua is None:
            return
        ctx = getattr(ua, '_naksha_shader_ctx', None)
        if ctx is None:
            return
        _push_uniforms_direct(ua, ctx)
    except Exception as e:
        print(f"  [warn] _snt_push_border_uniforms: {e}")


def _get_snt_z_offset(app):
    """
    Return the Z offset to apply to SNT actors so the grid sits above the
    loaded point cloud.  Falls back to 0.0 if no data is loaded.

    Uses app.data_bounds[4:6] as a fast cache (populated during LAZ load).
    Falls back to a live scan of app.data['xyz'][:, 2] if the cache is absent,
    then writes the result back so subsequent calls are O(1).

    Guards:
    - bounds list must have at least 6 elements (indices 4 and 5).
    - z_max must be finite and z_range non-negative.
    - Any exception returns 0.0 without crashing.
    """
    try:
        if hasattr(app, 'data') and app.data is not None and 'xyz' in app.data:
            # Try the fast cache first (set during LAZ load or by the fallback below)
            bounds = getattr(app, 'data_bounds', None)
            if bounds is not None and len(bounds) >= 6:
                z_min = float(bounds[4])
                z_max = float(bounds[5])
            else:
                # One-time live scan — cache the result so we only do this once
                z_vals = app.data['xyz'][:, 2]
                z_min, z_max = float(z_vals.min()), float(z_vals.max())
                # Store full 6-element list so future accesses via bounds[4/5] are safe
                app.data_bounds = [0.0, 0.0, 0.0, 0.0, z_min, z_max]

            import math as _math
            if not _math.isfinite(z_max):
                return 0.0

            z_range = max(z_max - z_min, 0.0)   # guard against inverted bounds
            offset = z_max + max(z_range * 0.5, 50.0)
            return offset
    except Exception:
        pass
    return 0.0


def _apply_z_offset_to_actor(actor, new_offset: float):
    old_offset = getattr(actor, '_snt_z_offset', 0.0)
    delta = new_offset - old_offset
    if abs(delta) > 0.001:
        actor.AddPosition(0, 0, delta)
        actor._snt_z_offset = new_offset

def _decode_point_body(body, layer, color):
    if len(body) < 12:
        return None
    try:
        x, y, z = struct.unpack_from("<3f", body)
        return {"type": "POINT", "layer": layer, "color": color,
                "position": (float(x), float(y), float(z))}
    except struct.error:
        return None


def _decode_line_body(body, layer, color):
    if len(body) < 24:
        return None
    try:
        sx, sy, sz, ex, ey, ez = struct.unpack_from("<6f", body)
        return {"type": "POLYLINE", "layer": layer, "color": color,
                "vertices": [(float(sx), float(sy), float(sz)),
                             (float(ex), float(ey), float(ez))],
                "closed": False}
    except struct.error:
        return None


def _decode_arc_body(body, layer, color):
    if len(body) < 24:
        return None
    try:
        cx, cy, cz, r, sa, ea = struct.unpack_from("<6f", body)
        sa_r = math.radians(float(sa))
        ea_r = math.radians(float(ea))
        if ea_r <= sa_r:
            ea_r += 2.0 * math.pi
        verts = [
            (float(cx) + float(r) * math.cos(sa_r + (ea_r - sa_r) * i / _ARC_SEGMENTS),
             float(cy) + float(r) * math.sin(sa_r + (ea_r - sa_r) * i / _ARC_SEGMENTS),
             float(cz))
            for i in range(_ARC_SEGMENTS + 1)
        ]
        return {"type": "POLYLINE", "layer": layer, "color": color,
                "vertices": verts, "closed": False}
    except struct.error:
        return None


def _decode_circle_body(body, layer, color):
    if len(body) < 16:
        return None
    try:
        cx, cy, cz, r = struct.unpack_from("<4f", body)
        verts = [
            (float(cx) + float(r) * math.cos(2.0 * math.pi * i / _CIRCLE_SEGMENTS),
             float(cy) + float(r) * math.sin(2.0 * math.pi * i / _CIRCLE_SEGMENTS),
             float(cz))
            for i in range(_CIRCLE_SEGMENTS + 1)
        ]
        return {"type": "POLYLINE", "layer": layer, "color": color,
                "vertices": verts, "closed": True}
    except struct.error:
        return None


def _decode_lwpolyline_body(body, layer, color):
    if len(body) < 9:
        return None
    try:
        elev, flags, count = struct.unpack_from("<fBI", body)
        if len(body) < 9 + count * 12:
            return None
        arr = np.frombuffer(body, dtype=np.dtype("<f4"), count=count * 3, offset=9)
        arr = arr.reshape((-1, 3))
        xy = arr[:, :2].astype(np.float64, copy=False)
        out = np.empty((len(xy), 3), dtype=np.float64)
        out[:, :2] = xy
        out[:, 2] = float(elev)
        verts = out.tolist()
        if not verts:
            return None
        return {"type": "POLYLINE", "layer": layer, "color": color,
                "vertices": verts, "closed": bool(flags & 0x01)}
    except (struct.error, ValueError):
        return None


def _decode_polyline_body(body, layer, color):
    if len(body) < 5:
        return None
    try:
        flags, count = struct.unpack_from("<BI", body)
        if len(body) < 5 + count * 12:
            return None
        arr = np.frombuffer(body, dtype=np.dtype("<f4"), count=count * 3, offset=5)
        arr = arr.reshape((-1, 3))
        verts = arr.astype(np.float64, copy=False).tolist()
        if not verts:
            return None
        return {"type": "POLYLINE", "layer": layer, "color": color,
                "vertices": verts, "closed": bool(flags & 0x01)}
    except (struct.error, ValueError):
        return None


def _decode_text_body(body, layer, color, string_fn):
    if len(body) < 28:
        return None
    try:
        ix, iy, iz, height, rotation, str_idx, _style = struct.unpack_from("<5fII", body)
        text = string_fn(str_idx)
        if not text or not text.strip():
            return None
        return {"type": "TEXT", "layer": layer, "color": color,
                "text": text,
                "position": (float(ix), float(iy), float(iz)),
                "height": float(height) if height > 0.0 else 1.0,
                "rotation": float(rotation)}
    except struct.error:
        return None


def _decode_insert_body(body, layer, color, string_fn):
    """
    Decode INSERT body as a label anchor when full block geometry is unavailable.

    Observed v1.2 payload layout:
      <3f4fI> -> insert(x,y,z), scale(x,y,z), rotation, name_str_idx
    """
    if len(body) < 32:
        return None
    try:
        ix, iy, iz, sx, sy, _sz, _rot, name_idx = struct.unpack_from("<7fI", body)
        text = string_fn(name_idx)
        if not text or not str(text).strip():
            return None
        scale = max(abs(float(sx)), abs(float(sy)), 1.0)
        return {
            "type": "TEXT",
            "layer": layer,
            "color": color,
            "text": str(text).strip(),
            "position": (float(ix), float(iy), float(iz)),
            "height": max(1.0, 2.5 * scale),
        }
    except struct.error:
        return None


def _decode_hatch_body(body, layer, color, string_fn):
    """Decode one logical SNT HATCH into its closed display boundaries."""
    if len(body) < 9:
        return None
    try:
        pattern_idx, solid, boundary_count = struct.unpack_from("<IBI", body, 0)
        if boundary_count <= 0 or boundary_count > 1_000_000:
            return None
        offset = 9
        boundaries: List[List[Tuple[float, float, float]]] = []
        for _ in range(boundary_count):
            if offset + 4 > len(body):
                return None
            (point_count,) = struct.unpack_from("<I", body, offset)
            offset += 4
            if point_count > 10_000_000 or offset + point_count * 8 > len(body):
                return None
            points = []
            for _point_index in range(point_count):
                x, y = struct.unpack_from("<2f", body, offset)
                offset += 8
                points.append((float(x), float(y), 0.0))
            if len(points) >= 2:
                boundaries.append(points)
        if not boundaries:
            return None
        try:
            pattern = str(string_fn(pattern_idx) or "SOLID")
        except Exception:
            pattern = "SOLID"
        return {
            "type": "HATCH",
            "layer": layer,
            "color": color,
            "pattern": pattern,
            "solid": bool(solid),
            "boundaries": boundaries,
        }
    except (struct.error, ValueError, OverflowError):
        return None


def _decode_face3d_body(body, layer, color):
    if len(body) < 48:
        return None
    try:
        verts = [tuple(struct.unpack_from("<3f", body, i * 12)) for i in range(4)]
        return {"type": "3DFACE", "layer": layer, "color": color,
                "vertices": [(float(v[0]), float(v[1]), float(v[2])) for v in verts]}
    except struct.error:
        return None


def _is_native_batch_enabled() -> bool:
    flag = os.getenv("NAKSHA_SNT_NATIVE_BATCH", "1").strip().lower()
    return flag not in {"0", "false", "no", "off"}


def _resolve_entity_color(hdr, layer_colors, color_mode_cls) -> Tuple[int, int, int]:
    if hdr.color_mode == color_mode_cls.BYLAYER:
        idx = hdr.layer_idx
        return layer_colors[idx] if 0 <= idx < len(layer_colors) else _DEFAULT_COLOR
    if hdr.color_mode == color_mode_cls.ACI:
        return _aci_to_rgb(hdr.color_value & 0xFF, hdr.layer_idx)
    r = (hdr.color_value >> 16) & 0xFF
    g = (hdr.color_value >> 8) & 0xFF
    b = hdr.color_value & 0xFF
    return (r, g, b)


def _make_unsupported_entity(
    etype,
    layer_name: str,
    color,
    *,
    body_size: int | None = None,
    reason: str = "unsupported_type",
) -> Dict:
    subtype = getattr(etype, "name", str(etype))
    out = {
        "type": "UNSUPPORTED",
        "subtype": str(subtype),
        "layer": layer_name,
        "color": color,
        "_reason": reason,
    }
    if body_size is not None:
        try:
            out["_body_size"] = int(body_size)
        except Exception:
            pass
    return out


def _decode_entity_from_body(etype, body: bytes, layer_name: str, color, entity_type_cls, string_fn):
    if etype == entity_type_cls.POINT:
        return _decode_point_body(body, layer_name, color)
    if etype == entity_type_cls.LINE:
        return _decode_line_body(body, layer_name, color)
    if etype == entity_type_cls.ARC:
        return _decode_arc_body(body, layer_name, color)
    if etype == entity_type_cls.CIRCLE:
        return _decode_circle_body(body, layer_name, color)
    if etype == entity_type_cls.LWPOLYLINE:
        return _decode_lwpolyline_body(body, layer_name, color)
    if etype == entity_type_cls.POLYLINE:
        return _decode_polyline_body(body, layer_name, color)
    if etype in (entity_type_cls.TEXT, entity_type_cls.MTEXT,
                 entity_type_cls.DIMENSION, entity_type_cls.LEADER):
        return _decode_text_body(body, layer_name, color, string_fn)
    if etype == entity_type_cls.INSERT:
        return _decode_insert_body(body, layer_name, color, string_fn)
    if etype == entity_type_cls.HATCH:
        return _decode_hatch_body(body, layer_name, color, string_fn)
    if etype in (entity_type_cls.SOLID, entity_type_cls.FACE3D):
        return _decode_face3d_body(body, layer_name, color)
    # Preserve unsupported entities in parsed output so feature counts remain
    # consistent with converter reports and source DXF totals.
    return _make_unsupported_entity(
        etype,
        layer_name,
        color,
        body_size=len(body) if body is not None else None,
    )


def _decode_entity_from_mmap(etype, mm_obj, body_offset: int, body_size: int,
                             layer_name: str, color, entity_type_cls, string_fn):
    """
    Fast-path decode using mmap slices from offsets produced by native SntReader.
    Returns None if the entity is malformed or unsupported.
    """
    if body_offset < 0 or body_size <= 0:
        return None
    if body_offset + body_size > len(mm_obj):
        return None

    try:
        if etype == entity_type_cls.POINT:
            if body_size < 12:
                return None
            x, y, z = struct.unpack_from("<3f", mm_obj, body_offset)
            return {"type": "POINT", "layer": layer_name, "color": color,
                    "position": (float(x), float(y), float(z))}

        if etype == entity_type_cls.LINE:
            if body_size < 24:
                return None
            coords = struct.unpack_from("<6f", mm_obj, body_offset)
            return {"type": "POLYLINE", "layer": layer_name, "color": color,
                    "vertices": [coords[:3], coords[3:]],
                    "closed": False}

        if etype == entity_type_cls.ARC:
            if body_size < 24:
                return None
            cx, cy, cz, r, sa, ea = struct.unpack_from("<6f", mm_obj, body_offset)
            sa_r = math.radians(float(sa))
            ea_r = math.radians(float(ea))
            if ea_r <= sa_r:
                ea_r += 2.0 * math.pi
            verts = [
                (float(cx) + float(r) * math.cos(sa_r + (ea_r - sa_r) * i / _ARC_SEGMENTS),
                 float(cy) + float(r) * math.sin(sa_r + (ea_r - sa_r) * i / _ARC_SEGMENTS),
                 float(cz))
                for i in range(_ARC_SEGMENTS + 1)
            ]
            return {"type": "POLYLINE", "layer": layer_name, "color": color,
                    "vertices": verts, "closed": False}

        if etype == entity_type_cls.CIRCLE:
            if body_size < 16:
                return None
            cx, cy, cz, r = struct.unpack_from("<4f", mm_obj, body_offset)
            verts = [
                (float(cx) + float(r) * math.cos(2.0 * math.pi * i / _CIRCLE_SEGMENTS),
                 float(cy) + float(r) * math.sin(2.0 * math.pi * i / _CIRCLE_SEGMENTS),
                 float(cz))
                for i in range(_CIRCLE_SEGMENTS + 1)
            ]
            return {"type": "POLYLINE", "layer": layer_name, "color": color,
                    "vertices": verts, "closed": True}

        if etype == entity_type_cls.LWPOLYLINE:
            if body_size < 9:
                return None
            elev, flags, count = struct.unpack_from("<fBI", mm_obj, body_offset)
            if count <= 0:
                return None
            expected = 9 + count * 12
            if body_size < expected:
                return None
            arr = np.frombuffer(mm_obj, dtype=np.dtype("<f4"), count=count * 3, offset=body_offset + 9)
            arr = arr.reshape((-1, 3))
            # C-speed vertex conversion: tolist() applies the same
            # float32->float coercion as the per-vertex float() calls it
            # replaces, but without a Python loop iteration per vertex.
            # Lists (not tuples) are fine downstream — every consumer only
            # indexes/iterates vertices, including snt_core.direct_write.
            xy = arr[:, :2].astype(np.float64, copy=False)
            out = np.empty((len(xy), 3), dtype=np.float64)
            out[:, :2] = xy
            out[:, 2] = float(elev)
            verts = out.tolist()
            return {"type": "POLYLINE", "layer": layer_name, "color": color,
                    "vertices": verts, "closed": bool(flags & 0x01)}

        if etype == entity_type_cls.POLYLINE:
            if body_size < 5:
                return None
            flags, count = struct.unpack_from("<BI", mm_obj, body_offset)
            if count <= 0:
                return None
            expected = 5 + count * 12
            if body_size < expected:
                return None
            arr = np.frombuffer(mm_obj, dtype=np.dtype("<f4"), count=count * 3, offset=body_offset + 5)
            arr = arr.reshape((-1, 3))
            # See LWPOLYLINE above: C-speed conversion, identical values.
            verts = arr.tolist()
            return {"type": "POLYLINE", "layer": layer_name, "color": color,
                    "vertices": verts, "closed": bool(flags & 0x01)}

        if etype in (entity_type_cls.TEXT, entity_type_cls.MTEXT,
                     entity_type_cls.DIMENSION, entity_type_cls.LEADER):
            if body_size < 28:
                return None
            ix, iy, iz, height, rotation, str_idx, _style = struct.unpack_from(
                "<5fII", mm_obj, body_offset
            )
            text = string_fn(str_idx)
            if not text or not text.strip():
                return None
            return {"type": "TEXT", "layer": layer_name, "color": color,
                    "text": text,
                    "position": (float(ix), float(iy), float(iz)),
                    "height": float(height) if height > 0.0 else 1.0,
                    "rotation": float(rotation)}

        if etype == entity_type_cls.INSERT:
            if body_size < 32:
                return None
            ix, iy, iz, sx, sy, _sz, _rot, name_idx = struct.unpack_from(
                "<7fI", mm_obj, body_offset
            )
            text = string_fn(name_idx)
            if not text or not str(text).strip():
                return None
            scale = max(abs(float(sx)), abs(float(sy)), 1.0)
            return {"type": "TEXT", "layer": layer_name, "color": color,
                    "text": str(text).strip(),
                    "position": (float(ix), float(iy), float(iz)),
                    "height": max(1.0, 2.5 * scale)}

        if etype == entity_type_cls.HATCH:
            return _decode_hatch_body(
                memoryview(mm_obj)[body_offset:body_offset + body_size],
                layer_name,
                color,
                string_fn,
            )

        if etype in (entity_type_cls.SOLID, entity_type_cls.FACE3D):
            if body_size < 48:
                return None
            arr = np.frombuffer(mm_obj, dtype=np.dtype("<f4"), count=12, offset=body_offset).reshape((4, 3))
            verts = arr.astype(np.float64, copy=False).tolist()
            return {"type": "3DFACE", "layer": layer_name, "color": color,
                    "vertices": verts}

    except (struct.error, ValueError, OverflowError):
        return None

    # Keep unknown/unsupported entities so SNT file entity counts do not drop
    # in UI even when we do not render those geometries yet (e.g., HATCH).
    return _make_unsupported_entity(
        etype,
        layer_name,
        color,
        body_size=body_size,
    )


def _promote_featureattrib_text_layer(ent: Dict, src_layer_name: str, src_color,
                                      layers_out: List[Dict], layer_name_set: Set[str]) -> None:
    """
    Keep existing split behavior:
    high-confidence labels from FeatureAttribs move to FileNames layer.
    """
    if src_layer_name != "FeatureAttribs":
        return
    text_val = ent.get("text")
    if not text_val:
        return

    is_yellow = (src_color == (255, 255, 0))
    is_cyan = (src_color == (0, 255, 255))
    if is_cyan or (not is_yellow and _score_label_cached(str(text_val)) >= 100):
        new_lname = "FileNames"
        ent["layer"] = new_lname
        if new_lname not in layer_name_set:
            layers_out.append({"name": new_lname, "color": (0, 255, 255)})
            layer_name_set.add(new_lname)


def _env_int(name: str, default: int, min_value: int = 0) -> int:
    raw = os.getenv(name, "")
    if not raw:
        return default
    try:
        value = int(raw)
    except ValueError:
        return default
    if value < min_value:
        return min_value
    return value


def _select_text_entities_for_render(text_ents: List[Dict]) -> Tuple[List[Dict], Dict]:
    """
    Reduce label actor count for very large files while preserving important labels.

    Tuning:
      NAKSHA_SNT_MAX_TEXT_ACTORS      : max labels to render (0 => unlimited)
      NAKSHA_SNT_TEXT_CELL_MIN_SIZE   : minimum decimation grid size in XY units
    """
    total = len(text_ents)
    if total == 0:
        return text_ents, {"total": 0, "selected": 0, "limit": 0}

    # NT-1034 contains 3,354 valid DGN text records.  The former 1,500 cap
    # necessarily hid names or coordinate annotations.  Geometry is now
    # rendered in batches, so files up to 5,000 labels can retain all source
    # text while larger datasets still use the semantic-first decimator below.
    max_labels = _env_int("NAKSHA_SNT_MAX_TEXT_ACTORS", 5000, min_value=0)
    if max_labels == 0 or total <= max_labels:
        return text_ents, {"total": total, "selected": total, "limit": max_labels}

    # Calculate bounds of ALL text entities first
    xmin = float("inf")
    ymin = float("inf")
    xmax = float("-inf")
    ymax = float("-inf")

    for e in text_ents:
        pos = e.get("position", (0.0, 0.0, 0.0))
        try:
            x = float(pos[0])
            y = float(pos[1])
            if x < xmin: xmin = x
            if x > xmax: xmax = x
            if y < ymin: ymin = y
            if y > ymax: ymax = y
        except Exception:
            continue

    exempt: List[Dict] = []
    coordinate: List[Dict] = []
    high: List[Dict] = []
    med: List[Dict] = []
    low: List[Dict] = []

    for e in text_ents:
        if _is_block_label_layer(e.get("layer", ""), e.get("text", "")):
            exempt.append(e)
        elif _is_repetitive_coordinate_annotation(e):
            coordinate.append(e)
        else:
            txt = str(e.get("text", "")).strip()
            score = _score_label_cached(txt)
            if score >= 100:
                high.append(e)
            elif score >= 50:
                med.append(e)
            else:
                low.append(e)

    if xmin == float("inf") or ymin == float("inf"):
        selected = (exempt + high + med + low + coordinate)[:max_labels]
        return selected, {"total": total, "selected": len(selected), "limit": max_labels}

    dx = max(xmax - xmin, 1.0)
    dy = max(ymax - ymin, 1.0)
    area = dx * dy
    cell_min_size = float(_env_int("NAKSHA_SNT_TEXT_CELL_MIN_SIZE", 1, min_value=1))
    cell_size = max(math.sqrt(area / max(1, max_labels)), cell_min_size)

    # Preserve semantic text first.  In NT-1034 this keeps all 1,391 names,
    # titles, and status labels.  The old high-score-first policy let the 1,963
    # repetitive coordinate strings consume the entire 1,500-actor budget,
    # which made valid names appear to be missing from the SNT.
    semantic = exempt + high + med + low
    selected: List[Dict] = semantic[:max_labels]
    selected_ids: Set[int] = {id(e) for e in selected}
    remaining = max(0, max_labels - len(selected))

    # Use the remaining budget for a spatially representative subset of the
    # repetitive coordinate grid.  Semantic labels are intentionally not added
    # to seen_cells: a name and its nearby coordinate annotation may coexist.
    seen_cells: Set[Tuple[int, int]] = set()
    if remaining > 0:
        for e in coordinate:
            pos = e.get("position", (0.0, 0.0, 0.0))
            try:
                x = float(pos[0])
                y = float(pos[1])
            except Exception:
                continue
            key = (int((x - xmin) / cell_size), int((y - ymin) / cell_size))
            if key in seen_cells:
                continue
            seen_cells.add(key)
            selected.append(e)
            selected_ids.add(id(e))
            if len(selected) >= max_labels:
                break

    # Very small extents may yield fewer unique spatial cells than the budget.
    # Fill any remaining slots without losing deterministic source order.
    if len(selected) < max_labels:
        for e in coordinate:
            if id(e) in selected_ids:
                continue
            selected.append(e)
            selected_ids.add(id(e))
            if len(selected) >= max_labels:
                break

    return selected, {
        "total": total,
        "selected": len(selected),
        "limit": max_labels,
        "semantic": min(len(semantic), max_labels),
        "coordinates": sum(1 for e in selected if _is_repetitive_coordinate_annotation(e)),
    }


# â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
# SNT BINARY FILE READER
# â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€

def _snt_clean_layer_count_map(value) -> Dict[str, int]:
    """Return a safe non-negative ``level name -> count`` mapping."""
    if not isinstance(value, dict):
        return {}
    cleaned: Dict[str, int] = {}
    for raw_name, raw_count in value.items():
        try:
            cleaned[str(raw_name)] = max(0, int(raw_count))
        except (TypeError, ValueError, OverflowError):
            continue
    return cleaned


def _snt_entity_layer_counts(entities) -> Dict[str, int]:
    """Count currently decoded/drawable entities by SNT layer."""
    counts: Dict[str, int] = {}
    for ent in list(entities or []):
        if not isinstance(ent, dict):
            continue
        lname = str(ent.get("layer", "0"))
        counts[lname] = counts.get(lname, 0) + 1
    return counts


def _snt_layer_stats_from_parsed(parsed) -> List[Tuple[str, int, Tuple[int, int, int]]]:
    """Build Level Manager rows without conflating two DGN count domains.

    ``entities`` contains logical drawable SNT records and remains authoritative
    for rendering and the file-wide entity badge. CONNECT bridge SNTs also carry
    ``source_layer_counts``: MicroStation's physical per-level counts, including
    stored complex components. Those declared counts are authoritative for the
    Level Manager. A drawable baseline captured at load time lets subsequent
    in-memory add/delete/move operations appear as deltas over the declaration.
    """
    if not isinstance(parsed, dict):
        return []

    raw_layers = [
        layer for layer in list(parsed.get("layers", []) or [])
        if isinstance(layer, dict)
    ]
    actual_counts = _snt_entity_layer_counts(parsed.get("entities", []))
    declared_counts = _snt_clean_layer_count_map(parsed.get("source_layer_counts"))
    baseline_counts = _snt_clean_layer_count_map(parsed.get("_source_entity_layer_counts"))

    stats: Dict[str, Dict[str, object]] = {}
    ordered_names: List[str] = []

    for layer in raw_layers:
        lname = str(layer.get("name", "0"))
        if lname not in stats:
            stats[lname] = {
                "count": 0,
                "color": tuple(layer.get("color", _DEFAULT_COLOR)),
            }
            ordered_names.append(lname)

    # Keep entities/layers created by the application visible even though they
    # naturally have no MicroStation declaration.
    for lname in actual_counts:
        if lname not in stats:
            stats[lname] = {"count": 0, "color": _DEFAULT_COLOR}
            ordered_names.append(lname)

    # A bridge declaration should normally have a matching layer-table row, but
    # retain it if a producer omitted that row instead of silently losing data.
    for lname in declared_counts:
        if lname not in stats:
            stats[lname] = {"count": 0, "color": _DEFAULT_COLOR}
            ordered_names.append(lname)

    for lname in ordered_names:
        current = actual_counts.get(lname, 0)
        if lname in declared_counts:
            baseline = baseline_counts.get(lname, current)
            count = max(0, declared_counts[lname] + current - baseline)
        else:
            count = current
        stats[lname]["count"] = count

    return [
        (lname, int(stats[lname]["count"]),
         tuple(stats[lname].get("color", _DEFAULT_COLOR)))
        for lname in ordered_names
    ]


def _snt_reader_metadata(reader) -> Dict:
    """Read SNT metadata without allowing an optional codec to break loading.

    Some packaged application environments include ``zstandard`` while these
    bridge SNTs use the format's zlib metadata fallback. Older SntReader builds
    try zstd solely because the module is installed and do not catch a zstd
    decompression error. Metadata is optional for rendering, so first isolate
    that failure, then decode the same metadata block with zlib directly.
    """
    try:
        metadata = reader.meta
        return dict(metadata) if isinstance(metadata, dict) else {}
    except Exception as primary_error:
        try:
            import json
            import zlib

            header = getattr(reader, "_header", {})
            mapped_file = getattr(reader, "_mm", None)
            offset = int(header["offset_meta"])
            (compressed_size,) = struct.unpack_from("<I", mapped_file, offset)
            payload_start = offset + 4
            compressed = bytes(mapped_file[payload_start:payload_start + compressed_size])
            metadata = json.loads(zlib.decompress(compressed).decode("utf-8"))
            return dict(metadata) if isinstance(metadata, dict) else {}
        except Exception as fallback_error:
            print(
                "  [warning] SNT metadata unavailable; using drawable layer counts "
                f"({type(primary_error).__name__}: {primary_error}; "
                f"fallback {type(fallback_error).__name__}: {fallback_error})"
            )
            return {}


class _SntCancelled(Exception):
    """Raised when an SNT decode is cancelled via ``is_cancelled``."""


def _read_snt_file(filepath: str, progress_cb=None, is_cancelled=None) -> Dict:
    """Decode an SNT file into layers + drawable entity dicts.

    ``progress_cb``, when given, is called as ``progress_cb(decoded_count)``
    roughly every 25k entities so a background worker can keep a progress
    dialog alive (and honour Cancel through ``is_cancelled``) instead of
    freezing the GUI thread at 0% on million-entity files.
    """
    result: Dict = {"version": (1, 0), "layers": [], "entities": []}

    try:
        from snt_core.snt_reader import SntReader
        from snt_core.snt_format import ColorMode, EntityType, FLAG_USE_F64

        with SntReader(filepath) as reader:
            result["version"] = (reader.version_major, reader.version_minor)
            result["flags"] = int(reader.flags)
            result["use_float64"] = bool(reader.flags & FLAG_USE_F64)
            metadata = _snt_reader_metadata(reader)
            result["metadata"] = metadata
            result["source_layer_counts"] = _snt_clean_layer_count_map(
                metadata.get("source_layer_counts")
            )
            layers_out: List[Dict] = []
            layer_colors: List[Tuple[int, int, int]] = []
            for i, rec in enumerate(reader.layers):
                lname = reader.string(rec.name_idx)
                color = _aci_to_rgb(rec.color_aci, i)
                layers_out.append({"name": lname, "color": color})
                layer_colors.append(color)
            result["layers"] = layers_out

            layer_name_set: Set[str] = {layer["name"] for layer in layers_out}
            entities_out: List[Dict] = []
            native_batch_used = False
            _decode_t0 = time.perf_counter()

            # Per-entity C-extension lookups (layer_name, string pool, ACI
            # colour) dominate decode time on million-entity files: each is a
            # Python→native call plus a fresh object allocation. Layer and
            # colour spaces are tiny (a handful of layers) and the string pool
            # is finite, so memoize all three. Zero behaviour change — the
            # same values are returned, just without repeating native calls.
            _layer_name_cache: Dict[int, str] = {}
            _string_cache: Dict[int, str] = {}
            _entity_color_cache: Dict[tuple, Tuple[int, int, int]] = {}

            def _cached_layer_name(layer_idx) -> str:
                try:
                    return _layer_name_cache[layer_idx]
                except KeyError:
                    pass
                name = reader.layer_name(layer_idx)
                _layer_name_cache[layer_idx] = name
                return name

            def _cached_string(string_idx):
                try:
                    return _string_cache[string_idx]
                except KeyError:
                    pass
                value = reader.string(string_idx)
                _string_cache[string_idx] = value
                return value

            def _cached_entity_color(hdr) -> Tuple[int, int, int]:
                try:
                    mode = hdr.color_mode
                    value = hdr.color_value
                    layer_idx = hdr.layer_idx
                except AttributeError:
                    return _resolve_entity_color(hdr, layer_colors, ColorMode)
                if mode == ColorMode.BYLAYER:
                    return layer_colors[layer_idx] if 0 <= layer_idx < len(layer_colors) else _DEFAULT_COLOR
                key = (mode, value, layer_idx)
                try:
                    return _entity_color_cache[key]
                except KeyError:
                    pass
                color = _resolve_entity_color(hdr, layer_colors, ColorMode)
                _entity_color_cache[key] = color
                return color

            if _is_native_batch_enabled():
                try:
                    with open(filepath, "rb") as fh, mmap.mmap(fh.fileno(), 0, access=mmap.ACCESS_READ) as mm_obj:
                        for entity_id, hdr in enumerate(reader.iter_entities()):
                            if (entity_id & 0xFFF) == 0:
                                # Cancel/progress bookkeeping every ~4k entities;
                                # per-entity calls here cost ~0.2s per million.
                                if is_cancelled is not None and is_cancelled():
                                    raise _SntCancelled()
                                if progress_cb is not None and (entity_id & 0x3FFF) == 0:
                                    # Every ~16k entities: keeps progress alive.
                                    try:
                                        progress_cb(entity_id + 1)
                                    except Exception:
                                        pass
                            layer_name = _cached_layer_name(hdr.layer_idx)
                            color = _cached_entity_color(hdr)
                            etype = hdr.entity_type
                            lw = hdr.lineweight if hasattr(hdr, 'lineweight') else 0

                            ent = _decode_entity_from_mmap(
                                etype=etype,
                                mm_obj=mm_obj,
                                body_offset=hdr.body_offset,
                                body_size=hdr.body_size,
                                layer_name=layer_name,
                                color=color,
                                entity_type_cls=EntityType,
                                string_fn=_cached_string,
                            )
                            if ent is None:
                                body = reader.read_body(hdr)
                                ent = _decode_entity_from_body(
                                    etype=etype,
                                    body=body,
                                    layer_name=layer_name,
                                    color=color,
                                    entity_type_cls=EntityType,
                                    string_fn=_cached_string,
                                )
                            if ent is None:
                                continue
                            ent["_lineweight"] = lw

                            ent["snt_binary"] = True

                            ent["_snt_entity_id"] = int(entity_id)
                            if etype in (EntityType.TEXT, EntityType.MTEXT,
                                         EntityType.DIMENSION, EntityType.LEADER):
                                if "height" in ent:
                                    ent["font_size"] = ent["height"] / 0.15
                                _promote_featureattrib_text_layer(
                                    ent=ent,
                                    src_layer_name=layer_name,
                                    src_color=ent.get("color", _DEFAULT_COLOR),
                                    layers_out=layers_out,
                                    layer_name_set=layer_name_set,
                                )
                            entities_out.append(ent)

                    native_batch_used = True
                except _SntCancelled:
                    raise
                except Exception as batch_exc:
                    print(f"  [native-batch] fallback to classic decode ({type(batch_exc).__name__}: {batch_exc})")

            if not native_batch_used:
                for entity_id, hdr in enumerate(reader.iter_entities()):
                    if (entity_id & 0xFFF) == 0:
                        if is_cancelled is not None and is_cancelled():
                            raise _SntCancelled()
                        if progress_cb is not None and (entity_id & 0x3FFF) == 0:
                            try:
                                progress_cb(entity_id + 1)
                            except Exception:
                                pass
                    body = reader.read_body(hdr)
                    layer_name = _cached_layer_name(hdr.layer_idx)
                    color = _cached_entity_color(hdr)
                    etype = hdr.entity_type
                    lw = int(getattr(hdr, 'lineweight', 0) or 0)

                    ent = _decode_entity_from_body(
                        etype=etype,
                        body=body,
                        layer_name=layer_name,
                        color=color,
                        entity_type_cls=EntityType,
                        string_fn=_cached_string,
                    )
                    if ent is None:
                        continue
                    ent["snt_binary"] = True
                    ent["_snt_entity_id"] = int(entity_id)
                    ent["_lineweight"] = lw

                    if etype in (EntityType.TEXT, EntityType.MTEXT,
                                 EntityType.DIMENSION, EntityType.LEADER):
                        if "height" in ent:
                            ent["font_size"] = ent["height"] / 0.15
                        _promote_featureattrib_text_layer(
                            ent=ent,
                            src_layer_name=layer_name,
                            src_color=ent.get("color", _DEFAULT_COLOR),
                            layers_out=layers_out,
                            layer_name_set=layer_name_set,
                        )
                    entities_out.append(ent)

            # Recover exact layer colors from entity true-colors since SNT only stores ACI
            layer_exact_colors = {}
            for ent in entities_out:
                lname = ent.get("layer", "0")
                if "color" in ent and lname not in layer_exact_colors:
                    layer_exact_colors[lname] = ent["color"]

            for layer_meta in result["layers"]:
                lname = layer_meta["name"]
                if lname in layer_exact_colors:
                    layer_meta["color"] = layer_exact_colors[lname]

            result["entities"] = entities_out
            # Capture after reader-side layer promotion so later live edit
            # deltas use the same layer names shown by the application.
            result["_source_entity_layer_counts"] = _snt_entity_layer_counts(entities_out)
            try:
                _decode_ms = (time.perf_counter() - _decode_t0) * 1000.0
            except Exception:
                _decode_ms = -1.0
            print(
                f"  SNT v{reader.version_major}.{reader.version_minor} | "
                f"layers={len(layers_out)} entities={len(entities_out)} "
                f"native_batch={'on' if native_batch_used else 'off'} "
                f"decode={_decode_ms:.0f}ms"
            )
            return result

    except ImportError:
        print("  [warning] snt_core not on PYTHONPATH - using legacy inline reader")
    except _SntCancelled:
        raise
    except Exception as exc:
        print(f"  [warning] SntReader failed ({type(exc).__name__}): {exc}")
        traceback.print_exc()
        return result
    # â”€â”€ Legacy inline parser â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
    try:
        with open(filepath, "rb") as f:
            raw: bytes = f.read()
    except OSError as exc:
        print(f"  [error] Cannot read SNT file: {exc}")
        return result

    if len(raw) < 24:
        print("  [error] File too small to be a valid SNT file")
        return result

    magic = raw[:4]
    if magic not in (_LEGACY_MAGIC_V0, _LEGACY_MAGIC_V1):
        print(f"  [error] Unrecognised magic {magic!r} - not an SNT file")
        return result

    pos = 4
    ver_major, ver_minor = struct.unpack_from("<HH", raw, pos); pos += 4
    result["version"] = (ver_major, ver_minor)
    pos += 4  # skip CRC
    num_strings, num_layers, num_entities = struct.unpack_from("<III", raw, pos)
    pos += 12
    print(f"  [legacy] SNT v{ver_major}.{ver_minor} | "
          f"strings={num_strings} layers={num_layers} entities={num_entities}")

    legacy_strings: List[str] = []
    for _ in range(num_strings):
        if pos + 4 > len(raw):
            break
        slen = struct.unpack_from("<I", raw, pos)[0]; pos += 4
        legacy_strings.append(raw[pos:pos + slen].decode("utf-8", errors="replace"))
        pos += slen

    legacy_layers: List[Dict] = []
    for i in range(num_layers):
        if pos + 7 > len(raw):
            break
        name_idx = struct.unpack_from("<I", raw, pos)[0]; pos += 4
        r, g, b  = struct.unpack_from("<BBB", raw, pos); pos += 3
        name  = (legacy_strings[name_idx] if name_idx < len(legacy_strings)
                 else f"Layer{i}")
        color = ((r, g, b) if (r + g + b) > 0
                 else _LAYER_COLOR_CYCLE[i % len(_LAYER_COLOR_CYCLE)])
        legacy_layers.append({"name": name, "color": color})
    result["layers"] = legacy_layers
    legacy_layer_name_set: Set[str] = {layer["name"] for layer in legacy_layers}

    legacy_entities: List[Dict] = []
    for _ in range(num_entities):
        if pos >= len(raw):
            break
        try:
            etype     = struct.unpack_from("<B", raw, pos)[0]; pos += 1
            layer_idx = struct.unpack_from("<I", raw, pos)[0]; pos += 4
            lname  = (legacy_layers[layer_idx]["name"]
                      if layer_idx < len(legacy_layers) else "0")
            lcolor = (legacy_layers[layer_idx]["color"]
                      if layer_idx < len(legacy_layers) else _DEFAULT_COLOR)

            if etype == _LEGACY_ETYPE_POLYLINE:
                nv = struct.unpack_from("<I", raw, pos)[0]; pos += 4
                verts = []
                for _ in range(nv):
                    x, y, z = struct.unpack_from("<ddd", raw, pos); pos += 24
                    verts.append((x, y, z))
                closed = (len(verts) >= 3 and
                          np.allclose(verts[0], verts[-1], atol=1e-6))
                legacy_entities.append({
                    "type": "POLYLINE", "layer": lname, "color": lcolor,
                    "vertices": verts, "closed": closed})
            elif etype == _LEGACY_ETYPE_TEXT:
                tlen = struct.unpack_from("<I", raw, pos)[0]; pos += 4
                text = raw[pos:pos + tlen].decode("utf-8", errors="replace")
                pos += tlen
                x, y, z = struct.unpack_from("<ddd", raw, pos); pos += 24
                height = (struct.unpack_from("<d", raw, pos)[0]
                          if pos + 8 <= len(raw) else 1.0)
                pos += 8
                
                ent = {
                    "type": "TEXT", "layer": lname, "color": lcolor,
                    "text": text, "position": (x, y, z), "height": height}
                
                # âœ… HIGH-PRIORITY SPLIT (Legacy)
                if lname == "FeatureAttribs":
                    is_yellow = (lcolor == (255, 255, 0))
                    is_cyan = (lcolor == (0, 255, 255))
                    if is_cyan or (not is_yellow and _score_label_cached(text) >= 100):
                        new_lname = "FileNames"
                        ent["layer"] = new_lname
                        if new_lname not in legacy_layer_name_set:
                            legacy_layers.append({"name": new_lname, "color": (0, 255, 255)})
                            legacy_layer_name_set.add(new_lname)
                
                legacy_entities.append(ent)
            elif etype == _LEGACY_ETYPE_3DFACE:
                verts = []
                for _ in range(4):
                    x, y, z = struct.unpack_from("<ddd", raw, pos); pos += 24
                    verts.append((x, y, z))
                legacy_entities.append({
                    "type": "3DFACE", "layer": lname, "color": lcolor,
                    "vertices": verts})
            else:
                break
        except struct.error:
            break

    result["entities"] = legacy_entities
    return result


def _read_snt_file_summary(filepath: str) -> Dict:
    """O(1) row summary: layer table + header entity count only.

    Browse must never iterate entity headers/bodies: on a 1.1M-entity file
    (possibly over a network share) that walk alone stalled the file list
    for seconds. The count badge comes straight from the file header's
    ``entity_count`` field — the same record count a full iteration would
    produce. Per-layer pre-attach counts come from the declared
    ``source_layer_counts`` metadata (the same source the Level Manager
    treats as authoritative after Attach). Full geometry stays deferred to
    the Attach worker.
    """
    from snt_core.snt_reader import SntReader

    with SntReader(filepath) as reader:
        layers = []
        try:
            layer_recs = list(reader.layers)
        except Exception:
            layer_recs = []
        for index, rec in enumerate(layer_recs):
            try:
                name_idx = getattr(rec, 'name_idx', index)
                lname = reader.string(name_idx)
            except Exception:
                try:
                    lname = reader.layer_name(index)
                except Exception:
                    lname = f"Layer{index}"
            try:
                color = _aci_to_rgb(getattr(rec, 'color_aci', 7), index)
            except Exception:
                color = _DEFAULT_COLOR
            layers.append({'name': lname, 'color': color})

        try:
            version = (int(reader.version_major), int(reader.version_minor))
        except Exception:
            version = (1, 0)
        try:
            flags = int(reader.flags)
        except Exception:
            flags = 0

        count = None
        try:
            count = int(getattr(reader, "entity_count"))
        except (AttributeError, TypeError, ValueError, OverflowError):
            pass
        if count is None:
            try:
                header = reader._parse_header() or {}
                count = int(header.get("entity_count"))
            except Exception:
                pass
        if count is None:
            try:
                header = getattr(reader, "_header", {}) or {}
                raw_count = header.get("entity_count", header.get("num_entities"))
                count = int(raw_count)
            except (TypeError, ValueError, OverflowError, AttributeError):
                pass

        # Declared per-level counts for the pre-attach Level Manager. This
        # is metadata-only (no entity walk) and matches post-attach Level
        # Manager semantics, which treat declarations as authoritative.
        layer_counts: Dict[str, int] = {}
        try:
            metadata = _snt_reader_metadata(reader)
            layer_counts = _snt_clean_layer_count_map(
                metadata.get("source_layer_counts"))
        except Exception:
            layer_counts = {}
        if not layer_counts:
            layer_counts = {layer["name"]: 0 for layer in layers
                            if isinstance(layer, dict)}

        if count is None:
            # Last resort: exact header iteration (slow on huge files, but
            # only reached when the reader exposes no header count).
            per_layer: Dict[int, int] = {}
            count = 0
            try:
                for hdr in reader.iter_entities():
                    count += 1
                    try:
                        li = int(getattr(hdr, 'layer_idx', -1))
                    except Exception:
                        li = -1
                    if li >= 0:
                        per_layer[li] = per_layer.get(li, 0) + 1
            except Exception:
                pass
            if not layer_counts or all(v == 0 for v in layer_counts.values()):
                layer_counts = {
                    layers[i]['name']: per_layer.get(i, 0)
                    for i in range(len(layers))
                }

        return {
            'version': version,
            'flags': flags,
            'layers': layers,
            'entity_count': count if count is not None else 0,
            'layer_counts': layer_counts,
            'deferred_geometry': True,
        }


# â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
# BACKGROUND LOAD WORKER
# â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€

class SNTLoadWorker(QThread):
    progress    = Signal(int, str, bool)
    file_loaded = Signal(object, object)
    load_succeeded = Signal()
    error       = Signal(str)

    def __init__(self, file_paths: List[str]) -> None:
        super().__init__()
        self.file_paths: List[str] = file_paths
        self._cancelled: bool      = False

    def cancel(self) -> None:
        self._cancelled = True

    def run(self) -> None:
        try:
            total = len(self.file_paths)
            indeterminate = (total == 1)
            for idx, fp in enumerate(self.file_paths):
                if self._cancelled:
                    return
                
                QCoreApplication.processEvents()
                if self._cancelled:
                    return
                    
                snt_path = Path(fp)
                self.progress.emit(
                    0 if indeterminate else idx,
                    f"Reading {snt_path.name}...",
                    indeterminate,
                )
                item_data = {"snt_path": snt_path}
                try:
                    summary = _read_snt_file_summary(str(snt_path))
                    if self._cancelled:
                        return
                    item_data["summary"] = summary
                    item_data["entity_count"] = int(summary["entity_count"])
                    item_data["layer_count"] = len(summary["layers"])
                except Exception as exc:
                    if not self._cancelled:
                        item_data["error"] = str(exc)
                
                if not self._cancelled:
                    self.file_loaded.emit(item_data, None)
            
            if not self._cancelled:
                # Keep application success separate from QThread.finished.
                # Redeclaring and emitting finished caused both the manual and
                # automatic emissions to invoke attachment callbacks.
                self.load_succeeded.emit()
        except Exception as exc:
            if not self._cancelled:
                self.error.emit(f"SNT loading failed: {exc}\n{traceback.format_exc()}")


def _convert_snt_entities(entities: List[Dict], progress_cb=None, is_cancelled=None) -> List[Dict]:
    """Pure (Qt-free) SNT decode-model → render-model conversion.

    Extracted from ``MultiSNTAttachmentDialog._convert_entities`` so the
    Attach decode phase can run on a worker thread. Behaviour is identical;
    the dialog method delegates to this function.
    """
    out: List[Dict] = []
    for index, ent in enumerate(entities):
        if (index & 0x3FFF) == 0:
            if is_cancelled is not None and is_cancelled():
                raise _SntCancelled()
            if progress_cb is not None:
                progress_cb(f"convert:{index}:{len(entities)}")
        etype = ent.get("type", "")
        color = ent.get("color", _DEFAULT_COLOR)
        layer = ent.get("layer", "0")

        if etype == "POLYLINE":
            verts = ent.get("vertices", [])
            if len(verts) < 2:
                continue
            out.append({
                "type":        "polyline",
                "points":      verts,
                "closed":      ent.get("closed", False),
                "color":       color,
                "layer":       layer,
                "_lineweight": int(ent.get("_lineweight", 0) or 0),
            })
        elif etype == "HATCH":
            # One logical DGN associative region may have several loops.
            # Expand them only for display so the SNT entity count remains
            # one-to-one with the DGN feature count.
            for boundary in ent.get("boundaries", []) or []:
                if len(boundary) < 2:
                    continue
                render_boundary: Dict = {
                    "type": "polyline",
                    "points": boundary,
                    "closed": True,
                    "color": color,
                    "layer": layer,
                    "_lineweight": int(ent.get("_lineweight", 0) or 0),
                }
                if ent.get("_snt_entity_id") is not None:
                    render_boundary["_snt_entity_id"] = int(ent["_snt_entity_id"])
                out.append(render_boundary)
        elif etype == "3DFACE":
            verts = ent.get("vertices", [])
            if len(verts) < 3:
                continue
            v = list(verts[:4])
            while len(v) < 4:
                v.append(v[-1])
            p2 = v[2]
            p3 = v[3]
            is_tri = (
                abs(float(p2[0]) - float(p3[0])) <= 1e-6
                and abs(float(p2[1]) - float(p3[1])) <= 1e-6
                and abs(float(p2[2]) - float(p3[2])) <= 1e-6
            )
            out.append({
                "type":        "3dface",
                "vertices":    v,
                "is_triangle": is_tri,
                "color":       color,
                "layer":       layer,
            })
        elif etype == "TEXT":
            text = str(ent.get("text", "")).strip()
            if not text:
                continue
            default_color, default_height = _label_color_and_height_cached(text)
            stored_font_size = ent.get("font_size")
            if stored_font_size is not None:
                label_color = color if color else default_color
            elif color and tuple(color) != tuple(_DEFAULT_COLOR):
                label_color = color
            else:
                label_color = default_color
            stored_height = ent.get("height")
            try:
                label_height = float(stored_height) if stored_height else float(default_height)
            except (TypeError, ValueError):
                label_height = float(default_height)
            try:
                label_rotation = float(ent.get("rotation", 0.0) or 0.0)
            except (TypeError, ValueError):
                label_rotation = 0.0
            pos = ent.get("position", (0.0, 0.0, 0.0))
            stored_font_size = ent.get("font_size")
            text_entry: Dict = {
                "type":     "text",
                "text":     text,
                "position": pos,
                "height":   label_height,
                "rotation": label_rotation,
                "color":    label_color,
                "layer":    layer,
            }
            if "snt_binary" in ent:
                text_entry["snt_binary"] = ent["snt_binary"]
            if stored_font_size is not None:
                try:
                    text_entry["font_size"] = float(stored_font_size)
                except (TypeError, ValueError):
                    pass
            out.append(text_entry)
        elif etype == "POINT":
            pos = ent.get("position", (0.0, 0.0, 0.0))
            out.append({
                "type":     "point",
                "position": pos,
                "color":    color,
                "layer":    layer,
            })
    return out


def _compute_snt_2d_bounds(entities: List[Dict]) -> Optional[Tuple[float, float, float, float]]:
    """Pure (Qt-free) stable XY bounds for fit-view.

    Geometry drives bounds; text anchors are fallback only. Identical to the
    former dialog method, which now delegates here.
    """
    if not entities:
        return None

    geom_min_x = float("inf")
    geom_min_y = float("inf")
    geom_max_x = float("-inf")
    geom_max_y = float("-inf")
    has_geom = False

    text_min_x = float("inf")
    text_min_y = float("inf")
    text_max_x = float("-inf")
    text_max_y = float("-inf")
    has_text = False

    def _update_xy(x_val, y_val, use_text_bucket=False):
        nonlocal geom_min_x, geom_min_y, geom_max_x, geom_max_y, has_geom
        nonlocal text_min_x, text_min_y, text_max_x, text_max_y, has_text
        try:
            x = float(x_val)
            y = float(y_val)
        except Exception:
            return
        if use_text_bucket:
            if x < text_min_x:
                text_min_x = x
            if y < text_min_y:
                text_min_y = y
            if x > text_max_x:
                text_max_x = x
            if y > text_max_y:
                text_max_y = y
            has_text = True
            return
        if x < geom_min_x:
            geom_min_x = x
        if y < geom_min_y:
            geom_min_y = y
        if x > geom_max_x:
            geom_max_x = x
        if y > geom_max_y:
            geom_max_y = y
        has_geom = True

    def _update_xy_many(points) -> bool:
        """Vectorised ``_update_xy`` for long vertex lists (geometry bucket).

        A 1.1M-entity contour file carries tens of millions of vertices;
        converting each with a Python ``float()`` call took minutes. Numpy
        reduces it to seconds. Non-finite coordinates are skipped (the scalar
        path effectively ignored NaN via failed comparisons, and including
        an inf would poison the fit-view camera, so filtering is strictly
        safer). Falls back to the scalar loop for ragged input.
        """
        nonlocal geom_min_x, geom_min_y, geom_max_x, geom_max_y, has_geom
        try:
            if not isinstance(points, (list, tuple)) or len(points) < 64:
                return False
            arr = np.asarray(points, dtype=np.float64)
            if arr.ndim != 2 or arr.shape[0] == 0 or arr.shape[1] < 2:
                return False
            xy = arr[:, :2]
            finite = np.isfinite(xy).all(axis=1)
            if not bool(finite.any()):
                return True
            x0 = float(xy[finite, 0].min())
            x1 = float(xy[finite, 0].max())
            y0 = float(xy[finite, 1].min())
            y1 = float(xy[finite, 1].max())
        except Exception:
            return False
        if not has_geom:
            geom_min_x, geom_max_x = x0, x1
            geom_min_y, geom_max_y = y0, y1
            has_geom = True
            return True
        if x0 < geom_min_x:
            geom_min_x = x0
        if y0 < geom_min_y:
            geom_min_y = y0
        if x1 > geom_max_x:
            geom_max_x = x1
        if y1 > geom_max_y:
            geom_max_y = y1
        return True

    for ent in entities:
        etype = str(ent.get("type", "")).lower()
        if etype in ("polyline", "line"):
            pts = ent.get("points") or ent.get("vertices") or []
            if not _update_xy_many(pts):
                for pt in pts:
                    if len(pt) >= 2:
                        _update_xy(pt[0], pt[1], use_text_bucket=False)
        elif etype == "3dface":
            pts = ent.get("vertices", []) or []
            if not _update_xy_many(pts):
                for pt in pts:
                    if len(pt) >= 2:
                        _update_xy(pt[0], pt[1], use_text_bucket=False)
        elif etype == "point":
            pos = ent.get("position", [])
            if len(pos) >= 2:
                _update_xy(pos[0], pos[1], use_text_bucket=False)
        elif etype == "text":
            pos = ent.get("position", [])
            if len(pos) >= 2:
                _update_xy(pos[0], pos[1], use_text_bucket=True)

    if has_geom:
        return (geom_min_x, geom_max_x, geom_min_y, geom_max_y)
    if has_text:
        return (text_min_x, text_max_x, text_min_y, text_max_y)
    return None


from gui.snt_bulk_allocations import bulk_snt_allocations


@bulk_snt_allocations()
def _decode_snt_attachment(
    snt_path_str: str,
    *,
    cached_parsed=None,
    selected_layers=None,
    display_mode: str = "overlay",
    override_enabled: bool = False,
    override_color=(0, 255, 80),
    progress_cb=None,
    is_cancelled=None,
    prepare_vectors=False,
) -> Optional[Dict]:
    """Qt-free Attach decode phase: file read → filter → convert → bounds.

    Runs on ``SNTAttachWorker`` so million-entity files no longer freeze the
    GUI at "Processing … 0%". Returns the attachment dict (without
    ``_snt_item``/``actor_cache_map``, which the GUI thread wires up).
    Raises ``_SntCancelled`` when ``is_cancelled`` becomes true.
    """
    snt_path = Path(snt_path_str)
    _attach_t0 = time.perf_counter()
    if isinstance(cached_parsed, dict) and cached_parsed:
        parsed = cached_parsed
    else:
        parsed = _read_snt_file(
            str(snt_path), progress_cb=progress_cb, is_cancelled=is_cancelled,
        )
    _read_ms = (time.perf_counter() - _attach_t0) * 1000.0
    if is_cancelled is not None and is_cancelled():
        raise _SntCancelled()

    color_override = override_color if override_enabled else None
    raw_entities = parsed.get("entities", [])
    if is_cancelled is not None and is_cancelled():
        raise _SntCancelled()
    _stats_t0 = time.perf_counter()
    layer_stats = _snt_layer_stats_from_parsed(parsed)
    _stats_ms = (time.perf_counter() - _stats_t0) * 1000.0

    _filter_t0 = time.perf_counter()
    filtered: List[Dict] = []
    if selected_layers is None and not color_override:
        # Common full-attach case: no per-entity filtering needed.
        filtered = raw_entities if isinstance(raw_entities, list) else list(raw_entities)
    else:
        for ent in raw_entities:
            lname = ent.get("layer", "0")
            if (selected_layers is not None
                    and lname not in selected_layers
                    and not _is_system_layer(lname)):
                continue
            if color_override and not _is_system_layer(lname):
                ent = {**ent, "color": color_override}
            filtered.append(ent)
    _filter_ms = (time.perf_counter() - _filter_t0) * 1000.0

    if progress_cb is not None:
        try:
            progress_cb(f"convert:{len(filtered)}")
        except Exception:
            pass
    if is_cancelled is not None and is_cancelled():
        raise _SntCancelled()
    _convert_t0 = time.perf_counter()
    render_entities = _convert_snt_entities(filtered, progress_cb, is_cancelled)
    _convert_ms = (time.perf_counter() - _convert_t0) * 1000.0
    _bounds_t0 = time.perf_counter()
    if progress_cb is not None:
        progress_cb("bounds")
    bounds = _compute_snt_2d_bounds(render_entities)
    _bounds_ms = (time.perf_counter() - _bounds_t0) * 1000.0
    print(
        f"[SNT attach] PERF {snt_path.name} "
        f"read={_read_ms:.0f}ms stats={_stats_ms:.0f}ms "
        f"filter={_filter_ms:.0f}ms convert={_convert_ms:.0f}ms "
        f"bounds={_bounds_ms:.0f}ms entities={len(raw_entities)}"
    )

    try:
        full_path = str(snt_path.resolve())
    except Exception:
        full_path = str(snt_path)
    attachment = {
        "filename":  snt_path.name,
        "full_path": full_path,
        "mode":      display_mode,
        "entities":  render_entities,
        "bounds": bounds,
        "entity_count": len(raw_entities),
        "selected_layers": selected_layers,
        "layer_stats": layer_stats,
        "override_enabled": override_enabled,
        "override_color": override_color,
        "parsed": parsed,
    }
    if prepare_vectors:
        if progress_cb is not None:
            progress_cb("prepare")
        started = time.perf_counter()
        prj_blocks = _parse_snt_adjacent_prj_blocks(full_path)
        corrected = _apply_prj_precision_to_block_entities(
            render_entities, prj_blocks,
            snt_uses_float64=bool(parsed.get("use_float64", False)))
        if is_cancelled is not None and is_cancelled():
            raise _SntCancelled()
        from gui.native_vector_overlay import group_entities
        groups = group_entities(corrected, is_cancelled=is_cancelled)
        attachment["_prepared_prj_blocks"] = prj_blocks
        attachment["_prepared_source_entities"] = corrected
        attachment["_prepared_vector_groups"] = groups
        print(f"[SNT attach] PERF {snt_path.name} worker_vector_prepare="
              f"{(time.perf_counter() - started) * 1000:.0f}ms")
    return attachment


class SNTAttachWorker(QThread):
    """Background Attach decoder: file read + convert + bounds, off the GUI thread.

    VTK/native actor creation still happens on the GUI thread afterwards
    (``_render_snt_in_vtk``), but the long "Processing …" freeze at 0% — the
    full native decode of every entity body — now runs here with live
    progress and a working Cancel button.
    """

    progress = Signal(int, int, str)
    file_decoded = Signal(object)
    all_decoded = Signal(object)
    failed = Signal(str)

    def __init__(self, jobs: List[Dict]) -> None:
        super().__init__()
        self.jobs: List[Dict] = list(jobs)
        self._cancelled: bool = False

    def cancel(self) -> None:
        self._cancelled = True

    def _is_cancelled(self) -> bool:
        return bool(self._cancelled)

    def run(self) -> None:
        try:
            decoded: List[Dict] = []
            total = len(self.jobs)
            for idx, job in enumerate(self.jobs):
                if self._cancelled:
                    return
                name = job.get("filename") or Path(str(job.get("snt_path", ""))).name

                def _cb(value, _idx=idx, _name=name, _total=total):
                    if isinstance(value, str) and value.startswith("convert:"):
                        parts = value.split(":")
                        done = int(parts[1]) if len(parts) > 2 else 0
                        count = max(1, int(parts[2])) if len(parts) > 2 else 1
                        fraction = min(1.0, done / count)
                        self.progress.emit(_idx * 1000 + 700 + int(fraction * 200), _total * 1000,
                                           f"Converting {_name}... {done:,} / {count:,} entities")
                    elif value == "bounds":
                        self.progress.emit(_idx * 1000 + 900, _total * 1000,
                                           f"Calculating bounds for {_name}...")
                    elif value == "prepare":
                        self.progress.emit(_idx * 1000 + 950, _total * 1000,
                                           f"Preparing GPU geometry for {_name}...")
                    else:
                        try:
                            n = int(value)
                        except Exception:
                            n = 0
                        count = max(1, int(job.get("entity_count", 0) or n or 1))
                        self.progress.emit(
                            _idx * 1000 + min(699, int(n / count * 700)), _total * 1000,
                            f"Processing {_name}... {n:,} entities decoded",
                        )

                self.progress.emit(idx * 1000, total * 1000, f"Processing {name}...")
                try:
                    attachment = _decode_snt_attachment(
                        str(job["snt_path"]),
                        cached_parsed=job.get("cached_parsed"),
                        selected_layers=job.get("selected_layers"),
                        display_mode=job.get("display_mode", "overlay"),
                        override_enabled=bool(job.get("override_enabled", False)),
                        override_color=job.get("override_color", (0, 255, 80)),
                        progress_cb=_cb,
                        is_cancelled=self._is_cancelled,
                        prepare_vectors=bool(job.get("prepare_vectors", False)),
                    )
                except _SntCancelled:
                    return
                if self._cancelled:
                    return
                attachment["_snt_job_index"] = idx
                decoded.append(attachment)
                self.file_decoded.emit(attachment)
            if not self._cancelled:
                self.all_decoded.emit(decoded)
        except _SntCancelled:
            return
        except Exception as exc:
            if not self._cancelled:
                self.failed.emit(f"SNT attach failed: {exc}\n{traceback.format_exc()}")


