# LAYER SELECTION DIALOG
# â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€

def _extract_drawing_color(drawing: dict) -> Tuple[int, int, int]:
    color = drawing.get("color") or drawing.get("original_color") or drawing.get("original_text_color") or (255, 255, 255)
    if not isinstance(color, (list, tuple)) or len(color) < 3:
        return (255, 255, 255)
    try:
        values = [float(color[0]), float(color[1]), float(color[2])]
    except (TypeError, ValueError):
        return (255, 255, 255)
    if max(abs(v) for v in values) <= 1.0:
        values = [v * 255.0 for v in values]
    return tuple(max(0, min(255, int(round(v)))) for v in values)

def _rgb_to_aci(rgb: Tuple[int, int, int]) -> int:
    best_aci = 7  # Default to white
    min_dist = float('inf')
    for aci, aci_rgb in _ACI_RGB.items():
        dist = sum((a - b) ** 2 for a, b in zip(rgb, aci_rgb))
        if dist < min_dist:
            min_dist = dist
            best_aci = aci
    return best_aci


def _ensure_snt_direct_state(attachment):
    """Attachment-scoped dirty state consumed by snt_core.direct_write()."""
    if not isinstance(attachment, dict):
        return None
    state = attachment.get("_snt_direct_changes")
    if isinstance(state, dict):
        return state
    parsed = attachment.get("parsed") if isinstance(attachment.get("parsed"), dict) else {}
    base_names = {
        str(layer.get("name", "0"))
        for layer in list(parsed.get("layers", []) or [])
        if isinstance(layer, dict)
    }
    state = {
        "base_layer_names": set(base_names),
        "added_layers": {},
        "renamed_layers": {},
        "updated_layers": {},
        "recolored_layers": {},
        "deleted_layers": set(),
        "deleted_entity_ids": set(),
        "moved_entities": {},
        "updated_entities": {},
        "block_boundary_layers": set(),
    }
    attachment["_snt_direct_changes"] = state
    return state


def _record_snt_added_layer(attachment, layer):
    state = _ensure_snt_direct_state(attachment)
    if state is None or not isinstance(layer, dict):
        return
    name = str(layer.get("name", "") or "").strip()
    if not name or name in state["base_layer_names"]:
        return
    color = layer.get("color", (255, 255, 255))
    try:
        rgb = (int(color[0]), int(color[1]), int(color[2]))
    except Exception:
        rgb = (255, 255, 255)
    state["added_layers"][name] = {
        "name": name,
        "color_aci": _rgb_to_aci(rgb),
        "linetype": str(layer.get("linetype", "CONTINUOUS") or "CONTINUOUS"),
        "flags": int(layer.get("flags", 0) or 0),
    }
    # The layer does not exist in the source SNT, so there are no original
    # records to recolor. Keeping it out of recolored_layers preserves the
    # fast bulk-copy path for add-level + add-entity saves.
    state["recolored_layers"].pop(name, None)


def _record_snt_layer_rename(attachment, old_name, new_name):
    state = _ensure_snt_direct_state(attachment)
    if state is None:
        return
    old_name = str(old_name or "").strip()
    new_name = str(new_name or "").strip()
    if not old_name or not new_name or old_name == new_name:
        return
    if old_name in state["added_layers"]:
        spec = dict(state["added_layers"].pop(old_name))
        spec["name"] = new_name
        state["added_layers"][new_name] = spec
        if old_name in state["recolored_layers"]:
            state["recolored_layers"][new_name] = state["recolored_layers"].pop(old_name)
        if old_name in state["updated_layers"]:
            state["updated_layers"][new_name] = state["updated_layers"].pop(old_name)
        return
    original = old_name
    for source_name, current_name in list(state["renamed_layers"].items()):
        if current_name == old_name:
            original = source_name
            break
    state["renamed_layers"][original] = new_name
    if old_name in state["recolored_layers"]:
        state["recolored_layers"][new_name] = state["recolored_layers"].pop(old_name)
    if old_name in state["updated_layers"]:
        state["updated_layers"][new_name] = state["updated_layers"].pop(old_name)

    # Propagate block boundary role through renames
    blk_set = state.get("block_boundary_layers")
    if isinstance(blk_set, set) and old_name in blk_set:
        blk_set.discard(old_name)
        blk_set.add(new_name)


def _record_snt_layer_color(attachment, layer_name, rgb):
    state = _ensure_snt_direct_state(attachment)
    if state is None:
        return
    try:
        rgb = (int(rgb[0]), int(rgb[1]), int(rgb[2]))
    except Exception:
        return
    layer_name = str(layer_name or "").strip()
    state["updated_layers"].setdefault(layer_name, {})["color_aci"] = _rgb_to_aci(rgb)
    if layer_name in state["added_layers"]:
        state["added_layers"][layer_name]["color_aci"] = _rgb_to_aci(rgb)
        state["recolored_layers"].pop(layer_name, None)
    else:
        state["recolored_layers"][layer_name] = rgb


def _record_snt_deleted_entity(attachment, entity):
    state = _ensure_snt_direct_state(attachment)
    if state is None or not isinstance(entity, dict):
        return
    entity_id = entity.get("_snt_entity_id")
    if entity_id is None:
        return
    entity_id = int(entity_id)
    state["deleted_entity_ids"].add(entity_id)
    state["moved_entities"].pop(entity_id, None)
    state["updated_entities"].pop(entity_id, None)


def _record_snt_moved_entity(attachment, entity, target_layer):
    state = _ensure_snt_direct_state(attachment)
    if state is None or not isinstance(entity, dict):
        return
    entity_id = entity.get("_snt_entity_id")
    if entity_id is None:
        return
    entity_id = int(entity_id)
    if entity_id not in state["deleted_entity_ids"]:
        state["moved_entities"][entity_id] = str(target_layer)


def _record_snt_deleted_layer(attachment, layer_name, entities):
    state = _ensure_snt_direct_state(attachment)
    if state is None:
        return
    layer_name = str(layer_name or "").strip()
    for ent in list(entities or []):
        if isinstance(ent, dict) and str(ent.get("layer", "0")) == layer_name:
            _record_snt_deleted_entity(attachment, ent)
    if layer_name in state["added_layers"]:
        state["added_layers"].pop(layer_name, None)
    else:
        original = layer_name
        for source_name, current_name in list(state["renamed_layers"].items()):
            if current_name == layer_name:
                original = source_name
                state["renamed_layers"].pop(source_name, None)
                break
        state["deleted_layers"].add(original)
    state["updated_layers"].pop(layer_name, None)
    state["recolored_layers"].pop(layer_name, None)


def _snt_direct_has_changes(attachment, pending_entities=None):
    state = _ensure_snt_direct_state(attachment)
    if state is None:
        return False
    parsed = attachment.get("parsed") if isinstance(attachment, dict) else None
    unsaved_parsed = []
    if isinstance(parsed, dict):
        unsaved_parsed = [
            ent for ent in list(parsed.get("entities", []) or [])
            if isinstance(ent, dict) and ent.get("_snt_entity_id") is None
        ]
    return bool(
        pending_entities
        or unsaved_parsed
        or state["added_layers"]
        or state["renamed_layers"]
        or state["updated_layers"]
        or state["recolored_layers"]
        or state["deleted_layers"]
        or state["deleted_entity_ids"]
        or state["moved_entities"]
        or state["updated_entities"]
    )


def _reset_snt_direct_state(attachment):
    if not isinstance(attachment, dict):
        return
    parsed = attachment.get("parsed") if isinstance(attachment.get("parsed"), dict) else {}
    for entity_id, ent in enumerate(list(parsed.get("entities", []) or [])):
        if isinstance(ent, dict):
            ent["_snt_entity_id"] = int(entity_id)
    attachment.pop("_snt_direct_changes", None)
    _ensure_snt_direct_state(attachment)


def save_snt_attachment_to_disk(attachment, pending_entities=None):
    """Persist dirty changes with snt_core.direct_write(), never through DXF."""
    import snt_core

    if not isinstance(attachment, dict):
        raise ValueError("Invalid SNT attachment.")
    filepath = attachment.get("full_path")
    parsed = attachment.get("parsed")
    if not filepath or not isinstance(parsed, dict):
        raise ValueError("SNT attachment has no path or parsed model.")
    if not hasattr(snt_core, "direct_write"):
        raise RuntimeError(
            "Installed snt_core does not provide direct_write(). Install the matched "
            "fast-writer wheel. Normal Save will not fall back to a lossy/slow DXF rebuild."
        )

    state = _ensure_snt_direct_state(attachment)
    pending_entities = list(pending_entities or [])
    added = [
        ent for ent in list(parsed.get("entities", []) or [])
        if isinstance(ent, dict) and ent.get("_snt_entity_id") is None
    ]
    added.extend(ent for ent in pending_entities if isinstance(ent, dict))

    return snt_core.direct_write(
        filepath,
        added_entities=added,
        deleted_entity_ids=sorted(state["deleted_entity_ids"]),
        moved_entities=dict(state["moved_entities"]),
        updated_entities=dict(state["updated_entities"]),
        added_layers=list(state["added_layers"].values()),
        renamed_layers=dict(state["renamed_layers"]),
        updated_layers=dict(state["updated_layers"]),
        recolored_layers=dict(state["recolored_layers"]),
        deleted_layers=sorted(state["deleted_layers"]),
        metadata_updates=dict(attachment.get("_snt_metadata_updates", {}) or {}),
        validate=True,
    )

def rebuild_snt_attachment(app, attachment):
    if not isinstance(attachment, dict):
        return

    item = attachment.get("_snt_item")
    if not item:
        return

    try:
        item.attachment = attachment
    except Exception:
        pass

    renderer = getattr(app.vtk_widget, "renderer", None)
    if renderer:
        for lname, actors in list(item.actor_cache.items()):
            for actor in actors:
                try:
                    if hasattr(actor, "dispose"):
                        actor.dispose()
                    renderer.RemoveActor(actor)
                except Exception:
                    pass

    item.actor_cache.clear()
    cache_map = attachment.get("actor_cache_map")
    if isinstance(cache_map, dict):
        cache_map.clear()
    else:
        attachment["actor_cache_map"] = {}

    parsed = attachment.get("parsed")
    if not isinstance(parsed, dict) or not parsed:
        return

    try:
        item.cached_parsed = parsed
    except Exception:
        pass

    raw_entities = [ent for ent in list(parsed.get("entities", []) or []) if isinstance(ent, dict)]
    entity_count = len(raw_entities)
    item.update_entity_count(entity_count)
    attachment["entity_count"] = entity_count

    layer_stats = _snt_layer_stats_from_parsed(parsed)
    item.layer_stats_cache = list(layer_stats)
    attachment["layer_stats"] = layer_stats

    filtered = []
    color_override = item.override_color if item.override_enabled else None
    for ent in raw_entities:
        lname = ent.get("layer", "0")
        is_system = _is_system_layer(lname)
        if item.selected_layers is not None and lname not in item.selected_layers and not is_system:
            continue
        if color_override and not is_system:
            ent = {**ent, "color": color_override}
        filtered.append(ent)

    if hasattr(item, "_sync_attachment_runtime_state"):
        try:
            item._sync_attachment_runtime_state()
        except Exception:
            pass

    dlg = item._find_parent_dialog()
    if not dlg:
        dlg = getattr(app, "snt_dialog", None)
        
    if not dlg:
        from gui.snt_attachment import MultiSNTAttachmentDialog
        dlg = MultiSNTAttachmentDialog(app)
        
    if dlg:
        render_entities = dlg._convert_entities(filtered)
        attachment["entities"] = render_entities
        attachment["bounds"] = dlg._compute_2d_bounds(render_entities)
        dlg._render_snt_in_vtk(attachment)
        item._force_render(dlg)

class _CenteredCheckBox(QWidget):
    """Classic-style checkbox cell for use inside a QTableWidget.

    Self-paints via QPainter so it is immune to QCheckBox stylesheet rules.
    The whole cell is a click target.
    """

    stateChanged = Signal(int)
    toggled = Signal(bool)

    _BOX_SIZE = 18

    def __init__(self, parent=None, *, hit_padding: int = 10):
        super().__init__(parent)
        self._hit = hit_padding
        self._checked = False
        self._hover   = False
        self.setMouseTracking(True)
        self.setCursor(Qt.PointingHandCursor)
        self.setMinimumHeight(self._BOX_SIZE + self._hit)
        self.setMinimumWidth(self._BOX_SIZE + self._hit * 2)

    def sizeHint(self):
        return QSize(self._BOX_SIZE + self._hit * 2,
                     self._BOX_SIZE + self._hit)

    def isChecked(self):
        return self._checked

    def setChecked(self, checked):
        checked = bool(checked)
        if checked == self._checked:
            return
        self._checked = checked
        self.update()
        self.toggled.emit(self._checked)
        state_value = (
            Qt.CheckState.Checked.value
            if self._checked
            else Qt.CheckState.Unchecked.value
        )
        self.stateChanged.emit(int(state_value))

    def checkState(self):
        return Qt.CheckState.Checked if self._checked else Qt.CheckState.Unchecked

    def setCheckState(self, state):
        try:
            state_value = state.value if hasattr(state, "value") else state
            state_value = int(state_value)
        except Exception:
            state_value = int(Qt.CheckState.Unchecked.value)
        self.setChecked(state_value == int(Qt.CheckState.Checked.value))

    def mousePressEvent(self, event):
        if event.button() == Qt.LeftButton:
            self.setChecked(not self._checked)
            event.accept()
            return
        super().mousePressEvent(event)

    def enterEvent(self, event):
        self._hover = True
        self.update()
        super().enterEvent(event)

    def leaveEvent(self, event):
        self._hover = False
        self.update()
        super().leaveEvent(event)

    def paintEvent(self, event):
        p = QPainter(self)
        p.setRenderHint(QPainter.Antialiasing, False)
        cx = self.width()  // 2
        cy = self.height() // 2
        x  = cx - self._BOX_SIZE // 2
        y  = cy - self._BOX_SIZE // 2
        s  = self._BOX_SIZE
        border = QColor("#222222") if self._checked else QColor("#8a8a8a")
        if self._hover and not self._checked:
            border = QColor("#555555")
        p.fillRect(x, y, s, s, QColor("#ffffff"))
        pen = QPen(border)
        pen.setWidth(1)
        p.setPen(pen)
        p.drawRect(x, y, s - 1, s - 1)
        if self._checked:
            check = QPen(QColor("#222222"))
            check.setWidth(2)
            check.setCapStyle(Qt.RoundCap)
            check.setJoinStyle(Qt.RoundJoin)
            p.setPen(check)
            p.setRenderHint(QPainter.Antialiasing, True)
            p.drawLine(x + 3,  y + s // 2,      x + s // 2 - 1, y + s - 4)
            p.drawLine(x + s // 2 - 1, y + s - 4, x + s - 3,     y + 3)
        p.end()


class SNTLayerSelectionDialog(QDialog):
    def __init__(self, snt_path: Path, parent_item=None, app=None):
        # Parentless top-level window:
        # avoids Windows desktop mini-bars on minimize for owned dialogs.
        super().__init__(None, Qt.Window)
        self.setAttribute(Qt.WA_QuitOnClose, False)

        # Keep Level Manager as a normal non-modal tool window. Do not force
        # always-on-top here; Settings and other modal dialogs must be able to
        # come in front without creating hidden-modal deadlocks.
        self.setWindowFlag(Qt.WindowStaysOnTopHint, False)
        self.snt_path    = snt_path
        self.parent_item = parent_item
        self.app         = app if app is not None else getattr(parent_item, 'app', None)
        if self.app is None and parent_item is not None:
            try:
                _pdlg = parent_item._find_parent_dialog()
                self.app = getattr(_pdlg, 'app', None)
            except Exception:
                self.app = None
        self.setWindowTitle(f"Layer Display & Level Manager - {snt_path.name}")
        self.setModal(False)
        self.setWindowModality(Qt.NonModal)
        self.resize(550, 600)

        self.attachment = None
        self.attachment = self._get_live_attachment()
        _ensure_snt_direct_state(self.attachment)
        self._live_counts_timer = None
        self.newly_created_layers = set()

        # Register count refresh callbacks on the digitizer to catch drawing events
        digitizer = getattr(self.app, "digitizer", None) if self.app else None
        if digitizer:
            self._refresh_counts_cb = self._refresh_layers_on_draw
            digitizer.add_drawing_finalized_callback(self._refresh_counts_cb)
            digitizer.add_drawing_removed_callback(self._refresh_counts_cb)

        self._init_ui()
        self._load_layers()
        self._start_live_counts_timer()
        # Apply dark title bar on Windows
        try:
            from gui.theme_manager import ThemeManager
            ThemeManager.apply_native_window_theme(self)
        except Exception:
            pass

    def _get_live_parent_item(self):
        item = getattr(self, "parent_item", None)
        if _qt_object_is_alive(item):
            return item

        app = getattr(self, "app", None)
        dlg = getattr(app, "snt_dialog", None) if app is not None else None
        if not _qt_object_is_alive(dlg):
            self.parent_item = None
            return None

        target_name = str(self.snt_path.name or "").lower()
        for candidate in list(getattr(dlg, "snt_items", []) or []):
            if not _qt_object_is_alive(candidate):
                continue
            try:
                candidate_name = str(candidate.snt_path.name or "").lower()
            except Exception:
                continue
            if candidate_name == target_name:
                self.parent_item = candidate
                return candidate

        self.parent_item = None
        return None

    def _get_live_attachment(self):
        parent_item = self._get_live_parent_item()
        if parent_item is not None:
            resolver = getattr(parent_item, "_resolve_primary_attachment", None)
            if callable(resolver):
                try:
                    att = resolver()
                except Exception:
                    att = None
                if isinstance(att, dict):
                    self.attachment = att
                    try:
                        parent_item.attachment = att
                    except Exception:
                        pass
                    return att

        current = getattr(self, "attachment", None)
        if isinstance(current, dict):
            return current

        app = getattr(self, "app", None)
        if app is None:
            return None

        try:
            target_full = str(self.snt_path.resolve()).lower()
        except Exception:
            target_full = str(self.snt_path).lower()
        target_name = os.path.basename(str(self.snt_path.name or "")).lower()

        for att in list(getattr(app, "snt_attachments", []) or []):
            if not isinstance(att, dict):
                continue
            att_name = os.path.basename(str(att.get("filename", "") or "")).lower()
            att_full = str(att.get("full_path", "") or "").lower()
            if (
                (target_name and att_name == target_name)
                or (target_full and att_full and att_full == target_full)
                or (target_name and att_full and os.path.basename(att_full) == target_name)
            ):
                self.attachment = att
                return att
        return None

    def _sync_runtime_attachment_state(self):
        parent_item = self._get_live_parent_item()
        if parent_item is not None:
            sync = getattr(parent_item, "_sync_attachment_runtime_state", None)
            if callable(sync):
                try:
                    att = sync()
                except Exception:
                    att = None
                if isinstance(att, dict):
                    self.attachment = att
                    try:
                        parent_item.attachment = att
                    except Exception:
                        pass
                    return att
        return self._get_live_attachment()

    def _start_live_counts_timer(self):
        if self._live_counts_timer is not None:
            return
        self._live_counts_timer = QTimer(self)
        self._live_counts_timer.setInterval(750)
        self._live_counts_timer.timeout.connect(self._poll_live_layer_counts)
        self._live_counts_timer.start()

    def _poll_live_layer_counts(self):
        if not self.isVisible():
            return
        try:
            from PySide6.QtWidgets import QApplication as _QA
            from PySide6.QtCore import Qt as _Qt
            panning_button = getattr(self.app, "panning_button", "scroll") if hasattr(self, "app") and self.app else "scroll"
            if bool(_QA.mouseButtons() & _Qt.MiddleButton):
                return
        except Exception:
            pass
        try:
            layers_info = list(self._build_layers_info_with_live_counts())
        except Exception:
            return

        latest_map = {name: (count, color) for name, count, color in layers_info}
        if not latest_map and self.table.rowCount() > 0:
            return

        structure_changed = False
        for row in range(self.table.rowCount()):
            name_item = self.table.item(row, 4)
            if name_item is None:
                continue
            name = str(name_item.data(Qt.UserRole) or name_item.text() or "")
            if name not in latest_map:
                structure_changed = True
                break
            count, color = latest_map[name]
            count_item = self.table.item(row, 5)
            wanted_count = f"{int(count):,}"
            if count_item is not None and count_item.text() != wanted_count:
                count_item.setText(wanted_count)
            color_item = self.table.item(row, 3)
            if color_item is not None:
                r, g, b = color if color else _DEFAULT_COLOR
                color_item.setBackground(QColor(int(r), int(g), int(b)))
                color_item.setToolTip(f"RGB({int(r)}, {int(g)}, {int(b)})")

        if structure_changed:
            try:
                self._load_layers()
            except Exception:
                pass

    def _build_layers_info_with_live_counts(self):
        attachment = self._get_live_attachment()
        parent_item = self._get_live_parent_item()

        parsed = attachment.get("parsed") if isinstance(attachment, dict) else None
        if (not isinstance(parsed, dict) or not parsed) and parent_item is not None:
            parsed = getattr(parent_item, "cached_parsed", None)

        stats = {}
        ordered_names = []

        if isinstance(parsed, dict) and parsed:
            for lname, count, color in _snt_layer_stats_from_parsed(parsed):
                stats[lname] = {"count": int(count), "color": tuple(color)}
                ordered_names.append(lname)

        if not ordered_names and parent_item is not None:
            # Pre-attach state: only the header-only summary exists (no
            # geometry decoded yet). Show its layer table + header counts so
            # the Level Manager is usable without triggering a full parse.
            try:
                summary = getattr(parent_item, "snt_summary", None)
                cached_stats = getattr(parent_item, "layer_stats_cache", None)
                if isinstance(summary, dict) and summary.get("layers"):
                    counts = summary.get("layer_counts") or {}
                    for layer in summary.get("layers", []) or []:
                        if not isinstance(layer, dict):
                            continue
                        lname = str(layer.get("name", "0"))
                        if lname not in stats:
                            stats[lname] = {
                                "count": int(counts.get(lname, 0) or 0),
                                "color": tuple(layer.get("color", _DEFAULT_COLOR)),
                            }
                            ordered_names.append(lname)
                elif cached_stats:
                    for row in list(cached_stats):
                        try:
                            lname, count, color = row
                            lname = str(lname)
                            if lname not in stats:
                                stats[lname] = {"count": int(count), "color": tuple(color)}
                                ordered_names.append(lname)
                        except Exception:
                            continue
            except Exception:
                pass

        app = getattr(self, "app", None)
        digitizer = getattr(app, "digitizer", None) if app is not None else None
        target_file = os.path.basename(str(self.snt_path.name or "")).lower()
        active_file = os.path.basename(str(getattr(app, "active_snt_filename", "") or "")).lower()
        active_layer = getattr(app, "active_snt_layer", None) if app else None

        if digitizer is not None:
            all_drawings = list(getattr(digitizer, "drawings", []) or [])
            live_drawings = [
                d for d in all_drawings
                if isinstance(d, dict) and not d.get("snt_committed")
            ]
            for d in live_drawings:
                lname = str(d.get("layer", "") or "").strip()
                if not lname or lname == "DIGITIZER":
                    continue

                owner_file = os.path.basename(str(d.get("snt_file", "") or "")).lower()
                if owner_file:
                    # Drawing is explicitly tagged to a file: must match.
                    if owner_file != target_file:
                        continue
                elif active_file and active_file != target_file:
                    # No drawing tag, but an active file is set in the app:
                    # trust the active file. If it doesn't match this dialog's
                    # file, skip — the drawing belongs to the other SNT.
                    continue
                elif not active_file:
                    # No drawing tag and no active file: if the layer is in
                    # the current SNT's known layers, count it. (Rare path.)
                    known_layers = {
                        str(x.get("name", ""))
                        for x in (parsed.get("layers", []) or [])
                        if isinstance(x, dict)
                    }
                    if lname not in known_layers:
                        continue
                # else: drawing has no `snt_file`, `active_file` is set and
                # matches `target_file` — falls through and gets counted.

                if lname not in stats:
                    stats[lname] = {
                        "count": 0,
                        "color": _extract_drawing_color(d),
                    }
                    ordered_names.append(lname)
                stats[lname]["count"] = int(stats[lname]["count"]) + 1

        layers_info = [
            (lname, int(stats[lname]["count"]), tuple(stats[lname].get("color", _DEFAULT_COLOR)))
            for lname in ordered_names
        ]

        if parent_item is not None:
            try:
                if isinstance(parsed, dict) and parsed:
                    parent_item.cached_parsed = parsed
                parent_item.layer_stats_cache = list(layers_info)
            except Exception:
                pass

        if isinstance(attachment, dict):
            self.attachment = attachment
            attachment["layer_stats"] = list(layers_info)
            if isinstance(parsed, dict) and parsed:
                attachment["parsed"] = parsed

        return layers_info

    def closeEvent(self, event):
        try:
            if self._live_counts_timer is not None:
                self._live_counts_timer.stop()
        except Exception:
            pass

        digitizer = getattr(self.app, "digitizer", None) if self.app else None
        if digitizer:
            if hasattr(self, "_refresh_counts_cb") and self._refresh_counts_cb:
                try:
                    digitizer.remove_drawing_finalized_callback(self._refresh_counts_cb)
                    digitizer.remove_drawing_removed_callback(self._refresh_counts_cb)
                except Exception:
                    pass
            if hasattr(self, "_auto_remove_cb") and self._auto_remove_cb:
                try:
                    digitizer.remove_drawing_removed_callback(self._auto_remove_cb)
                except Exception:
                    pass

        super().closeEvent(event)

