# SBM FILE ITEM WIDGET
# (Row in file list for loaded .sbm files — Layers button reopens SBMLayersDialog)

class SBMFileItem(QWidget):
    """Row widget for a loaded .sbm file in the SNT attachment file list."""
    remove_requested = Signal(object)

    def __init__(self, sbm_path: Path, categories: List[Dict], app=None, parent=None):
        super().__init__(parent)
        self.sbm_path = Path(sbm_path)
        self.categories = categories
        self._app = app
        self.entity_count = sum(len(c.get("subclasses", [])) for c in categories)
        self._sbm_dialog: Optional["SBMLayersDialog"] = None
        self._init_ui()

    @property
    def app(self):
        if self._app is not None:
            return self._app
        p = self.parent()
        while p is not None and not isinstance(p, MultiSNTAttachmentDialog):
            p = p.parent()
        return p.app if p else None

    def is_checked(self) -> bool:
        return self.checkbox.isChecked()

    def _init_ui(self):
        self.setObjectName("sntFileItemRow")
        self.setFixedHeight(44)

        layout = QHBoxLayout(self)
        layout.setContentsMargins(10, 0, 10, 0)
        layout.setSpacing(8)
        layout.setAlignment(Qt.AlignVCenter)

        self.checkbox = QCheckBox()
        self.checkbox.setChecked(True)
        self.checkbox.setCursor(Qt.PointingHandCursor)
        layout.addWidget(self.checkbox)

        self.name_label = QLabel(self.sbm_path.name)
        self.name_label.setObjectName("sntNameLabel")
        layout.addWidget(self.name_label, 1)

        self.badge = QLabel("SBM")
        self.badge.setObjectName("sbmBadge")
        self.badge.setFixedSize(48, 30)
        self.badge.setAlignment(Qt.AlignCenter)
        layout.addWidget(self.badge)

        self.count_label = QLabel(f"{self.entity_count} Entities")
        self.count_label.setObjectName("sntCountBadge")
        self.count_label.setFixedSize(110, 30)
        self.count_label.setAlignment(Qt.AlignCenter)
        layout.addWidget(self.count_label)

        self.layers_btn = QPushButton("Layers")
        self.layers_btn.setObjectName("sntRowBtn")
        self.layers_btn.setFixedSize(76, 30)
        self.layers_btn.setCursor(Qt.PointingHandCursor)
        self.layers_btn.setToolTip("Open SBM layers for class-based digitizing")
        self.layers_btn.clicked.connect(self._open_sbm_layers_dialog)
        layout.addWidget(self.layers_btn)

        self.rm_btn = QPushButton("X")
        self.rm_btn.setObjectName("sntRemoveBtn")
        self.rm_btn.setFixedSize(30, 30)
        self.rm_btn.setCursor(Qt.PointingHandCursor)
        self.rm_btn.setToolTip("Remove SBM file")
        self.rm_btn.clicked.connect(lambda: self.remove_requested.emit(self))
        layout.addWidget(self.rm_btn)

        self.refresh_theme()

    def refresh_theme(self):
        c = ThemeColors
        accent = c.get('accent')
        self.setStyleSheet(f"""
            QWidget#sntFileItemRow {{
                background: {c.get('bg_secondary')};
                border: 1px solid {c.get('border_light')};
                border-radius: 8px;
            }}
            QWidget#sntFileItemRow:hover {{
                background: {c.get('bg_input')};
                border-color: {c.get('dialog_primary_border')};
            }}
            QCheckBox {{ background: transparent; }}
            QCheckBox::indicator {{
                width: 16px; height: 16px; border-radius: 3px;
                border: 2px solid {c.get('border_light')};
                background-color: {c.get('bg_input')};
            }}
            QCheckBox::indicator:checked {{
                background-color: {accent}; border-color: {accent};
            }}
            QLabel#sntNameLabel {{
                color: {c.get('text_primary')}; font-weight: 700; font-size: 12px;
                background: transparent; border: none;
            }}
            QLabel#sbmBadge {{
                background: #e67e22; color: white; border-radius: 6px;
                font-size: 12px; font-weight: 700;
            }}
            QLabel#sntCountBadge {{
                background: {c.get('bg_input')}; color: {c.get('text_primary')};
                border: 1px solid {c.get('border_light')}; border-radius: 6px;
                font-size: 12px; font-weight: 700;
            }}
            QPushButton#sntRowBtn {{
                background: {c.get('bg_input')}; color: {c.get('text_primary')};
                border: 1px solid {c.get('border_light')}; border-radius: 6px;
                font-size: 12px; font-weight: 700; padding: 0px;
            }}
            QPushButton#sntRowBtn:hover {{ border-color: {accent}; color: {accent}; }}
            QPushButton#sntRemoveBtn {{
                background: {c.get('danger')}; color: white; border: none;
                border-radius: 6px; font-size: 12px; font-weight: 700; padding: 0px;
            }}
            QPushButton#sntRemoveBtn:hover {{ background: {c.get('danger_hover')}; }}
        """)

    def _open_sbm_layers_dialog(self):
        """Open or reshow the SBMLayersDialog for this SBM file."""
        if self._sbm_dialog is not None:
            try:
                if self._sbm_dialog.isMinimized():
                    self._sbm_dialog.showNormal()
                    self._sbm_dialog.raise_()
                    self._sbm_dialog.activateWindow()
                    return
                elif self._sbm_dialog.isVisible():
                    self._sbm_dialog.raise_()
                    self._sbm_dialog.activateWindow()
                    return
                else:
                    # Dialog was closed previously - reshow it
                    self._sbm_dialog.show()
                    self._sbm_dialog.raise_()
                    self._sbm_dialog.activateWindow()
                    return
            except (RuntimeError, AttributeError):
                self._sbm_dialog = None

        app = self.app
        dlg = SBMLayersDialog(self.sbm_path, self.categories, app=app, parent=None)
        self._sbm_dialog = dlg
        dlg.show()

    def cleanup(self):
        """Close associated SBM dialog and deactivate tools on removal."""
        if self._sbm_dialog is not None:
            try:
                self._sbm_dialog.close()
            except Exception:
                pass
            self._sbm_dialog = None
        app = self.app
        if app is not None:
            app.active_sbm_class = None
            if getattr(app, "active_snt_filename", None) == self.sbm_path.name:
                app.active_snt_layer = None
                app.active_snt_filename = None
                app.active_snt_color = None
            digitizer = getattr(app, "digitizer", None)
            if digitizer is not None:
                try:
                    digitizer.deactivate_all()
                except Exception:
                    pass


