# ─────────────────────────────────────────────────────────────────────────────
# SBM LAYERS DIALOG  — QGIS-style layer tree built from a .sbm file
# ─────────────────────────────────────────────────────────────────────────────


def _rgb_to_true_color_int(r: int, g: int, b: int) -> int:
    """Encode RGB into AutoCAD's 24-bit true color integer (group code 420)."""
    return (int(r) << 16) | (int(g) << 8) | int(b)


def _export_sbm_to_dxf(
    features: Dict[str, List[Dict]],
    out_path: str,
    categories: Optional[List[Dict]] = None,
) -> None:
    """
    Write drawn SBM features to a DXF R2010 file.

    Parameters
    ----------
    features   : {lv_name: [{"type", "vertices"|"position", "closed", "co", "wt"}, ...]}
    out_path   : absolute path to .dxf output file
    categories : optional list from parse_sbm_file() — used to prefix layer names
                 with their category title so DXF viewers show a grouped tree
                 (e.g. "Buildings|M2200_Building" instead of bare "M2200_Building")
    """
    # Build lv → "Category|lv" map from the SBM category tree
    lv_to_dxf_layer: Dict[str, str] = {}
    if categories:
        for cat in categories:
            cat_title = str(cat.get("title", "")).strip()
            for sub in cat.get("subclasses", []):
                lv = str(sub.get("lv", "")).strip()
                if lv and cat_title:
                    lv_to_dxf_layer[lv] = f"{cat_title}|{lv}"
    lines: List[str] = []

    def w(code: int, value) -> None:
        lines.append(f"{code:>3}\n{value}\n")

    # Minimal valid DXF header
    w(0, "SECTION"); w(2, "HEADER")
    w(9, "$ACADVER"); w(1, "AC1015")
    w(0, "ENDSEC")

    # TABLES section — one LAYER entry per SBM subclass
    w(0, "SECTION"); w(2, "TABLES")
    w(0, "TABLE");   w(2, "LAYER")
    w(70, len(features))

    for lv_name, geom_list in features.items():
        if not geom_list:
            continue
        co  = geom_list[0].get("co",  7)
        wt  = geom_list[0].get("wt",  1)
        rgb = geom_list[0].get("rgb", _aci_to_rgb(co))
        dxf_lw = max(13, min(211, wt * 25))
        dxf_lname = lv_to_dxf_layer.get(lv_name, lv_name)  # use prefixed name
        w(0, "LAYER")
        w(2,  dxf_lname)
        w(70, 0)
        w(62, co)
        w(6,  "CONTINUOUS")
        w(370, dxf_lw)
        # Write True Color to LAYER table
        tc = _rgb_to_true_color_int(*rgb)
        w(420, tc)

    w(0, "ENDTAB")
    w(0, "ENDSEC")

    # ENTITIES section
    w(0, "SECTION"); w(2, "ENTITIES")

    for lv_name, geom_list in features.items():
        for feat in geom_list:
            ftype   = str(feat.get("type",  "POLYLINE")).upper()
            co      = feat.get("co",  7)
            vertices = feat.get("vertices") or []
            closed   = bool(feat.get("closed", False))

            dxf_lname = lv_to_dxf_layer.get(lv_name, lv_name)
            tc = _rgb_to_true_color_int(*feat.get("rgb", _aci_to_rgb(co)))

            if ftype == "POINT":
                pos = feat.get("position") or (vertices[0] if vertices else (0, 0, 0))
                w(0,  "POINT")
                w(100, "AcDbEntity")
                w(8,  dxf_lname)
                w(100, "AcDbPoint")
                w(10, pos[0]); w(20, pos[1]); w(30, pos[2] if len(pos) > 2 else 0.0)
                w(62, co)
                w(420, tc)

            elif ftype in ("POLYLINE", "LINE", "POLYGON") and vertices:
                z_vals = {round(v[2] if len(v) > 2 else 0.0, 4) for v in vertices}
                if len(z_vals) == 1:
                    elev = float(next(iter(z_vals)))
                    flags = 1 if closed else 0
                    w(0,   "LWPOLYLINE")
                    w(100, "AcDbEntity")
                    w(8,   dxf_lname)
                    w(100, "AcDbPolyline")
                    w(90,  len(vertices))
                    w(70,  flags)
                    w(38,  elev)
                    w(62,  co)
                    w(420, tc)
                    for v in vertices:
                        w(10, v[0]); w(20, v[1])
                else:
                    pts = vertices + ([vertices[0]] if closed else [])
                    for i in range(len(pts) - 1):
                        a, b = pts[i], pts[i + 1]
                        w(0,  "LINE")
                        w(100, "AcDbEntity")
                        w(8,  dxf_lname)
                        w(100, "AcDbLine")
                        w(10, a[0]); w(20, a[1]); w(30, a[2] if len(a) > 2 else 0.0)
                        w(11, b[0]); w(21, b[1]); w(31, b[2] if len(b) > 2 else 0.0)
                        w(62, co)
                        w(420, tc)

    w(0, "ENDSEC")
    w(0, "EOF")

    with open(out_path, "w", encoding="utf-8") as fh:
        fh.write("".join(lines))


class SBMLayersDialog(QDialog):
    """
    Opens when the user loads a .sbm file from the SNT dialog.

    Shows a QGIS-style collapsible tree:
        ▼ Building        [✓]  3 entities      ← category row: total count + eye toggle
            ■ BUILDING    [✓]  2               ← subclass row: count badge + visibility cb
            ■ ROOF        [✓]  1
        ▼ Road            [✓]  0
            ...

    Column layout (QTreeWidget, 3 columns):
        col 0 — swatch + label
        col 1 — visibility checkbox  (eye icon / checkmark)
        col 2 — entity count badge

    Clicking a subclass row (col 0) sets it as the active SBM class.
    Toggling col 1 hides / shows all drawings that belong to that lv/category.
    Count badge updates every 2 s via a QTimer while the dialog is open.
    """

    class SBMFeature(dict):
        """
        Lightweight wrapper for a drawn SBM feature.

        Expected keys:
            type:    'POINT' | 'POLYLINE' | 'LINE' | 'POLYGON'
            vertices: list of (x, y) or (x, y, z)
            closed:  bool (for polygons / closed polylines)
            co:      colour index (int)
            wt:      lineweight (int)
        """

        def gettype(self, default="POLYLINE"):
            return self.get("type", default)

        def getvertices(self):
            return self.get("vertices", [])

        def getclosed(self, default=False):
            return bool(self.get("closed", default))

        def getco(self, default=7):
            return int(self.get("co", default))

        def getwt(self, default=1):
            return int(self.get("wt", default))

        def getposition(self, default=None):
            """Return a single 3D position for POINT features."""
            if "position" in self:
                return self["position"]
            verts = self.getvertices()
            if verts:
                return verts[0]
            return default

    def __init__(self, sbm_path: Path, categories: List[Dict], app=None, parent=None):
        # Parentless top-level window:
        # avoids Windows desktop mini-bars on minimize for owned dialogs.
        super().__init__(None, Qt.Window)
        self.setAttribute(Qt.WA_QuitOnClose, False)
        self.sbm_path   = sbm_path
        self.categories = categories
        self.app        = app

        self.setWindowTitle(f"SBM Layers — {sbm_path.name}")
        self.setModal(False)
        self.setWindowModality(Qt.NonModal)
        self.resize(460, 600)

        # lv -> bool  (True = visible)
        self._visibility: Dict[str, bool] = {}
        # category title -> bool
        self._cat_visibility: Dict[str, bool] = {}
        # lv -> QTreeWidgetItem  (for fast count refresh)
        self._sub_items: Dict[str, "QTreeWidgetItem"] = {}   # type: ignore[name-defined]
        # cat title -> QTreeWidgetItem
        self._cat_items: Dict[str, "QTreeWidgetItem"] = {}   # type: ignore[name-defined]

        self._active_item = None
        self._init_ui()
        self._populate_tree()
        self._start_refresh_timer()
        # Apply dark title bar on Windows
        try:
            from gui.theme_manager import ThemeManager
            ThemeManager.apply_native_window_theme(self)
        except Exception:
            pass

    # ── stylesheet ────────────────────────────────────────────────────────
    @staticmethod
    def _build_ss():
        c = ThemeColors
        accent = c.get('accent')
        return f"""
        QDialog {{
            background-color: {c.get('bg_primary')};
            color: {c.get('text_primary')};
            font-family: 'Segoe UI', Roboto, sans-serif;
        }}
        QLabel#dlgTitle {{
            color: {c.get('text_primary')};
            font-size: 13px;
            font-weight: 600;
        }}
        QLabel#dlgSub {{
            color: {c.get('text_secondary')};
            font-size: 10px;
        }}
        QLineEdit#searchBox {{
            background-color: {c.get('bg_input')};
            color: {c.get('text_primary')};
            border: 1px solid {c.get('border_light')};
            border-radius: 4px;
            padding: 4px 8px;
            font-size: 11px;
        }}
        QLineEdit#searchBox:focus {{ border-color: {accent}; }}

        QTreeWidget {{
            background-color: {c.get('bg_input')};
            color: {c.get('text_primary')};
            border: 1px solid {c.get('border_light')};
            border-radius: 4px;
            font-size: 11px;
            outline: none;
        }}
        QTreeWidget::item {{
            padding: 2px 4px;
            border: none;
        }}
        QTreeWidget::item:hover {{
            background-color: {c.get('dialog_selection')};
        }}
        QTreeWidget::item:selected {{
            background-color: {c.get('dialog_selection')};
            color: {c.get('text_primary')};
        }}

        QPushButton {{
            background-color: {c.get('bg_secondary')};
            color: {c.get('text_primary')};
            border: 1px solid {c.get('border_light')};
            border-radius: 4px;
            padding: 5px 12px;
            font-size: 11px;
        }}
        QPushButton:hover {{
            background-color: {c.get('bg_button_hover')};
            border-color: {accent};
            color: {accent};
        }}
        QPushButton#closeBtn {{
            background-color: {accent};
            color: #ffffff;
            border-color: {accent};
            font-weight: 600;
        }}
        QPushButton#closeBtn:hover {{
            background-color: {c.get('accent_hover', accent)};
        }}
        QLabel#activeLabel {{
            color: {c.get('success')};
            font-size: 10px;
            font-weight: 600;
        }}
    """

    # ── helpers ───────────────────────────────────────────────────────────

    def _get_drawings(self) -> List[Dict]:
        """Safely return the current drawings list from the digitizer."""
        try:
            return list(getattr(getattr(self.app, "digitizer", None), "drawings", []))
        except Exception:
            return []

    def rebuild_feature_cache(self) -> dict:
        """Rebuild the per-LV features dict from live digitizer drawings.

        Reads self._get_drawings() and groups them by "Category - Subclass"
        key, transforming into the format expected by _export_sbm_to_dxf.
        """
        TYPE_MAP = {
            "smartline":    "POLYLINE",
            "centerline":   "POLYLINE",
            "polyline":     "POLYLINE",
            "line":         "POLYLINE",
            "line_segment": "POLYLINE",
            "freehand":     "POLYLINE",
            "rectangle":    "POLYGON",
            "polygon":      "POLYGON",
            "circle":       "POLYGON",
            "text":         "POINT",
        }
        CLOSED_TYPES = {"rectangle", "polygon", "circle"}

        features: Dict[str, List[Dict]] = {}
        for d in self._get_drawings():
            sc = d.get("sbm_class")
            if not sc:
                continue
            lv = str(sc.get("lv", "")).strip()
            if not lv:
                continue

            cat = str(sc.get("category", "")).strip()
            layer_key = f"{cat} - {lv}" if cat else lv

            dtype = str(d.get("type", "")).lower()
            gtype = TYPE_MAP.get(dtype, "POLYLINE")

            coords = d.get("coords") or []
            if not coords:
                continue

            closed = dtype in CLOSED_TYPES
            co = int(sc.get("co", 7))
            wt = int(sc.get("wt", 1))

            feat: Dict = {
                "type": gtype,
                "vertices": list(coords),
                "closed": closed,
                "co": co,
                "wt": wt,
                "rgb": sc.get("rgb", (255, 255, 255)),
            }
            features.setdefault(layer_key, []).append(feat)

        return features


    def _count_for_lv(self, lv: str) -> int:
        """Count finalized drawings tagged with a given layer value (lv)."""
        lv_upper = lv.upper()
        count = 0
        for d in self._get_drawings():
            sc = d.get("sbm_class")
            if sc and sc.get("lv", "").upper() == lv_upper:
                count += 1
        return count

    def _count_for_category(self, cat: Dict) -> int:
        """Sum counts for all subclasses in a category."""
        return sum(self._count_for_lv(sub["lv"]) for sub in cat.get("subclasses", []))

    def _sbm_layer_name(self, cat: Dict, sub: Dict) -> str:
        category = str(cat.get("title") or "").strip()
        lv = str(sub.get("lv") or sub.get("label") or "").strip()
        if category and lv:
            return f"{category} - {lv}"
        return lv or "SBM"

    def _clear_active_sbm_class(self):
        if self.app is None:
            return
        self.app.active_sbm_class = None
        if getattr(self.app, "active_snt_filename", None) == self.sbm_path.name:
            self.app.active_snt_layer = None
            self.app.active_snt_filename = None
            self.app.active_snt_color = None

    def _set_lv_visibility(self, lv: str, visible: bool):
        """Show/hide all drawings whose sbm_class lv matches."""
        lv_upper = lv.upper()
        self._visibility[lv] = visible
        try:
            for d in self._get_drawings():
                sc = d.get("sbm_class")
                if sc and sc.get("lv", "").upper() == lv_upper:
                    actor = d.get("actor")
                    if actor:
                        actor.SetVisibility(1 if visible else 0)
            self.app.vtk_widget.render()
        except Exception:
            pass

    def _set_cat_visibility(self, cat: Dict, visible: bool):
        """Show/hide all drawings for every subclass in this category."""
        self._cat_visibility[cat["title"]] = visible
        for sub in cat.get("subclasses", []):
            self._visibility[sub["lv"]] = visible
            # update child checkboxes
            child_item = self._sub_items.get(sub["lv"])
            if child_item:
                child_item.setCheckState(0, Qt.Checked if visible else Qt.Unchecked)
        self._set_all_actors_for_cat(cat, visible)

    def _set_all_actors_for_cat(self, cat: Dict, visible: bool):
        lvs = {sub["lv"].upper() for sub in cat.get("subclasses", [])}
        try:
            for d in self._get_drawings():
                sc = d.get("sbm_class")
                if sc and sc.get("lv", "").upper() in lvs:
                    actor = d.get("actor")
                    if actor:
                        actor.SetVisibility(1 if visible else 0)
            self.app.vtk_widget.render()
        except Exception:
            pass

    # ── UI build ──────────────────────────────────────────────────────────

    def _init_ui(self):
        from PySide6.QtWidgets import QTreeWidget, QLineEdit
        self.setStyleSheet(self._build_ss())
        layout = QVBoxLayout(self)
        layout.setContentsMargins(12, 12, 12, 12)
        layout.setSpacing(8)

        # Header
        title = QLabel(f"SBM Layers: {self.sbm_path.name}")
        title.setObjectName("dlgTitle")
        layout.addWidget(title)

        sub = QLabel(f"{sum(len(c['subclasses']) for c in self.categories)} subclasses "
                     f"across {len(self.categories)} categories")
        sub.setObjectName("dlgSub")
        layout.addWidget(sub)

        # Search
        self.search_box = QLineEdit()
        self.search_box.setObjectName("searchBox")
        self.search_box.setPlaceholderText("🔍  Filter subclasses...")
        self.search_box.textChanged.connect(self._apply_filter)
        layout.addWidget(self.search_box)

        # Tree — 2 columns: col 0 = checkbox + swatch + label (stretches),
        #                   col 1 = count badge (fixed, right-aligned)
        # Qt renders the ItemIsUserCheckable checkbox BEFORE the icon in col 0,
        # which gives the QGIS-style: [✓] [■] Label
        self.tree = QTreeWidget()
        self.tree.setHeaderHidden(True)
        self.tree.setColumnCount(2)
        self.tree.setAlternatingRowColors(False)
        self.tree.setAnimated(True)
        self.tree.setIndentation(20)
        self.tree.header().setStretchLastSection(False)
        try:
            from PySide6.QtWidgets import QHeaderView
            self.tree.header().setSectionResizeMode(0, QHeaderView.Stretch)
            self.tree.header().setSectionResizeMode(1, QHeaderView.Fixed)
        except Exception:
            pass
        self.tree.setColumnWidth(1, 40)
        self.tree.itemClicked.connect(self._on_item_clicked)
        self.tree.itemChanged.connect(self._on_item_changed)
        layout.addWidget(self.tree)

        # Active class status bar
        self.active_label = QLabel("No active SBM class selected")
        self.active_label.setObjectName("activeLabel")
        self.active_label.setWordWrap(True)
        layout.addWidget(self.active_label)

        # Footer
        footer = QHBoxLayout()
        expand_btn = QPushButton("Expand All")
        collapse_btn = QPushButton("Collapse All")
        deactivate_btn = QPushButton("Deactivate")
        deactivate_btn.setToolTip("Stop tagging new drawings with the active SBM class")
        deactivate_btn.clicked.connect(self._deactivate_sbm_class)
        export_btn = QPushButton("Export")
        close_btn = QPushButton("Close")
        export_btn.setObjectName("exportDxfBtn")
        export_btn.setToolTip("Export all drawn SBM features to DXF, Shapefile, GeoTIFF, or SNT")
        expand_btn.clicked.connect(self.tree.expandAll)
        collapse_btn.clicked.connect(self.tree.collapseAll)
        export_btn.clicked.connect(self._on_export)
        close_btn.setObjectName("closeBtn")
        close_btn.clicked.connect(self.accept)
        footer.addWidget(expand_btn)
        footer.addWidget(collapse_btn)
        footer.addWidget(deactivate_btn)
        footer.addStretch()
        footer.addWidget(export_btn)
        footer.addWidget(close_btn)
        layout.addLayout(footer)

    def _populate_tree(self):
        from PySide6.QtWidgets import QTreeWidgetItem
        self.tree.blockSignals(True)
        self.tree.clear()
        self._sub_items.clear()
        self._cat_items.clear()

        for cat in self.categories:
            if not cat.get("subclasses"):
                continue

            cat_title = cat["title"]
            self._cat_visibility.setdefault(cat_title, True)
            cat_count = self._count_for_category(cat)

            parent_item = QTreeWidgetItem(self.tree)
            parent_item.setText(0, f"  {cat_title}")
            parent_item.setData(0, Qt.UserRole, {"_type": "category", "cat": cat})
            parent_item.setFlags(
                parent_item.flags() | Qt.ItemIsUserCheckable
            )
            parent_item.setCheckState(
                0, Qt.Checked if self._cat_visibility[cat_title] else Qt.Unchecked
            )
            parent_item.setText(1, str(cat_count) if cat_count else "")

            font = parent_item.font(0)
            font.setBold(True)
            font.setPointSize(10)
            parent_item.setFont(0, font)
            parent_item.setForeground(0, QColor(80, 80, 80))

            parent_item.setForeground(1, QColor(100, 100, 100))
            parent_item.setTextAlignment(1, Qt.AlignRight | Qt.AlignVCenter)

            self._cat_items[cat_title] = parent_item

            for sub in cat["subclasses"]:
                lv = sub["lv"]
                self._visibility.setdefault(lv, True)
                sub_count = self._count_for_lv(lv)

                child = QTreeWidgetItem(parent_item)
                r, g, b = sub["rgb"]

                # color swatch
                pix = QPixmap(14, 14)
                pix.fill(Qt.transparent)
                painter = QPainter(pix)
                painter.setRenderHint(QPainter.Antialiasing, True)
                painter.setBrush(QColor(r, g, b))
                painter.setPen(QColor(80, 80, 80))
                painter.drawRect(1, 1, 12, 12)
                painter.end()

                child.setIcon(0, QIcon(pix))
                child.setText(0, sub["label"].title())
                child.setData(0, Qt.UserRole, {"_type": "subclass", "sub": sub, "cat": cat})
                child.setFlags(child.flags() | Qt.ItemIsUserCheckable)
                child.setCheckState(
                    0, Qt.Checked if self._visibility[lv] else Qt.Unchecked
                )

                # count badge in col 1
                child.setText(1, str(sub_count) if sub_count else "")
                child.setForeground(1, QColor(37, 99, 235))   # blue count
                child.setTextAlignment(1, Qt.AlignRight | Qt.AlignVCenter)

                self._sub_items[lv] = child

            parent_item.setExpanded(True)

        self.tree.blockSignals(False)

    # ── live count refresh ────────────────────────────────────────────────

    def _start_refresh_timer(self):
        try:
            from PySide6.QtCore import QTimer
        except ImportError:
            from PyQt5.QtCore import QTimer
        self._refresh_timer = QTimer(self)
        self._refresh_timer.setInterval(2000)   # refresh every 2 s
        self._refresh_timer.timeout.connect(self._refresh_counts)
        self._refresh_timer.start()

    def _refresh_counts(self):
        """Update count badges without rebuilding the tree."""
        self.tree.blockSignals(True)
        try:
            for cat in self.categories:
                if not cat.get("subclasses"):
                    continue
                cat_total = 0
                for sub in cat["subclasses"]:
                    lv = sub["lv"]
                    n = self._count_for_lv(lv)
                    cat_total += n
                    item = self._sub_items.get(lv)
                    if item:
                        item.setText(1, str(n) if n else "")
                cat_item = self._cat_items.get(cat["title"])
                if cat_item:
                    cat_item.setText(1, str(cat_total) if cat_total else "")
        except Exception:
            pass
        finally:
            self.tree.blockSignals(False)

    # ── signal handlers ───────────────────────────────────────────────────

    def _on_item_changed(self, item, column):
        """Handle checkbox toggle in column 0."""
        if column != 0:
            return
        data = item.data(0, Qt.UserRole)
        if not data:
            return
        checked = item.checkState(0) == Qt.Checked

        if data.get("_type") == "subclass":
            sub = data["sub"]
            self._set_lv_visibility(sub["lv"], checked)

        elif data.get("_type") == "category":
            cat = data["cat"]
            # block signals to avoid recursive _on_item_changed
            self.tree.blockSignals(True)
            self._set_cat_visibility(cat, checked)
            self.tree.blockSignals(False)

    def _on_item_clicked(self, item, column):
        """Col 0 click → toggle active SBM class on/off."""
        if column != 0:
            return
        data = item.data(0, Qt.UserRole)
        if not data or data.get("_type") != "subclass":
            return

        sub = data["sub"]
        cat = data["cat"]
        lv = sub["lv"]

        if self.app is None:
            return

        currently_active = getattr(self.app, "active_sbm_class", None) or {}
        is_already_active = currently_active.get("lv") == lv

        if is_already_active:
            self._clear_active_sbm_class()
            self.active_label.setText("No active SBM class selected")
            self.active_label.setStyleSheet(
                "color: #888888; font-size: 10px; font-weight: 400;"
            )
        else:
            layer_name = self._sbm_layer_name(cat, sub)
            self.app.active_sbm_class = {
                "label":    sub["label"],
                "lv":       sub["lv"],
                "co":       sub["co"],
                "wt":       sub["wt"],
                "collect":  sub["collect"],
                "rgb":      sub["rgb"],
                "category": cat["title"],
                "layer":    layer_name,
            }
            self.app.active_snt_layer = layer_name
            self.app.active_snt_filename = self.sbm_path.name
            self.app.active_snt_color = sub["rgb"]
            r, g, b = sub["rgb"]
            self.active_label.setText(
                f"🎯  Active: [{cat['title']}] → {sub['label']}  "
                f"(CO={sub['co']}, WT={sub['wt']}, {sub['collect']})"
            )
            self.active_label.setStyleSheet(
                f"color: rgb({r},{g},{b}); font-size: 10px; font-weight: 600;"
            )

    def _deactivate_sbm_class(self):
        """Clear the active SBM class so new drawings are unclassified."""
        self._clear_active_sbm_class()
        self.active_label.setText("No active SBM class selected")
        self.active_label.setStyleSheet(
            "color: #888888; font-size: 10px; font-weight: 400;"
        )

    def _apply_filter(self, text: str):
        text = text.strip().lower()
        for i in range(self.tree.topLevelItemCount()):
            cat_item = self.tree.topLevelItem(i)
            any_visible = False
            for j in range(cat_item.childCount()):
                child = cat_item.child(j)
                label = child.text(0).strip().lower()
                visible = (not text) or (text in label)
                child.setHidden(not visible)
                if visible:
                    any_visible = True
            cat_item.setHidden(not any_visible and bool(text))
            if any_visible:
                cat_item.setExpanded(True)

    # ── EXPORT ─────────────────────────────────────────────────────────

    def _on_export(self) -> None:
        """Show format selection dialog and export drawn SBM features."""
        from PySide6.QtWidgets import QRadioButton, QDialogButtonBox

        features = self.rebuild_feature_cache()

        dialog = QDialog(self)
        dialog.setWindowTitle("Export Drawings")
        dialog.setModal(True)
        dialog.setStyleSheet(self._build_ss())

        layout = QVBoxLayout(dialog)

        dxf_radio = QRadioButton("DXF (SBM Layers)")
        dxf_radio.setChecked(True)
        shp_radio = QRadioButton("Shapefile")
        tiff_radio = QRadioButton("GeoTIFF")
        snt_radio = QRadioButton("SNT (All Visible Vectors)")

        layout.addWidget(dxf_radio)
        layout.addWidget(shp_radio)
        layout.addWidget(tiff_radio)
        layout.addWidget(snt_radio)

        buttons = QDialogButtonBox(
            QDialogButtonBox.Ok | QDialogButtonBox.Cancel
        )
        ok_btn = buttons.button(QDialogButtonBox.Ok)
        cancel_btn = buttons.button(QDialogButtonBox.Cancel)
        if ok_btn:
            ok_btn.setObjectName("primaryBtn")
            ok_btn.setAutoDefault(False)
            ok_btn.setDefault(False)
            ok_btn.setFocusPolicy(Qt.NoFocus)
        if cancel_btn:
            cancel_btn.setAutoDefault(False)
            cancel_btn.setDefault(False)
            cancel_btn.setFocusPolicy(Qt.NoFocus)
        buttons.accepted.connect(dialog.accept)
        buttons.rejected.connect(dialog.reject)
        layout.addWidget(buttons)

        if dialog.exec() != QDialog.Accepted:
            return

        app = self.app
        if dxf_radio.isChecked():
            self._export_dxf(features)
        elif shp_radio.isChecked():
            self._export_shapefile(app)
        elif tiff_radio.isChecked():
            self._export_geotiff(app)
        elif snt_radio.isChecked():
            self._export_snt(app)

    def _export_dxf(self, features: dict) -> None:
        if not features:
            QMessageBox.information(
                self, "No Drawn Features",
                "No digitized features found.\n"
                "Draw some features using the SBM layer panel first.",
            )
            return

        selected_lvs = self._show_layer_selection_dialog(features, "DXF")
        if selected_lvs is None:
            return

        filtered = {lv: feats for lv, feats in features.items() if lv in selected_lvs}
        if not filtered:
            QMessageBox.information(
                self, "No Layers Selected",
                "No layers were selected for export.",
            )
            return

        path, _ = QFileDialog.getSaveFileName(
            self, "Export SBM Features to DXF", "",
            "AutoCAD DXF (*.dxf);;All Files (*)",
        )
        if not path:
            return
        if not path.lower().endswith(".dxf"):
            path += ".dxf"

        try:
            _export_sbm_to_dxf(filtered, path, categories=self.categories)
            total = sum(len(v) for v in filtered.values())
            QMessageBox.information(
                self, "Export Successful",
                f"Exported {total} feature(s) across {len(filtered)} layer(s)\n→ {path}",
            )
        except Exception as exc:
            QMessageBox.critical(self, "Export Failed", f"Could not write DXF:\n{exc}")

    def _show_layer_selection_dialog(self, features: dict, format_name: str = "DXF"):
        """Show a tree with checkboxes for each SBM layer. Returns set of
        selected LV names, or None if cancelled."""
        from PySide6.QtWidgets import (
            QTreeWidget, QTreeWidgetItem, QCheckBox, QPushButton,
            QDialogButtonBox,
        )

        dlg = QDialog(self)
        dlg.setWindowTitle(f"Select Layers for {format_name} Export")
        dlg.setModal(True)
        dlg.setStyleSheet(self._build_ss())
        dlg.resize(420, 520)

        layout = QVBoxLayout(dlg)

        lbl = QLabel(f"Select which layers to include in the {format_name} export:")
        lbl.setObjectName("dlgSub")
        layout.addWidget(lbl)

        sel_all = QPushButton("Select All")
        desel_all = QPushButton("Deselect All")
        sel_all.setAutoDefault(False)
        desel_all.setAutoDefault(False)
        btn_row = QHBoxLayout()
        btn_row.addWidget(sel_all)
        btn_row.addWidget(desel_all)
        btn_row.addStretch()
        layout.addLayout(btn_row)

        tree = QTreeWidget()
        tree.setHeaderHidden(True)
        tree.setColumnCount(2)
        tree.setAnimated(True)
        tree.setIndentation(20)
        tree.header().setStretchLastSection(False)
        try:
            from PySide6.QtWidgets import QHeaderView
            tree.header().setSectionResizeMode(0, QHeaderView.Stretch)
            tree.header().setSectionResizeMode(1, QHeaderView.Fixed)
        except Exception:
            pass
        tree.setColumnWidth(1, 50)

        all_sub_items: List[QTreeWidgetItem] = []

        for cat in self.categories:
            subs = cat.get("subclasses", [])
            if not subs:
                continue

            parent = QTreeWidgetItem(tree)
            parent.setText(0, f"  {cat['title']}")
            parent.setFlags(parent.flags() & ~Qt.ItemIsSelectable)
            font = parent.font(0)
            font.setBold(True)
            font.setPointSize(10)
            parent.setFont(0, font)
            parent.setForeground(0, QColor(80, 80, 80))

            cat_count = 0
            for sub in subs:
                lv = sub["lv"]
                cat_title = cat.get("title", "")
                layer_key = f"{cat_title} - {lv}" if cat_title else lv
                count = len(features.get(layer_key, []))
                cat_count += count

                child = QTreeWidgetItem(parent)
                r, g, b = sub["rgb"]
                pix = QPixmap(14, 14)
                pix.fill(Qt.transparent)
                painter = QPainter(pix)
                painter.setRenderHint(QPainter.Antialiasing, True)
                painter.setBrush(QColor(r, g, b))
                painter.setPen(QColor(80, 80, 80))
                painter.drawRect(1, 1, 12, 12)
                painter.end()
                child.setIcon(0, QIcon(pix))
                child.setText(0, sub["label"].title())
                child.setText(1, str(count) if count else "")
                child.setForeground(1, QColor(100, 100, 100))
                child.setTextAlignment(1, Qt.AlignRight | Qt.AlignVCenter)

                checked = self._visibility.get(lv, True) and layer_key in features
                child.setCheckState(0, Qt.Checked if checked else Qt.Unchecked)
                child.setData(0, Qt.UserRole, layer_key)
                all_sub_items.append(child)

            parent.setText(1, str(cat_count) if cat_count else "")
            parent.setForeground(1, QColor(100, 100, 100))
            parent.setTextAlignment(1, Qt.AlignRight | Qt.AlignVCenter)
            parent.setExpanded(True)

        layout.addWidget(tree)

        def select_all():
            for item in all_sub_items:
                item.setCheckState(0, Qt.Checked)

        def deselect_all():
            for item in all_sub_items:
                item.setCheckState(0, Qt.Unchecked)

        sel_all.clicked.connect(select_all)
        desel_all.clicked.connect(deselect_all)

        buttons = QDialogButtonBox(QDialogButtonBox.Ok | QDialogButtonBox.Cancel)
        ok_btn = buttons.button(QDialogButtonBox.Ok)
        cancel_btn = buttons.button(QDialogButtonBox.Cancel)
        if ok_btn:
            ok_btn.setObjectName("primaryBtn")
            ok_btn.setAutoDefault(False)
            ok_btn.setDefault(False)
        if cancel_btn:
            cancel_btn.setAutoDefault(False)
            cancel_btn.setDefault(False)
        buttons.accepted.connect(dlg.accept)
        buttons.rejected.connect(dlg.reject)
        layout.addWidget(buttons)

        if dlg.exec() != QDialog.Accepted:
            return None

        selected = set()
        for item in all_sub_items:
            if item.checkState(0) == Qt.Checked:
                lv = item.data(0, Qt.UserRole)
                if lv:
                    selected.add(lv)
        return selected

    def _export_shapefile(self, app) -> None:
        try:
            from gui.vector_export import export_drawings_to_shapefile
        except ImportError:
            QMessageBox.critical(self, "Error", "vector_export module not available.")
            return

        features = self.rebuild_feature_cache()
        selected_lvs = self._show_layer_selection_dialog(features, "Shapefile")
        if selected_lvs is None:
            return

        path, _ = QFileDialog.getSaveFileName(
            self, "Export Drawings to Shapefile", "",
            "Shapefile (*.shp)",
        )
        if not path:
            return
        if not path.lower().endswith(".shp"):
            path += ".shp"

        original_drawings = self._filter_drawings_for_export(selected_lvs)
        try:
            ok = export_drawings_to_shapefile(app, path)
            if ok:
                QMessageBox.information(self, "Export Successful", f"Exported to:\n{path}")
            else:
                QMessageBox.warning(self, "Export Failed", "Export returned False. Check console.")
        except Exception as exc:
            QMessageBox.critical(self, "Export Failed", f"Could not write Shapefile:\n{exc}")
        finally:
            self._restore_drawings_after_export(original_drawings)

    def _export_geotiff(self, app) -> None:
        try:
            from gui.vector_export import export_drawings_to_tiff
        except ImportError:
            QMessageBox.critical(self, "Error", "vector_export module not available.")
            return

        features = self.rebuild_feature_cache()
        selected_lvs = self._show_layer_selection_dialog(features, "GeoTIFF")
        if selected_lvs is None:
            return

        path, _ = QFileDialog.getSaveFileName(
            self, "Export Drawings to GeoTIFF", "",
            "GeoTIFF Files (*.tif *.tiff)",
        )
        if not path:
            return
        if not path.lower().endswith((".tif", ".tiff")):
            path += ".tif"

        original_drawings = self._filter_drawings_for_export(selected_lvs)
        try:
            ok = export_drawings_to_tiff(app, path)
            if ok:
                QMessageBox.information(self, "Export Successful", f"Exported to:\n{path}")
            else:
                QMessageBox.warning(self, "Export Failed", "Export returned False. Check console.")
        except Exception as exc:
            QMessageBox.critical(self, "Export Failed", f"Could not write GeoTIFF:\n{exc}")
        finally:
            self._restore_drawings_after_export(original_drawings)

    def _export_snt(self, app) -> None:
        try:
            from gui.vector_export import export_visible_vectors_to_snt, _resolve_snt_export_output_path
        except ImportError:
            QMessageBox.critical(self, "Error", "vector_export module not available.")
            return

        features = self.rebuild_feature_cache()
        selected_lvs = self._show_layer_selection_dialog(features, "SNT")
        if selected_lvs is None:
            return

        from pathlib import Path as _Path
        if hasattr(app, 'last_save_path') and app.last_save_path:
            base_dir = _Path(app.last_save_path).parent
            base_name = _Path(app.last_save_path).stem
        else:
            base_dir = _Path.home()
            base_name = "drawings"

        output_path = _resolve_snt_export_output_path(app, base_dir, base_name)
        if not output_path:
            return

        original_drawings = self._filter_drawings_for_export(selected_lvs)
        try:
            ok = export_visible_vectors_to_snt(app, output_path)
            if ok:
                summary = getattr(app, "_last_snt_export_summary", None) or {}
                entities = summary.get("backend_entities", 0)
                layers = summary.get("backend_layers", 0)
                QMessageBox.information(
                    self, "Export Successful",
                    f"Exported to SNT:\n{_Path(output_path).with_suffix('.snt')}\n\n"
                    f"Entities: {int(entities):,}\nLayers: {int(layers):,}",
                )
            else:
                QMessageBox.warning(self, "Export Failed", "Export returned False. Check console.")
        except Exception as exc:
            QMessageBox.critical(self, "Export Failed", f"Could not write SNT:\n{exc}")
        finally:
            self._restore_drawings_after_export(original_drawings)

    def _filter_drawings_for_export(self, selected_lvs: set) -> list:
        """Temporarily replace app.digitizer.drawings with only drawings
        whose sbm_class layer key is in selected_lvs, and tag each drawing
        with a 'layer' attribute so vector_export writes per-layer DXF/SNT/Shapefile.

        Returns original list for restore."""
        digitizer = getattr(self.app, "digitizer", None)
        if digitizer is None:
            return []
        original = list(digitizer.drawings)
        filtered = []
        for d in original:
            sc = d.get("sbm_class") or {}
            lv = sc.get("lv", "")
            cat = sc.get("category", "")
            layer_key = f"{cat} - {lv}" if cat else lv
            if layer_key not in selected_lvs:
                continue
            d["layer"] = layer_key
            filtered.append(d)
        digitizer.drawings[:] = filtered
        return original

    def _restore_drawings_after_export(self, original_drawings: list):
        """Restore the original drawings list after export and clean up
        temporary 'layer' tags added during filtering."""
        digitizer = getattr(self.app, "digitizer", None)
        if digitizer is not None:
            for d in original_drawings:
                d.pop("layer", None)
            digitizer.drawings[:] = original_drawings

    def closeEvent(self, event):
        """Stop the refresh timer, deactivate tools, and clear active SBM class on close.
        
        The dialog instance is kept alive by the SBMFileItem so clicking
        'Layers' again will reshow this same dialog.
        """
        try:
            self._refresh_timer.stop()
        except Exception:
            pass
        if self.app is not None:
            self._clear_active_sbm_class()
            # Deactivate any active digitizer tool
            digitizer = getattr(self.app, "digitizer", None)
            if digitizer is not None:
                try:
                    digitizer.deactivate_all()
                except Exception:
                    pass
        super().closeEvent(event)

    def showEvent(self, event):
        """Restart the refresh timer when the dialog is (re)shown."""
        super().showEvent(event)
        try:
            if hasattr(self, '_refresh_timer') and not self._refresh_timer.isActive():
                self._refresh_timer.start()
        except Exception:
            pass

class MultiSNTAttachmentDialog(MinimizableDialogMixin, QDialog):
    """
    Dialog for attaching multiple SNT overlay files.
    """

    # A QVariantList signal recursively converts/copies the entire attachment,
    # including millions of entity dicts and vertices, on the GUI thread.
    # Receivers need the shared Python document, not a second Qt-owned model.
    snt_attached = Signal(object)

    def __init__(self, app, parent=None):
        target_parent = None
        if isinstance(parent, QWidget):
            target_parent = parent
        elif isinstance(app, QWidget):
            target_parent = app
        elif hasattr(app, "window") and isinstance(app.window, QWidget):
            target_parent = app.window

        # Parentless top-level window:
        # avoids Windows desktop mini-bars on minimize for owned dialogs.
        super().__init__(None, Qt.Window)
        self._init_minimize_state()        
        self.setAttribute(Qt.WA_QuitOnClose, False)
        self.setWindowModality(Qt.NonModal)
        self.app             = app
        self._dialog_guard_host = None
        self._dialog_guard_app = None
        # NOTE: `self.snt_items` is a MIXED list of SNTFileItem and SBMFileItem
        # row widgets. The two pipelines are intentionally separate, but they
        # share this one list because the file-list UI shows both kinds of rows
        # in the same vertical layout. Always iterate via the typed helpers
        # `_iter_snt_file_items()` and `_iter_sbm_file_items()` rather than
        # looping over `self.snt_items` directly, to avoid any cross-pipeline
        # attribute access.
        self.snt_items:      List[QWidget]           = []
        self._load_worker:   Optional[SNTLoadWorker] = None  # SNT-only worker (SBM browse is sync)
        self._attach_worker: Optional[SNTAttachWorker] = None  # background Attach decoder
        self._close_requested_while_loading = False
        self._labels_hidden: bool = False
        self.setProperty("themeStyledDialog", True)
        self._install_dialog_zorder_guard()

        self.setWindowTitle("Attach SNT Files - NakshaApp Native Format")
        self.setStyleSheet(get_dialog_stylesheet())
        self.setGeometry(150, 150, 720, 800)
        self._init_ui()

    def _install_dialog_zorder_guard(self):
        host = self.app if isinstance(self.app, QWidget) else None
        if host is None:
            return
        if host is self._dialog_guard_host:
            return
        try:
            host.installEventFilter(self)
            from PySide6.QtWidgets import QApplication
            app_instance = QApplication.instance()
            if app_instance is not None and app_instance is not self._dialog_guard_app:
                app_instance.installEventFilter(self)
                self._dialog_guard_app = app_instance
            self._dialog_guard_host = host
            print("✅ MultiSNTAttachmentDialog: z-order guard installed")
        except Exception as e:
            print(f"⚠️ MultiSNTAttachmentDialog: z-order guard install failed: {e}")

    def _refresh_dialog_zorder(self):
        try:
            if self.isHidden() or not self.isVisible():
                return
            if self.isMinimized() or self._is_minimized_to_chip:
                return
            self.raise_()
        except Exception:
            pass

    def eventFilter(self, obj, event):
        try:
            if event is None:
                return super().eventFilter(obj, event)
            host = self._dialog_guard_host
            if host is not None:
                et = event.type()
                is_host_event = (obj is host)
                is_host_child_event = (
                    isinstance(obj, QWidget) and
                    (obj is host or host.isAncestorOf(obj))
                )
                if et == QEvent.WindowActivate and is_host_event:
                    self._refresh_dialog_zorder()
                elif et in (QEvent.FocusIn, QEvent.MouseButtonPress) and is_host_child_event:
                    self._refresh_dialog_zorder()
        except Exception:
            pass
        return super().eventFilter(obj, event)

    def _init_ui(self):
        layout = QVBoxLayout(self)
        layout.setContentsMargins(15, 15, 15, 15)
        layout.setSpacing(12)

        # 1. Main Title
        self.title_label = QLabel("Attach SNT Files (NakshaApp Native Format)")
        self.title_label.setAlignment(Qt.AlignCenter)
        self.title_label.setStyleSheet(get_title_banner_style())
        layout.addWidget(self.title_label)

        # 2. Info Banner
        self.info_label = QLabel(
            "SNT loads 10-50x faster than DXF  |  "
            "Colours & layers preserved  |  Grid pipeline fully compatible")
        self.info_label.setAlignment(Qt.AlignCenter)
        self.info_label.setStyleSheet(get_notice_banner_style("info"))
        layout.addWidget(self.info_label)

        # 3. File Selection Group
        file_group = QGroupBox("Select SNT Files")
        file_layout = QVBoxLayout()

        # Row layout to hold both buttons side by side
        browse_row = QHBoxLayout()
        browse_row.setSpacing(10)

        # --- SNT button (existing behaviour) ---
        self.browse_btn = QPushButton("Browse SNT")
        self.browse_btn.setObjectName("secondaryBtn")
        self.browse_btn.setMinimumHeight(45)
        self.browse_btn.setAutoDefault(False)
        self.browse_btn.setDefault(False)
        self.browse_btn.setFocusPolicy(Qt.NoFocus)
        self.browse_btn.clicked.connect(self._select_snt_files)
