        self.browse_sbm_btn.setMinimumHeight(45)
        self.browse_sbm_btn.setAutoDefault(False)
        self.browse_sbm_btn.setDefault(False)
        self.browse_sbm_btn.setFocusPolicy(Qt.NoFocus)
        self.browse_sbm_btn.setToolTip("Load an .sbm layer-definition file for class-based digitizing")
        self.browse_sbm_btn.clicked.connect(self._browse_sbm_file)
        browse_row.addWidget(self.browse_sbm_btn, 1)

        file_layout.addLayout(browse_row)
        file_group.setLayout(file_layout)
